//
// The Perform pane: cents against time, with the lane a singer can actually aim
// into.
//
// WHY THIS PANE EXISTS AT ALL. The spectrogram's lane is exact and 2.8 px wide
// (see `waterfall-overlay.ts`), because a four-octave frequency axis cannot
// show a hundredth of a semitone. So the axis changes: y is CENTS relative to a
// centre, ±200 of them, and the same ±10-cent lane is ~15 px tall on a 300 px
// pane. Sing Sharp, Vanido, Yousician and Sing&See all draw exactly this
// picture — a target lane and a live trace entering it — and the survey behind
// the layout plan found no singing app that asks a singer to read pitch off a
// log-frequency spectrogram.
//
// THE CENTRE, AND WHY IT HAS HYSTERESIS. With a captured reference the centre
// IS the reference: the lane sits in the middle and the strip is a tuner. With
// none, the centre is the nearest equal-tempered note of the most recent voiced
// f0 — and it only moves when the voice leaves ±100 cents of it. Without that
// hysteresis a singer sitting 51 cents flat would see the whole strip jump a
// semitone every few frames, i.e. the display would be unstable exactly where
// the singing is; Cleartune and Pano Tuner both ship the same idea as needle
// damping. `(prov.)`, both numbers: a taste call, not a measurement.
//
// TIME RUNS RIGHT, newest at the right edge — the direction a phrase is read
// in, and the direction every app in the survey scrolls. The spectrogram runs
// downward for its own reason (`index.html` says so) and the two are allowed to
// differ: one is a record of a spectrum, the other is a line a singer is
// following.
//
// NOTHING HERE IS SMOOTHED, AND NOTHING HERE IS MEASURED. `cents()` is
// `dsp/cents.ts`'s, the lane is `reference.ts`'s, the row index is the
// spectrogram's. This file maps three given numbers to pixels.
// ---------------------------------------------------------------------------

import { cents, formatCents, noteHz, noteName } from '../dsp/cents';
import type { Lane } from '../app/reference';
import { PLOT_GUTTER, plotWidthFor } from './axis';
import { readSpectrumPalette, type CanvasPalette } from './palette';
import { browserRafHost, createFrameScheduler, type FrameScheduler, type RafHost } from './scheduler';
import { createTraceRing } from './trace-ring';
import { hatchRect, LANE_DECORATION } from './waterfall-overlay';
import { HISTORY_ROWS } from './waterfall-view';

/**
 * Half the visible range, in cents. `(prov.)`
 *
 * ±200 is two semitones: wide enough that an octave-and-a-bit of vibrato and a
 * scooped onset stay on the pane, narrow enough that a ±10-cent lane is still
 * a band rather than a line. A zoom control is a later step.
 */
export const SPAN_CENTS = 200;

/**
 * How far the voice may wander before the strip re-centres, in cents. `(prov.)`
 * Half a semitone: the point at which the nearest note changes anyway.
 */
export const HYSTERESIS_CENTS = 100;

/** Vertical breathing room so the ±200 labels are not clipped by the edges. */
const PADDING = { top: 8, bottom: 8 } as const;

/** The cents gridlines that get a label. 0 carries the note name instead. */
const GRID_CENTS = [50, 100, 200] as const;

const STROKE = { casing: 3.5, trace: 1.75, edge: 1 } as const;
const WASH = { inTune: 0.16, near: 0.1 } as const;
const LABEL_FONT = '10px ui-monospace, "DejaVu Sans Mono", monospace';
const NOTE_FONT = '600 12px ui-monospace, "DejaVu Sans Mono", monospace';

export interface PitchStripState {
  readonly centreHz: number | null;
  /** `A3`, or `null` before anything voiced has arrived. */
  readonly centreNote: string | null;
  readonly spanCents: number;
  readonly laneInTuneCents: number | null;
  readonly laneNearCents: number | null;
  /** The in-tune edges in CSS y, `[top, bottom]`. `null` with no lane. */
  readonly laneInTunePx: readonly [number, number] | null;
  /** Voiced rows in the ring — the points the polyline is made of. */
  readonly tracePoints: number;
  /** The newest voiced reading, in cents from the centre. */
  readonly lastTraceCents: number | null;
}

export interface PitchStrip {
  /** Record the f0 of the spectrogram row `row`, and request a repaint. */
  push(row: number, f0Hz: number | null): void;
  setLane(lane: Lane | null): void;
  setPalette(palette: CanvasPalette): void;
  resize(): void;
  state(): PitchStripState;
  destroy(): void;
}

/**
 * Where the strip should be centred, given where it is centred now.
 *
 * `null` in, `null` out: an unvoiced frame never moves the centre — a strip
 * that recentred on silence would drift to whatever the last breath was. With
 * no previous centre the first voiced frame snaps to its nearest equal-tempered
 * note; after that the centre only moves when the voice leaves the band.
 *
 * The centre is always a NOTE, never the raw f0, so the 0 line means "the note"
 * and a singer holding 20 cents sharp sees a line 20 cents above the middle
 * rather than a middle that quietly followed them up.
 */
export function centreFor(
  previousCentreHz: number | null,
  f0Hz: number | null,
  hysteresisCents: number = HYSTERESIS_CENTS,
): number | null {
  if (f0Hz === null || !(f0Hz > 0) || !Number.isFinite(f0Hz)) {
    return previousCentreHz;
  }
  if (previousCentreHz !== null && Math.abs(cents(f0Hz, previousCentreHz)) <= hysteresisCents) {
    return previousCentreHz;
  }
  const note = noteName(f0Hz);
  return note === null ? previousCentreHz : noteHz(note.midi);
}

/**
 * Cents → CSS y. `+spanCents` at the top of the plot, `−spanCents` at the
 * bottom: sharp is up, the direction every tuner in the survey draws it.
 *
 * Deliberately NOT clamped. A reading 400 cents off leaves the pane, and that
 * is the honest picture — clamping it to the edge would draw a line at −200
 * cents for a singer who is a third of an octave away.
 */
export function centsToY(
  centsValue: number,
  spanCents: number,
  plotTop: number,
  plotHeight: number,
): number {
  return plotTop + (plotHeight * (spanCents - centsValue)) / (2 * spanCents);
}

/**
 * The x of the row `age` rows behind the newest: newest at the RIGHT edge, one
 * column per ring row, `+ 0.5` for the column centre — the same convention the
 * spectrogram's rows use vertically.
 */
export function ageXOf(
  age: number,
  plotLeft: number,
  plotWidth: number,
  rows: number = HISTORY_ROWS,
): number {
  return plotLeft + plotWidth - ((age + 0.5) * plotWidth) / rows;
}

export function createPitchStrip(
  canvas: HTMLCanvasElement,
  palette: CanvasPalette = readSpectrumPalette(canvas),
  host: RafHost = browserRafHost(canvas.ownerDocument.defaultView ?? window),
): PitchStrip {
  const context = ((): CanvasRenderingContext2D => {
    const found = canvas.getContext('2d');
    if (found === null) {
      throw new Error('this browser did not give a 2d context for the pitch strip');
    }
    return found;
  })();

  let currentPalette = palette;
  let currentLane: Lane | null = null;
  let centreHz: number | null = null;
  let cssWidth = canvas.clientWidth > 0 ? canvas.clientWidth : canvas.width;
  let cssHeight = canvas.clientHeight > 0 ? canvas.clientHeight : canvas.height;
  let backingDpr = 1;
  const ring = createTraceRing(HISTORY_ROWS);
  let paintSeq = 0;

  function plot(): { x: number; y: number; w: number; h: number } {
    return {
      x: PLOT_GUTTER.left,
      y: PADDING.top,
      w: plotWidthFor(cssWidth),
      h: Math.max(1, cssHeight - PADDING.top - PADDING.bottom),
    };
  }

  function yOf(centsValue: number): number {
    const { y, h } = plot();
    return centsToY(centsValue, SPAN_CENTS, y, h);
  }

  /**
   * The lane's offset from the strip's centre, in cents.
   *
   * Zero whenever a lane is installed — the centre IS the lane's centre — but
   * computed rather than assumed, so a caller who sets a lane and a centre that
   * disagree gets a band in the right place instead of a band that lies.
   */
  function laneOffsetCents(lane: Lane): number | null {
    return centreHz === null ? null : cents(lane.centreHz, centreHz);
  }

  /** A horizontal band between two cents values, washed and optionally hatched. */
  function band(fromCents: number, toCents: number, colour: string, wash: number, hatch: boolean): void {
    const { x, w } = plot();
    const top = yOf(Math.max(fromCents, toCents));
    const bottom = yOf(Math.min(fromCents, toCents));
    context.save();
    context.globalAlpha = wash;
    context.fillStyle = colour;
    context.fillRect(x, top, w, bottom - top);
    context.globalAlpha = 1;
    if (hatch && bottom - top >= LANE_DECORATION.hatchMinPx) {
      context.globalAlpha = 0.5;
      context.strokeStyle = colour;
      context.lineWidth = 1;
      hatchRect(context, x, top, w, bottom - top);
    }
    context.restore();
  }

  /** A horizontal line across the plot, cased or bare. */
  function laneEdge(centsValue: number, cased: boolean): void {
    const { x, w } = plot();
    const y = yOf(centsValue);
    const draw = (): void => {
      context.beginPath();
      context.moveTo(x, y);
      context.lineTo(x + w, y);
      context.stroke();
    };
    if (cased) {
      context.strokeStyle = currentPalette.overlayCasing;
      context.lineWidth = STROKE.edge + 2;
      draw();
    }
    context.strokeStyle = currentPalette.lane;
    context.lineWidth = STROKE.edge;
    draw();
  }

  function drawGrid(): void {
    const { x, w } = plot();
    context.save();
    context.font = LABEL_FONT;
    context.textAlign = 'right';
    context.textBaseline = 'middle';
    context.lineWidth = 1;
    for (const magnitude of GRID_CENTS) {
      for (const signed of [magnitude, -magnitude]) {
        const yy = Math.round(yOf(signed)) + 0.5;
        context.strokeStyle = magnitude === 100 ? currentPalette.grid : currentPalette.gridMinor;
        context.beginPath();
        context.moveTo(x, yy);
        context.lineTo(x + w, yy);
        context.stroke();
        context.fillStyle = currentPalette.axisText;
        // Through `formatCents`, so the sign is the Unicode minus and the unit
        // is on every number — the ADR 0006 D3 habit applied to this axis. It
        // also replaces a separate `cents` caption, which collided with the
        // +200 label in the 46 px gutter (screenshot, 2026-08-22).
        context.fillText(formatCents(signed), x - 6, yy);
      }
    }

    // The centre line, and the note it stands for. Dashed as well as brighter:
    // the reading must survive a monochrome screenshot (SC 1.4.1).
    const centreY = Math.round(yOf(0)) + 0.5;
    context.setLineDash([6, 4]);
    context.strokeStyle = currentPalette.grid;
    context.beginPath();
    context.moveTo(x, centreY);
    context.lineTo(x + w, centreY);
    context.stroke();
    context.setLineDash([]);

    const note = centreHz === null ? null : noteName(centreHz);
    context.font = NOTE_FONT;
    context.fillStyle = centreHz === null ? currentPalette.axisText : currentPalette.lane;
    context.fillText(note === null ? '—' : `${note.name}${String(note.octave)}`, x - 6, centreY);
    context.restore();
  }

  function drawTrace(): void {
    if (centreHz === null) {
      return;
    }
    const { x, w } = plot();
    context.save();
    context.lineJoin = 'round';
    context.lineCap = 'round';
    context.beginPath();
    let open = false;
    for (let age = 0; age < ring.held; age += 1) {
      const hz = ring.at(age);
      if (hz === null) {
        open = false;
        continue;
      }
      const px = ageXOf(age, x, w);
      const py = yOf(cents(hz, centreHz));
      if (open) {
        context.lineTo(px, py);
      } else {
        context.moveTo(px, py);
        open = true;
      }
    }
    context.strokeStyle = currentPalette.overlayCasing;
    context.lineWidth = STROKE.casing;
    context.stroke();
    context.strokeStyle = currentPalette.f0Trace;
    context.lineWidth = STROKE.trace;
    context.stroke();
    context.restore();
  }

  function paint(): void {
    context.save();
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.fillStyle = currentPalette.background;
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.scale(backingDpr, backingDpr);

    // The gutter carries the labels, so the grid is drawn before the clip.
    drawGrid();

    // The lane and the trace are clipped to the plot rectangle: a reading 400
    // cents off the centre belongs off the pane (see `centsToY`), not painted
    // over the cents labels.
    const rect = plot();
    context.save();
    context.beginPath();
    context.rect(rect.x, rect.y, rect.w, rect.h);
    context.clip();

    const offset = currentLane === null ? null : laneOffsetCents(currentLane);
    if (currentLane !== null && offset !== null) {
      band(offset - currentLane.nearCents, offset + currentLane.nearCents, currentPalette.laneNear, WASH.near, false);
      band(offset - currentLane.inTuneCents, offset + currentLane.inTuneCents, currentPalette.lane, WASH.inTune, true);
      const height = yOf(offset - currentLane.inTuneCents) - yOf(offset + currentLane.inTuneCents);
      const cased = height >= LANE_DECORATION.casingMinPx;
      laneEdge(offset + currentLane.inTuneCents, cased);
      laneEdge(offset - currentLane.inTuneCents, cased);
    }

    drawTrace();
    context.restore();
    context.restore();
  }

  const scheduler: FrameScheduler<number> = createFrameScheduler<number>(() => {
    paint();
  }, host);

  function request(): void {
    paintSeq += 1;
    scheduler.submit(paintSeq);
  }

  function resize(): void {
    const view = canvas.ownerDocument.defaultView;
    const dpr = view?.devicePixelRatio ?? 1;
    backingDpr = dpr;
    const measuredWidth = canvas.clientWidth;
    const measuredHeight = canvas.clientHeight;
    cssWidth = measuredWidth > 0 ? measuredWidth : cssWidth;
    cssHeight = measuredHeight > 0 ? measuredHeight : cssHeight;
    const backingWidth = Math.max(1, Math.round(cssWidth * dpr));
    const backingHeight = Math.max(1, Math.round(cssHeight * dpr));
    if (canvas.width !== backingWidth || canvas.height !== backingHeight) {
      canvas.width = backingWidth;
      canvas.height = backingHeight;
    }
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.scale(dpr, dpr);
    paint();
  }

  resize();

  return {
    push: (row, f0Hz) => {
      ring.push(row, f0Hz);
      // The centre follows the voice ONLY when there is no reference to aim at.
      if (currentLane === null) {
        centreHz = centreFor(centreHz, f0Hz);
      }
      request();
    },
    setLane: (lane) => {
      currentLane = lane;
      if (lane !== null) {
        centreHz = lane.centreHz;
      }
      request();
    },
    setPalette: (next) => {
      currentPalette = next;
      request();
    },
    resize,
    state: (): PitchStripState => {
      const note = centreHz === null ? null : noteName(centreHz);
      let points = 0;
      let lastCents: number | null = null;
      for (let age = 0; age < ring.held; age += 1) {
        const hz = ring.at(age);
        if (hz === null) {
          continue;
        }
        points += 1;
        if (lastCents === null && centreHz !== null) {
          lastCents = cents(hz, centreHz);
        }
      }
      const offset = currentLane === null ? null : laneOffsetCents(currentLane);
      return {
        centreHz,
        centreNote: note === null ? null : `${note.name}${String(note.octave)}`,
        spanCents: SPAN_CENTS,
        laneInTuneCents: currentLane === null ? null : currentLane.inTuneCents,
        laneNearCents: currentLane === null ? null : currentLane.nearCents,
        laneInTunePx:
          currentLane === null || offset === null
            ? null
            : [yOf(offset + currentLane.inTuneCents), yOf(offset - currentLane.inTuneCents)],
        tracePoints: points,
        lastTraceCents: lastCents,
      };
    },
    destroy: () => {
      scheduler.cancel();
    },
  };
}
