//
// The canvas's colours, read from CSS custom properties.
//
// WHY THE CANVAS ASKS THE STYLESHEET. A `<canvas>` has no cascade: every colour
// inside it is a string in JavaScript, and a palette hard-coded there is a
// palette that ignores `prefers-color-scheme`, ignores the audit and cannot be
// changed without a rebuild. `app.css` already owns the page's colours and
// already switches them for dark mode; these `--ss-*` tokens extend that
// ownership across the canvas boundary so that ONE block of CSS is what a
// reviewer reads — which is the state `app.css` says the W3 contrast audit
// needs ("the palette lives in custom properties so that audit changes one
// block rather than fifty rules").
//
// THE FALLBACKS ARE LITERAL HEX, AND THAT IS DELIBERATE. `getComputedStyle`
// returns an empty string for a property that is not set, and a canvas painted
// with `''` is a canvas painted black on black. The fallbacks below are the
// same values `app.css` sets, duplicated once, so that a stylesheet that failed
// to load produces a legible spectrum instead of an invisible one. They are
// `(prov.)` in the same sense every colour in `app.css` is: nothing here has
// been measured against WCAG 2.2 1.4.3 or 1.4.11, and that audit is a W3
// deliverable (ADR 0021 consequences; bibliography 03 #23).
//
// T1 replaces where the tokens come from. This function's SIGNATURE does not
// change — that is the point of having one.
// ----------------------------------------------------------------------------

/** Every colour the spectrum canvas paints with. Nothing in the view invents one. */
export interface SpectrumPalette {
  readonly background: string;
  readonly grid: string;
  readonly gridMinor: string;
  readonly axisText: string;
  readonly trace: string;
  readonly traceFill: string;
  readonly hold: string;
  readonly peakMarker: string;
  readonly clip: string;
  /** The captured reference: its ghost trace, hollow markers and `Hn` labels. */
  readonly reference: string;
  /** The f0 trace drawn over the spectrogram and down the pitch strip. */
  readonly f0Trace: string;
  /** The in-tune lane: its hatched band and its cased edges. */
  readonly lane: string;
  /** The wider "near" band around the lane — a wash, decorative, never the reading. */
  readonly laneNear: string;
  /**
   * The casing every overlay stroke is drawn under. NOT a colour anyone picks
   * on its own: it is the second half of a pair, and `tokens.css`'s header
   * carries the rule the pair has to satisfy over the whole cividis ramp.
   */
  readonly overlayCasing: string;
}

/**
 * The same palette, named for what the panes that arrived with the overlay work
 * actually paint: a waterfall, a pitch strip and an axis strip are not spectra.
 * One alias, one resolver — a second palette type would be a second place for
 * the tokens to drift apart.
 */
export type CanvasPalette = SpectrumPalette;

/** The custom property each colour is read from. */
export const PALETTE_TOKENS: Readonly<Record<keyof SpectrumPalette, string>> = Object.freeze({
  // All fourteen live under the `--ss-canvas-` prefix, and `tokens.css` guarantees
  // every one of them is an OPAQUE hex literal. Canvas2D paints the string
  // `getComputedStyle` hands back: a token that resolved to `rgba(0,0,0,0.1)`
  // would composite against transparent black after `clearRect` and draw
  // almost nothing, which looks like a rendering bug and is a colour bug.
  background: '--ss-canvas-bg',
  grid: '--ss-canvas-grid',
  gridMinor: '--ss-canvas-grid-minor',
  axisText: '--ss-canvas-axis-text',
  trace: '--ss-canvas-trace',
  traceFill: '--ss-canvas-trace-fill',
  hold: '--ss-canvas-hold',
  peakMarker: '--ss-canvas-peak',
  clip: '--ss-canvas-clip',
  reference: '--ss-canvas-reference',
  f0Trace: '--ss-canvas-f0-trace',
  lane: '--ss-canvas-lane',
  laneNear: '--ss-canvas-lane-near',
  overlayCasing: '--ss-canvas-overlay-casing',
});

/** What the canvas paints with when the stylesheet did not load. Same values as `app.css`. */
export const FALLBACK_PALETTE: SpectrumPalette = Object.freeze({
  background: '#0b0d10',
  grid: '#2c313b',
  gridMinor: '#1a1e25',
  axisText: '#9aa1b1',
  trace: '#79a9ff',
  traceFill: 'rgba(121, 169, 255, 0.18)',
  hold: '#ffd166',
  peakMarker: '#e7e9ee',
  clip: '#ff8a95',
  reference: '#8ab4ff',
  // The fallback set is a dark one — `background` is `#0b0d10` — so the overlay
  // falls back to the dark palette's cores and to a casing that IS that
  // background. A stylesheet that failed to load still draws a cased line.
  f0Trace: '#11d68b',
  lane: '#8ab4ff',
  laneNear: '#5b7fc4',
  overlayCasing: '#0b0d10',
});

/**
 * Resolve the palette for `el` — normally the canvas itself, so a panel-level
 * override cascades into it.
 *
 * Reads through `el.ownerDocument.defaultView` rather than the global
 * `getComputedStyle`, so the function works on a detached document (a test
 * fixture, a future offscreen render) and returns the fallbacks rather than
 * throwing when there is no view at all.
 */
export function readSpectrumPalette(el: Element): SpectrumPalette {
  const view = el.ownerDocument.defaultView;
  if (view === null) {
    return FALLBACK_PALETTE;
  }
  const computed = view.getComputedStyle(el);
  const read = (key: keyof SpectrumPalette): string => {
    const value = computed.getPropertyValue(PALETTE_TOKENS[key]).trim();
    return value === '' ? FALLBACK_PALETTE[key] : value;
  };
  return {
    background: read('background'),
    grid: read('grid'),
    gridMinor: read('gridMinor'),
    axisText: read('axisText'),
    trace: read('trace'),
    traceFill: read('traceFill'),
    hold: read('hold'),
    peakMarker: read('peakMarker'),
    clip: read('clip'),
    reference: read('reference'),
    f0Trace: read('f0Trace'),
    lane: read('lane'),
    laneNear: read('laneNear'),
    overlayCasing: read('overlayCasing'),
  };
}
