//
// "G4", "F#3", "Gb4", "392 Hz" — a typed reference, parsed into one frequency.
//
// WHY TYPING A NOTE IS A FEATURE AND NOT A SHORTCUT. `captureReference`
// (`app/reference.ts`) needs 25 voiced frames — half a second of held note —
// because a captured reference carries a measured spectrum and a measured
// spread, and neither exists without a hold. The owner practises against
// isolated vocal stems, and a song does not hold a note for half a second: the
// phrase he is working on may never present a capturable frame at all. So the
// reference has to be settable from the note he can SEE the singer reach,
// which is a target rather than a measurement. That is exactly the reference
// `syntheticReference` already models — a pitch with no spectrum — so this
// module produces a frequency and nothing else, and the existing path does the
// rest. No new state, no format version, no second kind of reference.
//
// THE PITCH MATH IS NOT HERE. `noteHz` and `noteName` are `dsp/cents.ts`'s, and
// so is `transposeHz` for the ladder. This file owns a GRAMMAR — which strings
// are a note — and nothing else. A `440 * 2 ** ((midi - 69) / 12)` in here
// would be the second definition of equal temperament that `cents.ts`'s header
// forbids, and it would drift the day A4 stops being 440.
//
// FLATS ARE ACCEPTED AND SHARPS ARE DISPLAYED. A singer reading a score in D♭
// types "Gb4" and means MIDI 66; `NOTE_NAMES` has only sharps, so the cell then
// reads "F♯4". That is one naming convention on screen against two in the
// input, deliberately: the alternative is for the display to remember how the
// note was spelled, which makes the same pitch print two ways depending on
// where it came from — a captured F♯4 and a typed G♭4 would look like different
// references. The enharmonics fall out of arithmetic rather than a table:
// "B#3" is MIDI 60 and "Cb4" is 59, both correct, neither special-cased.
//
// EVERY REFUSAL CARRIES ITS NUMBERS, and the reason is a code the shell can
// branch on, in the shape `app/reference.ts` already uses for a refused
// capture (`Refusal<Reason>`). "H4" is a different mistake from "G" and from
// "0 Hz"; a singer who typed one of them should be told which.
// ---------------------------------------------------------------------------

import {
  A4_HZ,
  REFERENCE_MIDI_MAX,
  REFERENCE_MIDI_MIN,
  formatCents,
  noteHz,
  noteName,
  transposeHz,
  type NoteName,
} from '../dsp/cents';
import type { Refusal } from './reference';

export type NoteInputReason =
  | 'empty'
  | 'unknown-letter'
  | 'no-octave'
  | 'bad-number'
  | 'not-positive'
  | 'out-of-range';

export type NoteInputRefusal = Refusal<NoteInputReason>;

export interface ParsedNoteInput {
  /** `note` when a name was typed, `hz` when a frequency was. */
  readonly kind: 'note' | 'hz';
  /** The reference frequency. For a name this is `noteHz(midi)` exactly. */
  readonly hz: number;
  /** The note named, or — for a frequency — the nearest one. */
  readonly midi: number;
  /** The input as it was understood, trimmed. Echoed in the hint. */
  readonly text: string;
}

export type NoteInputResult = ParsedNoteInput | NoteInputRefusal;

/**
 * The semitone offsets of the natural letters within an octave, C = 0.
 *
 * Not derived from `NOTE_NAMES`: that list is indexed by semitone and answers
 * "what is note 6 called", which is the opposite question and has only one
 * answer (F♯). This table answers "where does the letter G sit", which is what
 * a spelling needs, and it is the table that makes G♭ and F♯ the same pitch.
 */
const LETTER_SEMITONES: Readonly<Record<string, number>> = Object.freeze({
  c: 0,
  d: 2,
  e: 4,
  f: 5,
  g: 7,
  a: 9,
  b: 11,
});

/** `C4`, `f#3`, `Gb-1` — letter, optional accidental, signed octave. */
const NOTE_PATTERN = /^([A-Ga-g])([#♯b♭]?)(-?\d{1,2})$/;
/** A letter and an accidental with no octave — its own mistake, its own message. */
const BARE_LETTER_PATTERN = /^([A-Ga-g])([#♯b♭]?)$/;
/** `440`, `440 Hz`, `261.63hz`, and `-5` so that a negative reads as "not positive". */
const HZ_PATTERN = /^(-?\d+(?:\.\d+)?)\s*(?:hz)?$/i;

const SHARPS = '#♯';

function refuse(reason: NoteInputReason, message: string): NoteInputRefusal {
  return { refused: true, reason, message };
}

export function isNoteInputRefusal(value: NoteInputResult | number | NoteInputRefusal): value is NoteInputRefusal {
  return typeof value === 'object' && (value as NoteInputRefusal).refused === true;
}

/** `C0` / `C8` — the bounds, spelled the way the refusals name them. */
function boundLabel(midi: number): string {
  const note = noteName(noteHz(midi));
  return note === null ? String(midi) : `${note.name}${String(note.octave)}`;
}

function outOfRange(what: string, midi: number): NoteInputRefusal {
  return refuse(
    'out-of-range',
    `${what} is MIDI ${String(midi)}, outside ${boundLabel(REFERENCE_MIDI_MIN)}…${boundLabel(REFERENCE_MIDI_MAX)} ` +
      `(MIDI ${String(REFERENCE_MIDI_MIN)}–${String(REFERENCE_MIDI_MAX)}, prov.)`,
  );
}

function inRange(midi: number): boolean {
  return midi >= REFERENCE_MIDI_MIN && midi <= REFERENCE_MIDI_MAX;
}

/**
 * Parse a typed reference. A note name gives its exact equal-tempered
 * frequency at `a4Hz`; a frequency is taken as typed and only checked for
 * being a pitch a voice could aim at.
 */
export function parseNoteInput(raw: string, a4Hz: number = A4_HZ): NoteInputResult {
  const text = raw.trim();
  if (text === '') {
    return refuse('empty', 'type a note (G4, F#3, Gb4) or a frequency (392 Hz)');
  }

  const note = NOTE_PATTERN.exec(text);
  if (note !== null) {
    const letter = (note[1] as string).toLowerCase();
    const accidental = note[2] as string;
    const octave = Number(note[3]);
    const semitone =
      (LETTER_SEMITONES[letter] as number) + (accidental === '' ? 0 : SHARPS.includes(accidental) ? 1 : -1);
    const midi = 12 * (octave + 1) + semitone;
    if (!inRange(midi)) {
      return outOfRange(`"${text}"`, midi);
    }
    return { kind: 'note', hz: noteHz(midi, a4Hz), midi, text };
  }

  const bare = BARE_LETTER_PATTERN.exec(text);
  if (bare !== null) {
    return refuse('no-octave', `"${text}" needs an octave: ${text}4 is the one above middle C's octave`);
  }

  if (/^[A-Za-z]/.test(text)) {
    return refuse(
      'unknown-letter',
      `"${text}" does not start with a note letter — they are C D E F G A B, with # or b for the accidental`,
    );
  }

  const hz = HZ_PATTERN.exec(text);
  if (hz === null) {
    return refuse('bad-number', `"${text}" is neither a note (G4, F#3) nor a frequency (392, 392 Hz)`);
  }
  const value = Number(hz[1]);
  if (!(value > 0) || !Number.isFinite(value)) {
    return refuse('not-positive', `"${text}" is not a pitch: a frequency has to be greater than zero`);
  }
  const nearest = noteName(value, a4Hz);
  if (nearest === null) {
    return refuse('bad-number', `"${text}" is not a frequency this page can place on the scale`);
  }
  if (!inRange(nearest.midi)) {
    return outOfRange(`"${text}" (nearest note ${nearest.name}${String(nearest.octave)})`, nearest.midi);
  }
  return { kind: 'hz', hz: value, midi: nearest.midi, text };
}

/**
 * One rung of the ladder: the current reference, a semitone up or down.
 *
 * The bound is applied to the RESULT, not to the step, so the last rung
 * refuses instead of walking off the scale — and the reference the singer had
 * is left exactly where it was.
 */
export function stepHz(hz: number, semitones: 1 | -1, a4Hz: number = A4_HZ): number | NoteInputRefusal {
  if (!(hz > 0) || !Number.isFinite(hz)) {
    return refuse('not-positive', `there is nothing to step: ${String(hz)} Hz is not a reference`);
  }
  const stepped = transposeHz(hz, semitones);
  const nearest = noteName(stepped, a4Hz);
  if (nearest === null || !inRange(nearest.midi)) {
    return outOfRange(
      `${semitones > 0 ? 'a semitone above' : 'a semitone below'} ${hz.toFixed(2)} Hz`,
      nearest === null ? Number.NaN : nearest.midi,
    );
  }
  return stepped;
}

/**
 * The sentence the hint shows after a successful Set — what the page
 * understood, including the enharmonic respelling, so a singer who typed G♭4
 * and sees F♯4 knows why.
 */
export function describeNoteInput(parsed: ParsedNoteInput, a4Hz: number = A4_HZ): string {
  const note: NoteName | null = noteName(parsed.hz, a4Hz);
  const name = note === null ? '—' : `${note.name}${String(note.octave)}`;
  if (parsed.kind === 'note') {
    const respelled = name.toLowerCase() !== parsed.text.toLowerCase() ? ` (${parsed.text} spelled ${name})` : '';
    return `reference set to ${name} = ${parsed.hz.toFixed(2)} Hz${respelled}`;
  }
  const offset = note === null ? '' : ` · ${formatCents(note.cents)} of ${name}`;
  return `reference set to ${parsed.hz.toFixed(2)} Hz${offset}`;
}
