//
// The one WAV reader of the browser instrument: RIFF, 16-bit PCM, mono, samples
// returned as the file's own int16, untouched.
//
// `decodeAudioData` IS NEVER USED ON THE INJECTION OR GOLDEN PATH (ADR 0021
// decision 7(c)), and this module is that path's only reader. It resamples to
// the AudioContext's rate and converts by an unstated convention, so a Tier-0
// file decoded through it is not the file the manifest's sha256 names — and
// "the same Tier-0 files against the same goldens" would stop being literally
// true. This module parses the int16 PCM itself; injection mode (W2) feeds it
// to the same DSP module in a Worker with no audio graph at all.
//
// The ONE call in the repository is `audio/file-source.ts`, the PLAYBACK
// source of 7(c)'s second note (2026-08-22): the owner's stems are MP3, no
// hand-written reader decodes those, and a stem is something to sing along to
// rather than something to measure. That path declares its codec, its
// resample and its down-mix, and no number it produces meets a golden. The
// sentence above narrowed rather than broke: it is still true of every file
// that reaches a tolerance row.
//
// The refusals are `host/src/spectral_host/wavio.py`'s, transcribed with its
// reasoning:
//   * anything but 16-bit PCM is REFUSED, never converted — so that a
//     manifest's `inputs[].bit_depth: 16` describes the bytes rather than a
//     conversion this reader performed;
//   * a multichannel file is refused rather than down-mixed, because summing
//     channels changes the level by a convention nobody wrote down (wavio's
//     `WavFile.mono` rule, applied at read time here because every consumer in
//     this application wants one channel);
//   * samples come back unscaled: the int16 → float seam is applied exactly
//     once, later, by `dsp/pipeline.ts` (ADR 0003 d.2, ADR 0006 D3).
// ----------------------------------------------------------------------------

/** The file is a WAV this project does not read (not 16-bit PCM mono, or not RIFF at all). */
export class UnsupportedWav extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'UnsupportedWav';
  }
}

/** A decoded 16-bit PCM mono WAV. `samples` is the file's own int16, unscaled. */
export interface WavFile {
  readonly samples: Int16Array;
  readonly sampleRateHz: number;
  readonly channels: 1;
  readonly bitDepth: 16;
  readonly durationS: number;
}

/** The only sample format this reader admits (manifest `inputs[].bit_depth`). */
export const SUPPORTED_BIT_DEPTH = 16;

/** `WAVE_FORMAT_PCM`. `0xFFFE` (`WAVE_FORMAT_EXTENSIBLE`) is named in the refusal so the message is actionable. */
const WAVE_FORMAT_PCM = 0x0001;
const WAVE_FORMAT_EXTENSIBLE = 0xfffe;

function fourCc(view: DataView, offset: number): string {
  return String.fromCharCode(
    view.getUint8(offset),
    view.getUint8(offset + 1),
    view.getUint8(offset + 2),
    view.getUint8(offset + 3),
  );
}

/**
 * Parse a RIFF/WAVE byte buffer into 16-bit PCM mono samples.
 *
 * Chunks are walked rather than assumed at fixed offsets: a `LIST`/`INFO` block
 * between `fmt ` and `data` is legal WAV and a fixed-offset reader would read
 * its bytes as audio. Odd-sized chunks carry a pad byte, which is skipped.
 */
/** The `fmt ` chunk's four numbers, and where the samples are. */
export interface RiffLayout {
  readonly fmt: {
    readonly audioFormat: number;
    readonly channels: number;
    readonly sampleRate: number;
    readonly bitsPerSample: number;
  };
  readonly dataOffset: number;
  readonly dataSize: number;
  readonly view: DataView;
}

/**
 * Walk the chunks and return the layout, refusing only what is not RIFF/WAVE
 * at all. It DESCRIBES; `readWav` below is what refuses a format.
 *
 * Split out so that `io/audio-probe.ts` can read the header of a file this
 * reader would refuse — a 24-bit stereo WAV is a perfectly good thing to sing
 * along to, and the capture-chain panel has to name its real rate and channel
 * count before the browser decodes it. One walk, two callers: a second
 * implementation of "where is the fmt chunk" is how a probe comes to report a
 * rate the reader read differently.
 */
export function readRiffLayout(bytes: Uint8Array): RiffLayout {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (view.byteLength < 12) {
    throw new UnsupportedWav(`not a PCM WAV this reader accepts: ${String(view.byteLength)} bytes is shorter than a RIFF header`);
  }
  if (fourCc(view, 0) !== 'RIFF') {
    throw new UnsupportedWav(`not a PCM WAV this reader accepts: expected a 'RIFF' magic, found ${JSON.stringify(fourCc(view, 0))}`);
  }
  if (fourCc(view, 8) !== 'WAVE') {
    throw new UnsupportedWav(`not a PCM WAV this reader accepts: RIFF form is ${JSON.stringify(fourCc(view, 8))}, not 'WAVE'`);
  }

  let fmt: { audioFormat: number; channels: number; sampleRate: number; bitsPerSample: number } | null = null;
  let dataOffset = -1;
  let dataSize = -1;

  let offset = 12;
  while (offset + 8 <= view.byteLength) {
    const id = fourCc(view, offset);
    const size = view.getUint32(offset + 4, true);
    const body = offset + 8;
    if (id === 'fmt ') {
      if (size < 16 || body + 16 > view.byteLength) {
        throw new UnsupportedWav(`not a PCM WAV this reader accepts: 'fmt ' chunk is ${String(size)} bytes, need at least 16`);
      }
      fmt = {
        audioFormat: view.getUint16(body, true),
        channels: view.getUint16(body + 2, true),
        sampleRate: view.getUint32(body + 4, true),
        bitsPerSample: view.getUint16(body + 14, true),
      };
    } else if (id === 'data') {
      dataOffset = body;
      dataSize = size;
    }
    offset = body + size + (size % 2); // RIFF pads odd-sized chunks to even
  }

  if (fmt === null) {
    throw new UnsupportedWav("not a PCM WAV this reader accepts: no 'fmt ' chunk");
  }
  if (dataOffset < 0) {
    throw new UnsupportedWav("not a PCM WAV this reader accepts: no 'data' chunk");
  }
  return { fmt, dataOffset, dataSize, view };
}

export function readWav(bytes: Uint8Array): WavFile {
  const { fmt, dataOffset, dataSize, view } = readRiffLayout(bytes);
  if (fmt.audioFormat !== WAVE_FORMAT_PCM) {
    const extensible = fmt.audioFormat === WAVE_FORMAT_EXTENSIBLE ? ' (WAVE_FORMAT_EXTENSIBLE)' : '';
    throw new UnsupportedWav(
      `format tag 0x${fmt.audioFormat.toString(16)}${extensible}: only uncompressed WAVE_FORMAT_PCM is read ` +
        '(no decoding, so that the bytes the manifest hashes are the samples analysed)',
    );
  }
  if (fmt.bitsPerSample !== SUPPORTED_BIT_DEPTH) {
    throw new UnsupportedWav(
      `${String(fmt.bitsPerSample)}-bit PCM; only ${String(SUPPORTED_BIT_DEPTH)}-bit PCM is read ` +
        '(no conversion, so that inputs[].bit_depth describes the bytes)',
    );
  }
  if (fmt.channels !== 1) {
    throw new UnsupportedWav(
      `file has ${String(fmt.channels)} channels; refusing to down-mix (the level convention would be unstated) — ` +
        'split the file outside this application if one channel is what you mean',
    );
  }
  if (!(fmt.sampleRate > 0)) {
    throw new UnsupportedWav(`sample rate is ${String(fmt.sampleRate)}`);
  }
  if (dataSize % 2 !== 0) {
    throw new UnsupportedWav(`'data' chunk is ${String(dataSize)} bytes, not a whole number of 16-bit samples`);
  }
  if (dataOffset + dataSize > view.byteLength) {
    const available = view.byteLength - dataOffset;
    throw new UnsupportedWav(
      `truncated: header promises ${String(dataSize / 2)} samples, the file holds ${String(Math.floor(available / 2))}`,
    );
  }

  // Copied through a DataView rather than aliased with `new Int16Array(buffer,
  // offset, n)`: the data chunk is not guaranteed to start on a 2-byte
  // boundary (a preceding odd-sized chunk plus its pad byte can leave it odd),
  // and a typed-array view would throw; the explicit little-endian read is also
  // the convention RIFF states rather than the platform's.
  const count = dataSize / 2;
  const samples = new Int16Array(count);
  for (let i = 0; i < count; i += 1) {
    samples[i] = view.getInt16(dataOffset + 2 * i, true);
  }

  return {
    samples,
    sampleRateHz: fmt.sampleRate,
    channels: 1,
    bitDepth: SUPPORTED_BIT_DEPTH,
    durationS: count / fmt.sampleRate,
  };
}
