//
// Saying "in tune" out loud, at a rate a screen reader can follow.
//
// The match cell changes at the hop rate — fifty times a second — and its text
// is the single most important event on this page for a deaf or hard-of-hearing
// singer, who ADR 0012 decision 6(d) names as a first-class user. A live region
// updated fifty times a second is not an announcement; it is a stutter that
// most screen readers coalesce into nothing.
//
// So: announce on a CHANGE of state only, and never more often than the
// interval. When a change arrives too soon after the last one it is scheduled
// rather than dropped, and a change arriving before that timer fires REPLACES
// the pending text — so the announcement is always the latest state, and the
// last state is never the one that got skipped.
// ---------------------------------------------------------------------------

export interface AnnouncerOptions {
  readonly minIntervalMs: number;
  readonly now: () => number;
  readonly schedule: (fn: () => void, ms: number) => number;
  readonly cancel: (id: number) => void;
  readonly write: (text: string) => void;
}

export interface Announcer {
  /**
   * Announce `text` if `key` differs from the last announced key.
   * `key` is the state ('in', 'near', …), not the text: "flat 12¢" and
   * "flat 13¢" are the same news.
   */
  announce(key: string, text: string): void;
  /** Drop a pending announcement. */
  cancel(): void;
}

export function createAnnouncer(options: AnnouncerOptions): Announcer {
  let lastKey: string | null = null;
  let lastWriteMs = Number.NEGATIVE_INFINITY;
  let pending: { key: string; text: string } | null = null;
  let timer: number | null = null;

  function flush(): void {
    timer = null;
    if (pending === null) {
      return;
    }
    const { key, text } = pending;
    pending = null;
    lastKey = key;
    lastWriteMs = options.now();
    options.write(text);
  }

  return {
    announce: (key, text) => {
      if (key === lastKey && pending === null) {
        return;
      }
      if (pending !== null) {
        // A newer state supersedes the one waiting for the timer.
        pending = { key, text };
        return;
      }
      const since = options.now() - lastWriteMs;
      if (since >= options.minIntervalMs) {
        lastKey = key;
        lastWriteMs = options.now();
        options.write(text);
        return;
      }
      pending = { key, text };
      timer = options.schedule(flush, options.minIntervalMs - since);
    },
    cancel: () => {
      if (timer !== null) {
        options.cancel(timer);
        timer = null;
      }
      pending = null;
    },
  };
}
