//
// The scrolling spectrogram, as a ring in a texture.
//
// WHY A RING AND NOT A SCROLL. The obvious implementation copies the whole
// history up by one row each frame and writes the new row at the bottom. At the
// live-singing preset that is 50 full-texture copies a second, and the cost
// grows with the history you keep — exactly backwards. Instead the texture is
// never moved: one row is uploaded at a moving offset, and the fragment shader
// wraps its lookup. Cost per frame is one `texSubImage2D` of a single row,
// independent of how much history is on screen.
//
// WHY THE TEXTURE HOLDS dB AND NOT COLOUR. Baking the colormap into the upload
// would mean re-uploading the entire history to change the dB range, which is a
// control the panel has. One channel of normalised level in, the ADR 0011 LUT as
// a second texture, and the shader joins them.
//
// WHY WEBGL2 SPECIFICALLY. `R8` single-channel textures and `texelFetch` on a
// LUT without filtering. WebGL1 has neither cleanly. When WebGL2 is missing the
// view says so on the canvas rather than staying black — a blank panel with a
// console error is the failure this rule exists to prevent.
//
// THE PANE IS NOW ONE OF FOUR THAT SHARE A FREQUENCY AXIS, and three things
// changed with it (2026-08-22):
//
//   1. The plot rectangle is `axis.ts`'s, not the whole canvas. The spectrum
//      reserves `PLOT_GUTTER.left` for its dB labels and the overlay draws time
//      ticks in the same gutter; a spectrogram that spanned the full width
//      would put 440 Hz at a different x from the pane above it. So the GL
//      viewport is the plot rectangle and the gutters are cleared to
//      `--ss-canvas-bg` — the colour the neighbouring panes' margins already
//      are.
//   2. A column's frequency is its texel CENTRE, `hzAt((i + 0.5)/N)`, not
//      `i/(N − 1)`. The old form put column 0 at exactly `freqMinHz` and column
//      N−1 at exactly `freqMaxHz`, i.e. it treated texel centres as texel
//      edges; every column was then half a texel off the frequency the shader
//      samples it at.
//   3. `push` returns the ring row it wrote. `trace-ring.ts` has no head of its
//      own precisely so that the f0 overlay cannot drift from the texture it is
//      drawn on; this return value is that single head.
// ---------------------------------------------------------------------------

import { COLORMAP } from './colormap';
import { PLOT_GUTTER, axisMapper, plotWidthFor } from './axis';
import { FALLBACK_PALETTE, readSpectrumPalette, type CanvasPalette } from './palette';
import type { FrameMessage } from '../worker/protocol';

/** Columns of history kept. 512 at 50 Hz is ~10 s, which is a musical phrase. */
export const HISTORY_ROWS = 512;

/** Frequency samples per row. Fixed, so the texture never has to be reallocated. */
export const FREQUENCY_BINS = 1024;

export interface WaterfallOptions {
  readonly freqMinHz: number;
  readonly freqMaxHz: number;
  readonly freqScale: 'log' | 'linear';
  readonly dbFloor: number;
  readonly dbCeiling: number;
}

export interface WaterfallView {
  /**
   * Upload one hop as a row and request a redraw. Returns the RING ROW it was
   * written to — the number the f0 overlay and the pitch strip index their own
   * histories by, so that all three stay in step through a dropped frame.
   */
  push(frame: FrameMessage): number;
  setOptions(options: WaterfallOptions): void;
  /** Re-read the colours. Only the gutters are painted here; the ramp is ADR 0011's and does not change. */
  setPalette(palette: CanvasPalette): void;
  resize(): void;
  /** What actually happened, for the capture panel: the backend, or why there is none. */
  readonly backend: string;
  readonly rowsPushed: number;
  destroy(): void;
}

/**
 * `#rrggbb` (or `#rgb`) → the three floats `gl.clearColor` wants.
 *
 * `tokens.css` guarantees every canvas-facing token is an OPAQUE hex literal
 * and `theme-contrast.test.ts` enforces it, so this parser only has to know one
 * form. It still refuses rather than guesses: an unparsable value returns
 * `null` and the caller keeps the previous clear colour, because a gutter
 * painted a wrong flat colour is harder to notice than one that did not change.
 */
export function clearColourOf(css: string): readonly [number, number, number] | null {
  const hex = css.trim();
  const short = /^#([0-9a-f])([0-9a-f])([0-9a-f])$/i.exec(hex);
  const long = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex);
  if (short !== null) {
    return [
      parseInt((short[1] as string).repeat(2), 16) / 255,
      parseInt((short[2] as string).repeat(2), 16) / 255,
      parseInt((short[3] as string).repeat(2), 16) / 255,
    ];
  }
  if (long !== null) {
    return [
      parseInt(long[1] as string, 16) / 255,
      parseInt(long[2] as string, 16) / 255,
      parseInt(long[3] as string, 16) / 255,
    ];
  }
  return null;
}

const VERTEX = `#version 300 es
in vec2 a_position;
out vec2 v_uv;
void main() {
  v_uv = a_position * 0.5 + 0.5;
  gl_Position = vec4(a_position, 0.0, 1.0);
}`;

const FRAGMENT = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 outColour;

uniform sampler2D u_history;   // R8: normalised level, x = frequency, y = ring row
uniform sampler2D u_colormap;  // RGBA8, 256x1, the ADR 0011 words
uniform float u_head;          // ring write position, in rows
uniform float u_rows;

void main() {
  // v_uv.y = 1 at the top of the canvas. Time runs DOWNWARD (index.html says so),
  // so the top is the newest row and we walk backwards from the head.
  //
  // NO +0.5 ON THE ROW. u_head is the NEXT write slot, so the newest row is
  // u_head-1; the centre of the topmost display row is at age 0.5, which makes
  // (u_head - age) land on (u_head-1) + 0.5: already the texel CENTRE of the
  // newest row once divided by u_rows. Adding half a texel on top of that
  // sampled u_head itself, the OLDEST row, and shifted the whole spectrogram
  // one row toward the old end: a fixed ~20 ms lag at live_singing's hop,
  // invisible in a still and exactly the kind of quiet offset the f0 overlay
  // would have inherited.
  float age = (1.0 - v_uv.y) * u_rows;
  float row = mod(u_head - age, u_rows);
  float level = texture(u_history, vec2(v_uv.x, row / u_rows)).r;
  // texelFetch, not texture(): the LUT is 256 designed words and interpolating
  // between them would invent colours that ADR 0011 deliberately excluded.
  outColour = texelFetch(u_colormap, ivec2(int(level * 255.0 + 0.5), 0), 0);
}`;

function compile(gl: WebGL2RenderingContext, type: number, source: string): WebGLShader {
  const shader = gl.createShader(type);
  if (shader === null) {
    throw new Error('could not create a shader');
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(shader) ?? '(no log)';
    gl.deleteShader(shader);
    throw new Error(`shader failed to compile: ${log}`);
  }
  return shader;
}

/** Draw the reason on the canvas. A blank panel is the failure mode to avoid. */
function explain(canvas: HTMLCanvasElement, palette: CanvasPalette, message: string): void {
  const context = canvas.getContext('2d');
  if (context === null) {
    return;
  }
  context.fillStyle = palette.background;
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = palette.axisText;
  context.font = '13px ui-monospace, "DejaVu Sans Mono", monospace';
  context.textBaseline = 'middle';
  context.fillText(message, 12, canvas.height / 2);
}

export function createWaterfallView(
  canvas: HTMLCanvasElement,
  options: WaterfallOptions,
  palette: CanvasPalette = readSpectrumPalette(canvas),
): WaterfallView {
  let currentOptions = options;
  let currentPalette = palette;
  let rowsPushed = 0;
  let head = 0;
  /** CSS-pixel size of the drawing area and the ratio behind it, owned by `resize()`. */
  let cssWidth = canvas.clientWidth > 0 ? canvas.clientWidth : canvas.width;
  let cssHeight = canvas.clientHeight > 0 ? canvas.clientHeight : canvas.height;
  let backingDpr = 1;
  let clearColour = clearColourOf(currentPalette.background) ?? clearColourOf(FALLBACK_PALETTE.background);

  const maybeGl = canvas.getContext('webgl2', {
    alpha: false,
    antialias: false,
    // The history must survive between frames: only one row is uploaded per
    // frame, and a cleared buffer would show one row of spectrogram on black.
    preserveDrawingBuffer: false,
    powerPreference: 'high-performance',
  });

  if (maybeGl === null) {
    const message = 'WebGL2 is unavailable in this browser — the waterfall cannot render here.';
    explain(canvas, currentPalette, message);
    return {
      // The ROW STILL ADVANCES with no spectrogram to draw it on. The overlay
      // and the pitch strip index their histories by this number, and they are
      // the panes a singer reads: losing the spectrogram must not also stop the
      // pitch trace. `rowsPushed` stays 0 — nothing was rendered, and that
      // counter is a rendering claim.
      push: () => {
        const written = head;
        head = (head + 1) % HISTORY_ROWS;
        return written;
      },
      setOptions: (next) => { currentOptions = next; },
      setPalette: (next) => {
        currentPalette = next;
        explain(canvas, currentPalette, message);
      },
      resize: () => { explain(canvas, currentPalette, message); },
      backend: 'none (WebGL2 unavailable)',
      get rowsPushed() { return 0; },
      destroy: () => undefined,
    };
  }

  // A separately declared binding, not the narrowed one: the drawing helpers
  // below are hoisted function declarations, and TypeScript does not carry a
  // narrowing from the enclosing flow into them. Typing the binding is proof;
  // `gl!` at each use would only be an assertion.
  const gl: WebGL2RenderingContext = maybeGl;

  const program = gl.createProgram();
  if (program === null) {
    throw new Error('could not create the waterfall program');
  }
  gl.attachShader(program, compile(gl, gl.VERTEX_SHADER, VERTEX));
  gl.attachShader(program, compile(gl, gl.FRAGMENT_SHADER, FRAGMENT));
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    throw new Error(`waterfall program failed to link: ${gl.getProgramInfoLog(program) ?? ''}`);
  }
  gl.useProgram(program);

  // A full-screen triangle pair.
  const quad = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, quad);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
  const position = gl.getAttribLocation(program, 'a_position');
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

  // --- the history ring ------------------------------------------------------
  const history = gl.createTexture();
  gl.activeTexture(gl.TEXTURE0);
  gl.bindTexture(gl.TEXTURE_2D, history);
  gl.texImage2D(
    gl.TEXTURE_2D, 0, gl.R8, FREQUENCY_BINS, HISTORY_ROWS, 0, gl.RED, gl.UNSIGNED_BYTE,
    new Uint8Array(FREQUENCY_BINS * HISTORY_ROWS),
  );
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);

  // --- the colormap ----------------------------------------------------------
  const colormap = gl.createTexture();
  gl.activeTexture(gl.TEXTURE1);
  gl.bindTexture(gl.TEXTURE_2D, colormap);
  gl.texImage2D(
    gl.TEXTURE_2D, 0, gl.RGBA8, COLORMAP.entries, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, COLORMAP.rgba,
  );
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);

  gl.uniform1i(gl.getUniformLocation(program, 'u_history'), 0);
  gl.uniform1i(gl.getUniformLocation(program, 'u_colormap'), 1);
  const uHead = gl.getUniformLocation(program, 'u_head');
  gl.uniform1f(gl.getUniformLocation(program, 'u_rows'), HISTORY_ROWS);

  const row = new Uint8Array(FREQUENCY_BINS);

  /**
   * The plot rectangle in CSS pixels, and the axis mapped across it.
   *
   * One call site for both the GL viewport and the column frequencies, so the
   * rectangle the spectrogram is drawn into and the frequencies it is resampled
   * onto can never describe different axes. Rebuilt per hop and per draw rather
   * than cached: it is four numbers and a closure, and a cache would need
   * invalidating from `setOptions`, `resize` and the dpr change — three places
   * to forget.
   */
  function mapper(): ReturnType<typeof axisMapper> {
    return axisMapper(currentOptions, PLOT_GUTTER.left, plotWidthFor(cssWidth));
  }

  function resample(frame: FrameMessage): void {
    const { dbFloor, dbCeiling } = currentOptions;
    // Once per hop, not once per column: 1024 mappers a row at 50 Hz is 51 000
    // closures a second for an axis that did not move.
    const { hzAt } = mapper();
    const span = Math.max(dbCeiling - dbFloor, 1e-9);
    const bins = frame.levelDb.length;
    const binHz = frame.frequencyHz;
    const nyquist = binHz[bins - 1] ?? 1;
    const binWidth = nyquist / Math.max(bins - 1, 1);

    for (let i = 0; i < FREQUENCY_BINS; i += 1) {
      // The texel CENTRE — see the header.
      const hz = hzAt((i + 0.5) / FREQUENCY_BINS);
      // Nearest bin, deliberately, and never interpolated ACROSS bins in dB:
      // ADR 0006 D8's rule is that averaging happens in linear power, and a
      // display that interpolated levels in dB would soften every peak by an
      // amount that depends on where it fell in the bin.
      const k = Math.min(bins - 1, Math.max(0, Math.round(hz / binWidth)));
      const db = frame.levelDb[k] ?? dbFloor;
      const t = (db - dbFloor) / span;
      row[i] = Math.max(0, Math.min(255, Math.round(t * 255)));
    }
  }

  /**
   * The gutters, then the spectrogram inside the plot rectangle.
   *
   * `gl.clear` ignores the viewport (there is no scissor test enabled), so the
   * order is: clear the WHOLE drawing buffer to the neighbouring panes' margin
   * colour, then narrow the viewport and let the full-screen quad fill exactly
   * the plot rectangle. `v_uv.x` therefore runs 0 → 1 across the plot, which is
   * the same 0 → 1 `axisMapper.fractionOf` produces — the overlay's lane and
   * this texture's columns come from one number.
   */
  function draw(): void {
    const dpr = backingDpr;
    gl.viewport(0, 0, canvas.width, canvas.height);
    if (clearColour !== null) {
      gl.clearColor(clearColour[0], clearColour[1], clearColour[2], 1);
      gl.clear(gl.COLOR_BUFFER_BIT);
    }
    const { plotLeft, plotWidth } = mapper();
    gl.viewport(
      Math.round(plotLeft * dpr),
      0,
      Math.max(1, Math.round(plotWidth * dpr)),
      canvas.height,
    );
    gl.uniform1f(uHead, head);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  }

  /*
   * UPLOAD PER HOP, DRAW PER ANIMATION FRAME.
   *
   * The first version drew inside `push()`, i.e. once per hop — 50 GL draws a
   * second, issued synchronously from the Worker's message handler, competing
   * with the compositor rather than cooperating with it. Measured on this
   * machine (2026-08-22, Chromium 151, live_singing): the spectrum went from
   * 0 dropped columns to 47 of 94, and the animation rate halved from 48.3 Hz
   * to 23.8 Hz.
   *
   * The upload has to happen per hop — every row is a moment in time and a
   * skipped one is a hole in the record. The DRAW does not: the screen cannot
   * show more than one image per refresh, so extra draws are pure waste. So the
   * texture is written immediately and a redraw is merely REQUESTED, coalescing
   * to at most one per animation callback.
   */
  let pending: number | null = null;
  const view = canvas.ownerDocument.defaultView;

  function requestDraw(): void {
    if (pending !== null || view === null) {
      return;
    }
    pending = view.requestAnimationFrame(() => {
      pending = null;
      draw();
    });
  }

  function resize(): void {
    const view = canvas.ownerDocument.defaultView;
    const dpr = view?.devicePixelRatio ?? 1;
    // The same discipline as `spectrum-view.resize()`: record the ratio the
    // backing store was actually built with rather than deriving it later from
    // `canvas.width / cssWidth`, which are only in step AFTER a resize.
    backingDpr = dpr;
    const measuredWidth = canvas.clientWidth;
    const measuredHeight = canvas.clientHeight;
    cssWidth = measuredWidth > 0 ? measuredWidth : cssWidth;
    cssHeight = measuredHeight > 0 ? measuredHeight : cssHeight;
    const width = Math.max(1, Math.round(cssWidth * dpr));
    const height = Math.max(1, Math.round(cssHeight * dpr));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
    draw();
  }

  resize();

  return {
    push: (frame) => {
      resample(frame);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, history);
      gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, head, FREQUENCY_BINS, 1, gl.RED, gl.UNSIGNED_BYTE, row);
      const written = head;
      head = (head + 1) % HISTORY_ROWS;
      rowsPushed += 1;
      requestDraw();
      return written;
    },
    setOptions: (next) => {
      currentOptions = next;
    },
    setPalette: (next) => {
      currentPalette = next;
      const parsed = clearColourOf(currentPalette.background);
      if (parsed !== null) {
        clearColour = parsed;
      }
      requestDraw();
    },
    resize,
    backend: 'WebGL2, R8 history ring + RGB565 LUT expanded in the shader',
    get rowsPushed() {
      return rowsPushed;
    },
    destroy: () => {
      if (pending !== null) {
        view?.cancelAnimationFrame(pending);
        pending = null;
      }
      gl.deleteTexture(history);
      gl.deleteTexture(colormap);
      gl.deleteBuffer(quad);
      gl.deleteProgram(program);
    },
  };
}
