//
// `window.__spectral` — the automation surface.
//
// WHY IT EXISTS. Every W1/W2 acceptance row that says "in Chromium and Firefox"
// is unmeasurable through a screenshot. A browser test needs to read the frame
// the page just drew, the rates the browser actually chose, and counters it did
// not compute itself. Scraping the DOM for those numbers would measure the
// formatter, not the instrument.
//
// WHY IT IS GATED. `import.meta.env.DEV` or `?debug=1`, and nothing else. The
// standalone bundle that the owner's Jekyll site hosts is a public page; a
// public page that hands out live microphone frames from a global is a
// different thing from an analyzer, and the difference should not depend on
// anyone remembering to strip a file.
//
// WHY IT HANDS OUT COPIES. `FrameMessage` arrays arrive TRANSFERRED from the
// Worker and are then owned by the page — but the view keeps the last one, and
// a harness that held a reference would watch its own numbers change under it
// between two reads. `Array.from` on each is cheap next to being wrong.
//
// THE REFERENCE SURFACE (2026-08-22). `capture()`, `clearReference()`,
// `setReferenceF0(hz)`, `reference()`, `match()`, `collectMatches(n)` and
// `constants()` are what `tests/e2e/reference.spec.ts` drives. They go through
// the SAME shell functions the buttons call — a harness path that bypassed the
// page's own wiring would measure a second implementation. `setReferenceF0`
// exists because the band edges (±10 / ±25 cents) can only be pinned against
// a known tone, and no Tier-0 file is 10.000 cents from another: a synthetic
// reference at exactly the frequency the test asks for is the stimulus, and
// it is displayed "(set, not sung)" so that a screenshot of one can never
// pass for a capture — the same words a TYPED reference shows, because they
// are the same state: a pitch nobody sang, with no spread and no ghost. `constants()` is how a test reads the bands instead of typing
// them — a tolerance typed into a test is a tolerance nobody audits.
//
// THE TOLERANCE AND THE TWO PANE STATES (2026-08-22). `setTolerance` goes
// through the page's own control path, so a test that moves the band moves the
// same three things a click moves — the constants, the two lanes and the cell.
// `constants()` therefore returns the ACTIVE constants, not the frozen
// defaults: a harness that read the defaults while the page matched against
// something else would pass while the instrument disagreed with itself, and
// `reference.spec.ts` — which types no band edge at all — stays valid without
// an edit because at the default tolerance the two carry the same numbers.
//
// `overlayState()` and `pitchStripState()` are how a lane is measured. A lane
// is geometry, and geometry on a canvas is unreadable from the DOM; these two
// hand back the numbers the pane actually drew with — the lane's edges in Hz
// AND in pixels, the trace's last point, the CSS box and the dpr — so a test
// can assert `laneInTunePx` against the page's own `axisMapper` rather than
// against a second implementation of it.
// ---------------------------------------------------------------------------

import type { CaptureChain } from '../audio/chain';
import type { PitchStripState } from '../render/pitch-strip';
import type { WaterfallOverlayState } from '../render/waterfall-overlay';
import type { FrameMessage } from '../worker/protocol';
import type { NoteInputRefusal } from './note-input';
import type { DerivedProvenance, FileTransport } from '../audio/file-source';
import type { SourceKind } from '../audio/chain';
import type { Region, RegionRefusal, TransportState } from './transport';
import type { CaptureResult, MatchState, Reference, ToleranceCents } from './reference';
import type { Session, SessionStats } from './session';
import type { Mode } from './prefs';
import type { TunerDrawn, TunerMeasured } from './tuner-display';

/** What Tune is drawing, and what it measured to draw it. */
export interface DebugTuner {
  readonly drawn: TunerDrawn;
  readonly measured: TunerMeasured;
  /** The time constant that separates them, in milliseconds. */
  readonly dampingMs: number;
  readonly held: boolean;
}

/** A frame, flattened to plain JSON so it survives `page.evaluate()`. */
export interface DebugFrame {
  readonly frameIndex: number;
  readonly frequencyHz: number[];
  readonly levelDb: number[];
  readonly rawLevelDb: number[];
  readonly holdDb: number[] | null;
  readonly peak: { hz: number; db: number; bin: number; deltaBins: number };
  readonly peaks: { hz: number; db: number; bin: number; deltaBins: number; prominenceDb: number; harmonic: number | null }[];
  readonly f0: { f0Hz: number | null; clarity: number; lag: number } | null;
  readonly clipped: boolean;
  readonly peakAbs: number;
  readonly capturedAtMs: number;
  readonly computedAtMs: number;
  readonly levelUnit: string;
  readonly enbwHz: number;
}

export interface DebugSessionInfo {
  readonly running: boolean;
  readonly presetId: string | null;
  readonly startedAtMs: number | null;
}

/** Every number the reference/match display is built from, so a test reads them rather than typing them. */
export interface DebugConstants {
  readonly holdFrames: number;
  readonly minVoicedFraction: number;
  readonly minClarity: number;
  readonly inTuneCents: number;
  readonly nearCents: number;
  readonly barSpanCents: number;
  readonly a4Hz: number;
  readonly maxPeaks: number;
}

/**
 * What the harness reads about the active source. Plain JSON: `decodeCount` is
 * what proves a preset switch REUSED the decoded buffer instead of paying for
 * it again, and the native fields are what the panel's declaration is built
 * from — a test that read them from the AudioBuffer would be reading the
 * decoder's output, which is the one place they no longer exist.
 */
export interface DebugSource {
  readonly kind: SourceKind;
  readonly name: string | null;
  readonly bytes: number | null;
  readonly container: string | null;
  readonly nativeSampleRateHz: number | null;
  readonly nativeChannels: number | null;
  readonly decodedSampleRateHz: number | null;
  readonly decodedChannels: number | null;
  readonly durationS: number | null;
  readonly decodeCount: number;
}

/** What a harness reads about the stretch. `derived` is `null` at 1×, which is the raw file. */
export interface DebugStretch {
  readonly factor: number;
  /** The window length in seconds — the "smear" control (roadmap Q58). */
  readonly smearS: number;
  /** The largest factor this region can reach under the output cap. */
  readonly maxFactor: number;
  /** What would be rendered: the A–B region, or the whole file when none is set. */
  readonly regionS: number;
  readonly derived: DerivedProvenance | null;
  readonly outputSamples: number | null;
  readonly durationS: number | null;
}

export interface SpectralDebug {
  /** Resolves once the shell has booted and the preset list is in hand. */
  ready(): Promise<void>;
  session(): DebugSessionInfo;
  /** The capture chain verbatim, deep-copied. `null` when nothing is running. */
  chain(): CaptureChain | null;
  lastFrame(): DebugFrame | null;
  /** The next `n` frames, in order. Rejects if nothing is running. */
  collect(n: number): Promise<DebugFrame[]>;
  stats(): SessionStats | null;
  resetCounters(): void;
  start(presetId?: string): Promise<void>;
  stop(): Promise<void>;
  /** Preset ids the shell knows about, in list order. */
  presets(): string[];
  /** The installed reference, as plain JSON, or `null`. */
  reference(): Reference | null;
  /** Capture the running session's hold through the page's own path. Rejects with no session. */
  capture(): CaptureResult;
  clearReference(): void;
  /** Install a synthetic reference at `hz` (`source: 'synthetic'`, shown "(set, not sung)"). */
  setReferenceF0(hz: number): Reference;
  /** Set it from typed text ("G4", "Gb4", "392 Hz") through the rail's own path, or the refusal. */
  setReferenceText(text: string): Reference | NoteInputRefusal;
  /** One rung of the ladder, through the rail's own buttons' path, or the refusal. */
  stepReference(semitones: 1 | -1): Reference | NoteInputRefusal;
  /** The match of the most recent frame, or `null` (no reference, or nothing running). */
  match(): MatchState | null;
  /** The next `n` per-frame match states, in order. Rejects if nothing is running. */
  collectMatches(n: number): Promise<(MatchState | null)[]>;
  /** The ACTIVE constants — the ones the running band is judged by. See the header. */
  constants(): DebugConstants;
  /** The in-tune band in force, in cents. */
  tolerance(): ToleranceCents;
  /** Move it, through the same path the segmented control uses. */
  setTolerance(tolerance: ToleranceCents): void;
  /**
   * Tune's drawn and measured readings, side by side.
   *
   * The pair is the point: a harness that could only read the DOM would have
   * to parse the big number and would have no way at all to see what the
   * measurement under it was doing. HOLD is exactly the case where the two
   * must disagree, and this is what lets a test say so.
   */
  tuner(): DebugTuner;
  /** Switch display mode through the same path the segmented control uses. */
  setMode(mode: Mode): void;
  /** Which source is active, and the file's facts when it is one. */
  source(): DebugSource;
  /** The stretch in force, and the provenance of the render behind it. */
  stretch(): DebugStretch;
  /** Set the factor through the slider's own path; renders and restarts. */
  setStretch(factor: number): Promise<void>;
  /** Set the window length through the smear slider's own path; re-renders when stretched. */
  setSmear(smearS: number): Promise<void>;
  /** Switch source through the rail's own path; restarts a running session. */
  selectSource(kind: SourceKind): Promise<void>;
  /** Resolves after the decode a `setInputFiles` started. */
  fileReady(): Promise<void>;
  /** The transport's state, or `null` for a microphone. */
  transport(): TransportState | null;
  play(): void;
  pause(): void;
  seek(toS: number): void;
  setLoop(loop: boolean): void;
  setRegion(startS: number, endS: number | null): Region | RegionRefusal;
  /** The spectrogram overlay's geometry, deep-copied; `null` when nothing is running. */
  overlayState(): WaterfallOverlayState | null;
  /** The pitch strip's geometry, deep-copied; `null` when nothing is running. */
  pitchStripState(): PitchStripState | null;
}

/** What the shell gives the debug surface, so this file needs no state of its own. */
export interface DebugHost {
  ready: Promise<void>;
  current(): Session | null;
  startedAtMs(): number | null;
  presetIds(): string[];
  start(presetId?: string): Promise<void>;
  stop(): Promise<void>;
  /** Register a per-frame listener; returns an unsubscribe. */
  onFrame(listener: (frame: FrameMessage) => void): () => void;
  reference(): Reference | null;
  capture(): CaptureResult;
  clearReference(): void;
  setReferenceF0(hz: number): Reference;
  setReferenceText(text: string): Reference | NoteInputRefusal;
  stepReference(semitones: 1 | -1): Reference | NoteInputRefusal;
  match(): MatchState | null;
  /** Register a per-frame match listener; returns an unsubscribe. */
  onMatch(listener: (match: MatchState | null) => void): () => void;
  constants(): DebugConstants;
  tolerance(): ToleranceCents;
  setTolerance(tolerance: ToleranceCents): void;
  tuner(): DebugTuner;
  setMode(mode: Mode): void;
  source(): DebugSource;
  stretch(): DebugStretch;
  setStretch(factor: number): Promise<void>;
  setSmear(smearS: number): Promise<void>;
  selectSource(kind: SourceKind): Promise<void>;
  fileReady(): Promise<void>;
  transport(): FileTransport | null;
  setRegion(startS: number, endS: number | null): Region | RegionRefusal;
}

declare global {
  interface Window {
    __spectral?: SpectralDebug;
  }
}

export function debugRequested(view: Window = window): boolean {
  if (import.meta.env.DEV) {
    return true;
  }
  try {
    return new URLSearchParams(view.location.search).get('debug') === '1';
  } catch {
    return false;
  }
}

export function toDebugFrame(frame: FrameMessage): DebugFrame {
  return {
    frameIndex: frame.frameIndex,
    frequencyHz: Array.from(frame.frequencyHz),
    levelDb: Array.from(frame.levelDb),
    rawLevelDb: Array.from(frame.rawLevelDb),
    holdDb: frame.holdDb === null ? null : Array.from(frame.holdDb),
    peak: { ...frame.peak },
    peaks: frame.peaks.map((p) => ({ ...p })),
    f0: frame.f0 === null ? null : { ...frame.f0 },
    clipped: frame.clipped,
    peakAbs: frame.peakAbs,
    capturedAtMs: frame.capturedAtMs,
    computedAtMs: frame.computedAtMs,
    levelUnit: frame.levelUnit,
    enbwHz: frame.enbwHz,
  };
}

export function createDebugSurface(host: DebugHost): SpectralDebug {
  return {
    ready: () => host.ready,
    session: (): DebugSessionInfo => {
      const session = host.current();
      return {
        running: session !== null,
        presetId: session?.preset.id ?? null,
        startedAtMs: host.startedAtMs(),
      };
    },
    // JSON round trip rather than a hand-written copier: `CaptureChain` carries
    // `capabilities`, whose shape is whatever the browser put there. A copier
    // would have to guess it; this cannot.
    chain: () => {
      const session = host.current();
      return session === null ? null : (JSON.parse(JSON.stringify(session.chain)) as CaptureChain);
    },
    lastFrame: () => {
      const frame = host.current()?.lastFrame() ?? null;
      return frame === null ? null : toDebugFrame(frame);
    },
    collect: (n: number): Promise<DebugFrame[]> =>
      new Promise((resolve, reject) => {
        if (!Number.isInteger(n) || n < 1) {
          reject(new RangeError(`collect(n) wants a positive integer, got ${String(n)}`));
          return;
        }
        if (host.current() === null) {
          reject(new Error('collect() needs a running session; call start() first'));
          return;
        }
        const out: DebugFrame[] = [];
        const off = host.onFrame((frame) => {
          out.push(toDebugFrame(frame));
          if (out.length >= n) {
            off();
            resolve(out);
          }
        });
      }),
    stats: () => host.current()?.stats() ?? null,
    resetCounters: () => {
      host.current()?.resetCounters();
    },
    start: (presetId?: string) => host.start(presetId),
    stop: () => host.stop(),
    presets: () => host.presetIds(),
    // JSON round trips again: a `Reference` is plain data by construction
    // (it is what `serialize` writes), and a copy is what keeps the harness
    // from holding the object the session is matching against.
    reference: () => {
      const reference = host.reference();
      return reference === null ? null : (JSON.parse(JSON.stringify(reference)) as Reference);
    },
    capture: () => JSON.parse(JSON.stringify(host.capture())) as CaptureResult,
    clearReference: () => {
      host.clearReference();
    },
    setReferenceF0: (hz: number) => JSON.parse(JSON.stringify(host.setReferenceF0(hz))) as Reference,
    setReferenceText: (text: string) =>
      JSON.parse(JSON.stringify(host.setReferenceText(text))) as Reference | NoteInputRefusal,
    stepReference: (semitones: 1 | -1) =>
      JSON.parse(JSON.stringify(host.stepReference(semitones))) as Reference | NoteInputRefusal,
    match: () => {
      const match = host.match();
      return match === null ? null : { ...match };
    },
    collectMatches: (n: number): Promise<(MatchState | null)[]> =>
      new Promise((resolve, reject) => {
        if (!Number.isInteger(n) || n < 1) {
          reject(new RangeError(`collectMatches(n) wants a positive integer, got ${String(n)}`));
          return;
        }
        if (host.current() === null) {
          reject(new Error('collectMatches() needs a running session; call start() first'));
          return;
        }
        const out: (MatchState | null)[] = [];
        const off = host.onMatch((match) => {
          out.push(match === null ? null : { ...match });
          if (out.length >= n) {
            off();
            resolve(out);
          }
        });
      }),
    constants: () => ({ ...host.constants() }),
    tolerance: () => host.tolerance(),
    setTolerance: (tolerance: ToleranceCents) => {
      host.setTolerance(tolerance);
    },
    tuner: () => JSON.parse(JSON.stringify(host.tuner())) as DebugTuner,
    setMode: (mode: Mode) => {
      host.setMode(mode);
    },
    // JSON round trips, for the same reason `chain` does: these are the numbers
    // a pane drew with, and a harness holding the pane's own object would watch
    // them change under it between two reads.
    source: () => ({ ...host.source() }),
    stretch: () => JSON.parse(JSON.stringify(host.stretch())) as DebugStretch,
    setStretch: (factor: number) => host.setStretch(factor),
    setSmear: (smearS: number) => host.setSmear(smearS),
    selectSource: (kind: SourceKind) => host.selectSource(kind),
    fileReady: () => host.fileReady(),
    transport: () => {
      const state = host.transport()?.state();
      return state === undefined ? null : (JSON.parse(JSON.stringify(state)) as TransportState);
    },
    play: () => { host.transport()?.play(); },
    pause: () => { host.transport()?.pause(); },
    seek: (toS: number) => { host.transport()?.seek(toS); },
    setLoop: (loop: boolean) => { host.transport()?.setLoop(loop); },
    setRegion: (startS: number, endS: number | null) =>
      JSON.parse(JSON.stringify(host.setRegion(startS, endS))) as Region | RegionRefusal,
    overlayState: () => {
      const state = host.current()?.overlayState() ?? null;
      return state === null ? null : (JSON.parse(JSON.stringify(state)) as WaterfallOverlayState);
    },
    pitchStripState: () => {
      const state = host.current()?.pitchStripState() ?? null;
      return state === null ? null : (JSON.parse(JSON.stringify(state)) as PitchStripState);
    },
  };
}

/** Install on `window` when the gate allows it. Returns whether it did. */
export function installDebugSurface(host: DebugHost, view: Window = window): boolean {
  if (!debugRequested(view)) {
    return false;
  }
  view.__spectral = createDebugSurface(host);
  return true;
}
