//
// The shared frequency axis, drawn once for the whole column.
//
// WHY IT IS A PANE OF ITS OWN. Before this file every pane printed its own Hz
// labels along its own bottom edge: two readings of the same axis a few pixels
// apart, 16 px of vertical budget spent twice, and — the reason it had to
// change — nothing musical anywhere on screen. A singer reading `261.6 Hz` is
// doing arithmetic mid-phrase. Every analyzer singers actually use offers a
// note axis (Sing&See draws its trace on a keyboard; `woheller69/audio-analyzer`
// ships a note axis beside its linear and log ones), so this strip carries TWO
// rows — Hz above, note names below — for the spectrum and the spectrogram it
// sits between.
//
// THE TWO TRIANGLES. The lane marker is where the captured reference is; the
// live marker is where the voice is now. They are told apart by FILL and SIZE
// as well as by hue — hollow and wide for the reference, filled and narrow for
// the live one — so "the filled triangle is inside the hollow one" is the
// in-tune picture even in a monochrome screenshot (WCAG 2.2 SC 1.4.1, ADR 0012
// d.6). Nothing here decides whether they coincide: the strip is handed two
// frequencies and maps them to two x positions.
//
// LABELS MAY BE DROPPED, TICKS NEVER ARE — `spectrum-view.ts`'s rule, and its
// implementation: one running `lastRight` per row, a label whose measured
// extent would start inside the previous one's plus a gap is skipped. On a
// 60–8000 Hz log axis there are 74 semitones and no room for 74 names, which is
// why only the Cs are labelled at all.
//
// ONE PAINT PER ANIMATION CALLBACK. The live marker moves at the hop rate (50
// Hz at `live_singing`) and the display refreshes at whatever the display
// refreshes at; the scheduler that already carries that rule for the spectrum
// carries it here, with the two marker frequencies as its payload.
// ---------------------------------------------------------------------------

import { noteName } from '../dsp/cents';
import { PLOT_GUTTER, axisMapper, frequencyTicks, noteTicks, plotWidthFor, type FrequencyAxis } from './axis';
import { readSpectrumPalette, type CanvasPalette } from './palette';
import { browserRafHost, createFrameScheduler, type FrameScheduler, type RafHost } from './scheduler';

/** What the strip is asked to point at. Both `null` before anything is running. */
export interface AxisMarks {
  /** The captured reference, if there is one. */
  readonly referenceHz: number | null;
  /** The live f0 of the newest frame, or `null` for an unvoiced one. */
  readonly liveHz: number | null;
}

export interface AxisStrip {
  setOptions(axis: FrequencyAxis): void;
  setPalette(palette: CanvasPalette): void;
  /** Move the hollow lane marker, or take it away. */
  setReference(hz: number | null): void;
  /** Move the filled live marker, or take it away (an unvoiced frame). */
  setLive(hz: number | null): void;
  /** What the strip is currently pointing at. Read by the harness, never by the drawing. */
  marks(): AxisMarks;
  resize(): void;
  destroy(): void;
}

/** Marker geometry, CSS pixels. The live triangle nests INSIDE the reference one. */
const MARKER = { maxHeight: 8, referenceHalf: 5, liveHalf: 3.5 } as const;

/** Tick lengths, CSS pixels. */
const TICK = { major: 4, minor: 2 } as const;

/** One label row: the 10 px font plus its leading. */
const LABEL_ROW_PX = 11;

/** Minimum gap between two labels on the same row before the second is skipped. */
const LABEL_GAP_PX = 4;

const LABEL_FONT = '10px ui-monospace, "DejaVu Sans Mono", monospace';

export function createAxisStrip(
  canvas: HTMLCanvasElement,
  axis: FrequencyAxis,
  palette: CanvasPalette = readSpectrumPalette(canvas),
  host: RafHost = browserRafHost(canvas.ownerDocument.defaultView ?? window),
): AxisStrip {
  // An IIFE, for the reason `spectrum-view.ts` gives: the hoisted helpers below
  // do not inherit a narrowing from this scope.
  const context = ((): CanvasRenderingContext2D => {
    const found = canvas.getContext('2d');
    if (found === null) {
      throw new Error('this browser did not give a 2d context for the axis strip');
    }
    return found;
  })();

  let currentAxis = axis;
  let currentPalette = palette;
  let currentMarks: AxisMarks = { referenceHz: null, liveHz: null };
  let cssWidth = canvas.clientWidth > 0 ? canvas.clientWidth : canvas.width;
  let cssHeight = canvas.clientHeight > 0 ? canvas.clientHeight : canvas.height;
  /** The ratio the backing store was built with — owned by `resize()`; see `spectrum-view.ts`. */
  let backingDpr = 1;

  /** One label row's collision state: `lastRight` walks left to right. */
  interface LabelRow {
    lastRight: number;
  }

  function claim(row: LabelRow, left: number, right: number): boolean {
    if (left < row.lastRight + LABEL_GAP_PX) {
      return false;
    }
    row.lastRight = right;
    return true;
  }

  /**
   * A triangle standing on the top edge, apex up, pointing at the pane above.
   * `filled` is the live marker; the hollow one is the reference.
   */
  function triangle(x: number, half: number, height: number, filled: boolean): void {
    context.beginPath();
    context.moveTo(x, 0);
    context.lineTo(x - half, height);
    context.lineTo(x + half, height);
    context.closePath();
    if (filled) {
      context.fill();
    } else {
      context.stroke();
    }
  }

  function paint(marks: AxisMarks): void {
    const plotLeft = PLOT_GUTTER.left;
    const plotWidth = plotWidthFor(cssWidth);
    const mapper = axisMapper(currentAxis, plotLeft, plotWidth);
    const markerHeight = Math.min(MARKER.maxHeight, cssHeight * 0.25);

    // Clear the whole BACKING STORE, not the measured CSS box — the ghost
    // `spectrum-view.ts` documents at length.
    context.save();
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.fillStyle = currentPalette.background;
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.scale(backingDpr, backingDpr);
    context.font = LABEL_FONT;
    context.textAlign = 'center';

    const inPlot = (x: number): boolean => x >= plotLeft && x <= plotLeft + plotWidth;

    // --- row 1: Hz, hung from the top --------------------------------------
    const hzTickTop = markerHeight;
    const hzLabelTop = hzTickTop + TICK.major + 1;
    const hzRow: LabelRow = { lastRight: Number.NEGATIVE_INFINITY };
    context.textBaseline = 'top';
    for (const tick of frequencyTicks(currentAxis)) {
      const x = Math.round(mapper.xOf(tick.hz)) + 0.5;
      context.strokeStyle = tick.major ? currentPalette.grid : currentPalette.gridMinor;
      context.beginPath();
      context.moveTo(x, hzTickTop);
      context.lineTo(x, hzTickTop + (tick.major ? TICK.major : TICK.minor));
      context.stroke();
      if (tick.label === null) {
        continue;
      }
      const half = context.measureText(tick.label).width / 2;
      if (claim(hzRow, x - half, x + half)) {
        context.fillStyle = currentPalette.axisText;
        context.fillText(tick.label, x, hzLabelTop);
      }
    }

    // --- row 2: note names, hung from the bottom ---------------------------
    // Anchored to the opposite edge so that a taller strip gains air in the
    // middle rather than a gap under the last row.
    const noteLabelBottom = cssHeight - 1;
    const noteTickBottom = noteLabelBottom - LABEL_ROW_PX;
    const noteRow: LabelRow = { lastRight: Number.NEGATIVE_INFINITY };
    context.textBaseline = 'bottom';
    for (const tick of noteTicks(currentAxis)) {
      const x = Math.round(mapper.xOf(tick.hz)) + 0.5;
      context.strokeStyle = tick.major ? currentPalette.grid : currentPalette.gridMinor;
      context.beginPath();
      context.moveTo(x, noteTickBottom - (tick.major ? TICK.major : TICK.minor));
      context.lineTo(x, noteTickBottom);
      context.stroke();
      if (tick.label === null) {
        continue;
      }
      const half = context.measureText(tick.label).width / 2;
      if (claim(noteRow, x - half, x + half)) {
        context.fillStyle = currentPalette.axisText;
        context.fillText(tick.label, x, noteLabelBottom);
      }
    }

    // --- the two markers ---------------------------------------------------
    // The reference first, so the live triangle is drawn INSIDE it when the
    // singer has arrived rather than behind it.
    if (marks.referenceHz !== null && marks.referenceHz > 0) {
      const x = mapper.xOf(marks.referenceHz);
      if (inPlot(x)) {
        context.strokeStyle = currentPalette.lane;
        context.lineWidth = 1.5;
        triangle(x, MARKER.referenceHalf, markerHeight, false);
      }
    }
    if (marks.liveHz !== null && marks.liveHz > 0) {
      const x = mapper.xOf(marks.liveHz);
      if (inPlot(x)) {
        context.fillStyle = currentPalette.f0Trace;
        triangle(x, MARKER.liveHalf, markerHeight, true);
      }
    }

    // --- the reference's note, in the left gutter --------------------------
    // The gutter is empty on this pane and the name is the one thing a singer
    // needs when the marker is off the edge of a narrow axis.
    if (marks.referenceHz !== null && marks.referenceHz > 0) {
      const note = noteName(marks.referenceHz);
      if (note !== null) {
        context.fillStyle = currentPalette.lane;
        context.textAlign = 'left';
        context.textBaseline = 'top';
        context.fillText(`${note.name}${String(note.octave)}`, 4, hzLabelTop);
      }
    }

    context.restore();
  }

  const scheduler: FrameScheduler<AxisMarks> = createFrameScheduler<AxisMarks>((marks) => {
    paint(marks);
  }, host);

  function request(): void {
    scheduler.submit(currentMarks);
  }

  function resize(): void {
    const view = canvas.ownerDocument.defaultView;
    const dpr = view?.devicePixelRatio ?? 1;
    backingDpr = dpr;
    const measuredWidth = canvas.clientWidth;
    const measuredHeight = canvas.clientHeight;
    cssWidth = measuredWidth > 0 ? measuredWidth : cssWidth;
    cssHeight = measuredHeight > 0 ? measuredHeight : cssHeight;
    const backingWidth = Math.max(1, Math.round(cssWidth * dpr));
    const backingHeight = Math.max(1, Math.round(cssHeight * dpr));
    if (canvas.width !== backingWidth || canvas.height !== backingHeight) {
      canvas.width = backingWidth;
      canvas.height = backingHeight;
    }
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.scale(dpr, dpr);
    // Immediately, not on the next callback: a resize clears the backing store
    // and the strip would otherwise be blank until the next hop.
    paint(currentMarks);
  }

  resize();

  return {
    setOptions: (next) => {
      currentAxis = next;
      request();
    },
    setPalette: (next) => {
      currentPalette = next;
      request();
    },
    setReference: (hz) => {
      currentMarks = { ...currentMarks, referenceHz: hz };
      request();
    },
    setLive: (hz) => {
      currentMarks = { ...currentMarks, liveHz: hz };
      request();
    },
    marks: () => currentMarks,
    resize,
    destroy: () => {
      scheduler.cancel();
    },
  };
}
