/* --- state ---------------------------------------------------------------- */

interface Shell {
  summaries: readonly PresetSummary[];
  presets: Map<string, LivePreset>;
  selected: string | null;
  session: Session | null;
  startedAtMs: number | null;
  /** The one reference. Persisted; handed to every session; rendered before any. */
  reference: Reference | null;
  /** Did the last `store.save` succeed? `false` → "kept for this page only". */
  referencePersisted: boolean;
  /** Perform or Study. Mirrored onto `#app[data-mode]`, which is the whole switch. */
  mode: Mode;
  /** The in-tune band, the singer's to set. */
  tolerance: Tolerance;
  /** `REFERENCE_CONSTANTS` with that band — the constants everything on this page uses. */
  constants: ReferenceConstants;
  /** The damped needle position, in cents; `null` after an unvoiced frame. */
  needleCents: number | null;
  /** `1 − e^(−hop/τ)` for the running preset's hop. */
  needleAlpha: number;
  /**
   * The last typed-reference refusal, PINNED.
   *
   * `renderReadiness` rewrites `#reference-hint` every fifth frame — 100 ms at
   * the live_singing hop — so a refusal written there once is gone before a
   * singer's eye reaches it. It is held here instead and reprinted by
   * `renderReadiness` until the field changes or a Set succeeds.
   */
  typedRefusal: string | null;
  /**
   * Microphone or file. NEVER PERSISTED: a `File` cannot be put in
   * localStorage, so a remembered choice of "file" would come back on reload
   * with nothing behind it — a source that is a lie. On reload it is the
   * microphone, and the hint says why.
   */
  source: SourceKind;
  /** The chosen file, decoded once per analysis rate. `null` until one is picked. */
  file: DecodedAudioFile | null;
  /** Buffers by decode rate: `stem_analysis` runs at 48 kHz and needs its own. */
  decodedByRate: Map<number, DecodedAudioFile>;
  /** How many decodes this page has run. A harness reads it to prove a preset switch reused the buffer. */
  decodeCount: number;
  /** The decode in flight, so the harness can await a `setInputFiles`. */
  decoding: Promise<void> | null;
  /** The loop and region the singer set — the shell's, so they survive a restart. */
  fileLoop: boolean;
  fileRegion: Region | null;
  /** Unsubscribe from the running session's transport. */
  transportOff: (() => void) | null;
  /** The factor the slider is on. 1 means "the raw file" and renders nothing. */
  stretch: number;
  /** The window length, in seconds — how much of the voice each frame freezes. */
  smearS: StretchSmearS;
  /** The render in force, keyed by `(rate, region, factor)`; `null` at 1×. */
  stretched: DecodedAudioFile | null;
  /** The render in flight, so a second slider move supersedes rather than races. */
  renderId: number;
  rendering: Promise<void> | null;
  /** The needle's time constant, in ms, as the singer set it. */
  dampingMs: number;
  /** Tune's rolling display state: what is drawn, beside what was measured. */
  tuner: TunerState;
  tunerHeld: boolean;
}

