/** The constants in force. Every band, tick and match on this page reads this one. */
function activeConstants(): ReferenceConstants {
  return shell.constants;
}

const store = createReferenceStore();

const frameListeners = new Set<(frame: FrameMessage) => void>();
const matchListeners = new Set<(match: MatchState | null) => void>();

/** The sentence for a preset whose `display.overlays` has no `f0`: nothing to match, nothing to capture. */
const NO_F0_OVERLAY = 'no pitch — this preset has no f0 overlay';

/**
 * The match state, said out loud at a rate a screen reader can follow.
 *
 * ADR 0012 decision 6(d) names the deaf and hard-of-hearing singer as a
 * first-class user, and for that reader this cell is the single most important
 * event on the page. It changes at the hop rate; a live region written fifty
 * times a second is a stutter most screen readers coalesce into nothing. So:
 * on a change of STATE only, at most twice a second, and the last state is
 * never the one that gets skipped (`app/announce.ts`).
 */
const announcer = createAnnouncer({
  minIntervalMs: 500,
  now: () => performance.now(),
  schedule: (fn, ms) => window.setTimeout(fn, ms),
  cancel: (id) => {
    window.clearTimeout(id);
  },
  write: (text) => {
    required<HTMLElement>('match-announce').textContent = text;
  },
});

/** The glyph beside the match word. Shape, not colour: ✓ in, ▼ flat, ▲ sharp, — nothing to say. */
function matchGlyph(match: MatchState | null): string {
  if (match === null || match.cents === null) {
    return '—';
  }
  if (match.state === 'in') {
    return '✓';
  }
  return match.direction === 'flat' ? '▼' : '▲';
}

/* --- the cents bar's geometry, in the SVG's own units ------------------------ */

/**
 * The axis runs 30…330 in a `0 0 360 40` viewBox; its centre is 0 cents.
 *
 * The bar was 240 units wide inside a readout cell, which put its tick labels
 * at 8 px — the smallest text on the page, on the one control a singer reads
 * while singing. It has a cell of its own now, and the labels are 12 px.
 */
const BAR = { left: 30, right: 330, centre: 180, halfWidth: 150, top: 4, height: 18 } as const;

/** x of a cents value on the bar: the mapping `barFraction` is defined for, applied to a fraction of the span. */
function barX(fractionOfSpan: number): number {
  return BAR.centre + fractionOfSpan * BAR.halfWidth;
}

function svgElement<K extends keyof SVGElementTagNameMap>(tag: K): SVGElementTagNameMap[K] {
  return document.createElementNS('http://www.w3.org/2000/svg', tag);
}

/* --- rendering ------------------------------------------------------------ */

function setStatus(text: string, kind: 'idle' | 'live' | 'error' = 'idle'): void {
  const state = required<HTMLElement>('capture-state');
  state.textContent = text;
  state.dataset['kind'] = kind;
}

function chainRow(term: string, detail: string, kind?: string): HTMLDivElement {
  const row = document.createElement('div');
  row.className = 'chain__row';
  const dt = document.createElement('dt');
  dt.textContent = term;
  const dd = document.createElement('dd');
  dd.textContent = detail;
  if (kind !== undefined) {
    dd.dataset['kind'] = kind;
  }
  row.append(dt, dd);
  return row;
}

function renderChain(session: Session | null): void {
  const list = required<HTMLElement>('capture-chain-readback');
  if (session === null) {
    list.replaceChildren(chainRow('state', 'idle — press Start capture'));
    return;
  }
  const c = session.chain;
  const rows: HTMLDivElement[] = [
    chainRow('source', c.source === 'file' ? `file — ${c.fileName} (${String(c.fileBytes)} bytes)` : 'microphone'),
    chainRow('device', c.deviceLabel),
    chainRow('preset rate', `${String(c.requestedSampleRate)} Hz (asserted, never resampled by us)`),
    chainRow('AudioContext rate', `${String(c.contextSampleRate)} Hz`),
  ];
  if (c.source === 'file') {
    // Every stage the browser added between the file's bytes and our first
    // sample, each as its own row: what the container said, what the decoder
    // did, and — when there is one — the resample and the down-mix. All three
    // are `warn`, not because anything is wrong but because they are stages
    // this application did not add and cannot remove (ADR 0003 d.7).
    rows.push(
      chainRow('container', c.probe.summary),
      chainRow(
        'file rate',
        c.trackSampleRate === null ? 'not stated by its header' : `${String(c.trackSampleRate)} Hz`,
      ),
      chainRow(
        'decoded',
        `${String(c.decoded.frames)} frames · ${String(c.decoded.channels)} ch · ` +
          `${String(c.decoded.sampleRateHz)} Hz · ${c.decoded.durationS.toFixed(2)} s`,
      ),
      chainRow('decoder', c.decode, 'warn'),
    );
    if (c.stretch !== null) {
      // The fourth declared stage, and the only one this application added
      // rather than the browser (ADR 0023 decision 3).
      rows.push(chainRow('stretch', c.stretch, 'warn'));
    }
    if (c.browserResampler !== null) {
      rows.push(chainRow('browser resampler', c.browserResampler, 'warn'));
    }
    if (c.downmix !== null) {
      rows.push(chainRow('down-mix', c.downmix, 'warn'));
    }
    rows.push(
      chainRow(
        'processing flags',
        'none — a decoder has no AGC, NS or EC stage (by construction, not read back)',
      ),
      chainRow('remembered', 'no — a file cannot be stored by the page; choose it again after a reload'),
    );
  } else {
    rows.push(
      chainRow(
        'track rate',
        c.trackSampleRate === null ? 'not reported by this browser' : `${String(c.trackSampleRate)} Hz`,
      ),
    );
    if (c.browserResampler !== null) {
      rows.push(chainRow('browser resampler', c.browserResampler, 'warn'));
    }
    rows.push(
      chainRow(
        'processing flags',
        `echoCancellation ${flagWord(c.processing.echoCancellation)} · ` +
          `noiseSuppression ${flagWord(c.processing.noiseSuppression)} · ` +
          `autoGainControl ${flagWord(c.processing.autoGainControl)}`,
        c.processing.allOff ? undefined : 'warn',
      ),
    );
  }
  rows.push(
    chainRow(
      'base latency',
      c.baseLatencyS === null ? 'not reported' : `${(c.baseLatencyS * 1000).toFixed(2)} ms`,
    ),
    chainRow(
      'DC blocker',
      c.dcBlocker === null
        ? 'off for this preset'
        : `f_c ${String(c.dcBlocker.cutoffHz)} Hz · R = ${c.dcBlocker.R.toFixed(6)}`,
    ),
  );
  list.replaceChildren(...rows);
}

function renderCounters(): void {
  const target = required<HTMLElement>('counters');
  const session = shell.session;
  if (session === null) {
    target.textContent = '';
    return;
  }
  const s = session.stats();
  target.textContent =
    `${s.achievedColumnsPerS.toFixed(1)} columns/s achieved of ${s.expectedColumnsPerS.toFixed(1)} asked · ` +
    `${String(s.columnsDrawn)} drawn, ${String(s.columnsDropped)} dropped · ` +
    `${s.rafHz.toFixed(1)} Hz animation · ${s.elapsedS.toFixed(1)} s`;
}

/**
 * The one line that stays visible when the door is shut.
 *
 * Everything else about the chain can wait behind a `<details>`; these four
 * facts cannot, because each of them silently invalidates a reading. The rate
 * pair is the resampling stage of ADR 0021 decision 7(c); the processing flags
 * are the non-linear pre-processing that corrupts a spectrum outright; the
 * achieved column rate is the measured half of decision 3; a non-zero drop
 * count means the spectrogram has holes in time.
 */
function renderFooterSummary(): void {
  const target = required<HTMLElement>('footer-summary');
  const session = shell.session;
  if (session === null) {
    target.textContent = 'not capturing';
    return;
  }
  const c = session.chain;
  const s = session.stats();
  const processing =
    c.source === 'file'
      ? 'decoded'
      : c.processing.allOff
        ? 'AGC/NS/EC off'
        : `AGC ${flagWord(c.processing.autoGainControl)} · NS ${flagWord(c.processing.noiseSuppression)} · ` +
          `EC ${flagWord(c.processing.echoCancellation)}`;
  // THE SOURCE IS THE FIFTH FACT THAT MUST NEVER BE HIDDEN. The other four
  // each silently invalidate a reading; this one silently changes what the
  // reading is OF, which is worse. A rate pair with no source beside it reads
  // as the microphone, and on this page it now may not be.
  const source =
    c.source === 'file'
      ? c.derived === null
        ? `file ${c.fileName}`
        : `file ${c.fileName} · stretched ${c.derived.stretch.toFixed(1)}× (derived)`
      : 'mic';
  const rates =
    c.trackSampleRate === null
      ? `? → ${kilohertz(c.requestedSampleRate)} kHz`
      : `${kilohertz(c.trackSampleRate)} kHz → ${kilohertz(c.requestedSampleRate)} kHz`;
  const downmix = c.source === 'file' && c.downmix !== null ? ' · stereo→mono' : '';
  target.textContent =
    `${source} · ${rates}${downmix} · ` +
    `${processing} · ${s.achievedColumnsPerS.toFixed(1)} col/s · ${String(s.columnsDropped)} dropped`;
}

function renderFrame(frame: FrameMessage): void {
  required<HTMLElement>('readout-peak').textContent =
    `${formatHz(frame.peak.hz)} at ${formatDb(frame.peak.db)}`;
  // The note is read from f0, never from the peak: the owner's first
  // screenshot (2026-08-22) showed a D3 labelled D4 because the strongest
  // partial was the second harmonic. With no estimator (the preset declares
  // no `f0` overlay) or no voicing, the cell says so rather than guessing.
  const f0 = frame.f0;
  const f0Cell = required<HTMLElement>('readout-f0');
  const noteCell = required<HTMLElement>('readout-note');
  if (f0 === null) {
    f0Cell.textContent = 'no f0 overlay';
    noteCell.textContent = '—';
  } else if (f0.f0Hz === null) {
    f0Cell.textContent = `unvoiced (clarity ${f0.clarity.toFixed(2)})`;
    noteCell.textContent = '—';
  } else {
    const note = noteName(f0.f0Hz, A4_HZ);
    noteCell.textContent = noteLabel(note);
    // "220.31 Hz · −8¢ ET": the frequency, then how far it sits from EQUAL
    // TEMPERAMENT at this page's A4 — which is a different question from the
    // match cell's "how far from the note you captured", and is tagged `ET` so
    // the two can never be read as the same number.
    f0Cell.textContent =
      note === null ? formatHz(f0.f0Hz) : `${formatHz(f0.f0Hz)} · ${formatCents(note.cents)} ET`;
  }
  renderPeakLegend(frame);
}

/**
 * Every marker's numbers, in full. The canvas skips a label that would
 * overprint its neighbour; this list is where nothing is skipped. The `li`s
 * are reused rather than rebuilt, because this runs at the hop rate.
 */
function renderPeakLegend(frame: FrameMessage): void {
  const list = required<HTMLUListElement>('peak-legend');
  const preset = shell.session?.preset;
  if (preset !== undefined && !preset.display.overlays.includes('peak_markers')) {
    list.replaceChildren(mutedItem('peak markers are not an overlay of this preset'));
    return;
  }
  if (frame.peaks.length === 0) {
    list.replaceChildren(mutedItem('none above the prominence floor'));
    return;
  }
  const reference = shell.reference;
  while (list.children.length > frame.peaks.length) {
    list.lastElementChild?.remove();
  }
  while (list.children.length < frame.peaks.length) {
    list.append(document.createElement('li'));
  }
  frame.peaks.forEach((peak, i) => {
    const item = list.children[i] as HTMLLIElement;
    item.className = '';
    item.textContent = legendLine(peak, frame.levelUnit, reference);
  });
}

function legendLine(peak: LabelledPeak, unit: string, reference: Reference | null): string {
  const label = peak.harmonic === null ? '—' : `H${String(peak.harmonic)}`;
  const live = `${label} ${formatHz(peak.hz)} ${peak.db.toFixed(1)} ${unit}`;
  if (reference === null || peak.harmonic === null) {
    return live;
  }
  // The reference's level at the SAME harmonic number, when its capture found
  // one: the timbre comparison the ghost trace shows, as a number.
  const twin = reference.peaks.find((p) => p.harmonic === peak.harmonic);
  return twin === undefined ? live : `${live} · ref ${twin.db.toFixed(1)}`;
}

function mutedItem(text: string): HTMLLIElement {
  const item = document.createElement('li');
  item.className = 'muted';
  item.textContent = text;
  return item;
}

/* --- the match cell and the cents bar ---------------------------------------- */

/**
 * Lay the bar out from the ACTIVE constants. The band edges and the ticks are
 * the only geometry that depends on a number, and that number is read from the
 * same object the session matches against — so a tolerance change moves the
 * band, the tick labels and the rule together or not at all.
 */
/**
 * The ids of one meter. There are two on the page — the glance bar's and
 * Tune's — and they are the SAME meter at two sizes: same viewBox, same
 * constants, same layout code. A second implementation would be a second
 * chance to draw a band that disagrees with the tolerance it claims to show.
 */
interface MeterIds {
  readonly band: string;
  readonly near: string;
  readonly ticks: string;
  readonly needle: string;
}

const GLANCE_METER: MeterIds = {
  band: 'cents-bar-band',
  near: 'cents-bar-near',
  ticks: 'cents-bar-ticks',
  needle: 'cents-bar-needle',
};

const TUNER_METER: MeterIds = {
  band: 'tuner-meter-band',
  near: 'tuner-meter-near',
  ticks: 'tuner-meter-ticks',
  needle: 'tuner-meter-needle',
};

/** Both meters, from one set of constants. Called at boot and on every tolerance change. */
function layoutCentsBar(): void {
  layoutMeter(GLANCE_METER);
  layoutMeter(TUNER_METER);
}

function layoutMeter(ids: MeterIds): void {
  const { inTuneCents, nearCents, barSpanCents } = activeConstants();
  const band = required<SVGRectElement>(ids.band);
  const near = required<SVGRectElement>(ids.near);
  const inLeft = barX(-inTuneCents / barSpanCents);
  const inRight = barX(inTuneCents / barSpanCents);
  band.setAttribute('x', String(inLeft));
  band.setAttribute('width', String(inRight - inLeft));
  const nearLeft = barX(-nearCents / barSpanCents);
  const nearRight = barX(nearCents / barSpanCents);
  near.setAttribute('x', String(nearLeft));
  near.setAttribute('width', String(nearRight - nearLeft));

  const ticks = required<SVGGElement>(ids.ticks);
  ticks.replaceChildren();
  // The span and the near band, labelled; the in-tune band is NOT. Its edges
  // are drawn — the hatched rectangle is exactly them — and at ±5 the two
  // labels would sit 15 viewBox units apart and overprint each other and the
  // zero. `nearCents` can equal `barSpanCents` (a 25-cent band takes a 50-cent
  // near band), so a Set keeps one tick where two would coincide.
  for (const c of [...new Set([-barSpanCents, -nearCents, 0, nearCents, barSpanCents])]) {
    const x = barX(c / barSpanCents);
    const line = svgElement('line');
    line.setAttribute('x1', String(x));
    line.setAttribute('x2', String(x));
    line.setAttribute('y1', String(BAR.top + BAR.height));
    line.setAttribute('y2', String(BAR.top + BAR.height + 4));
    const text = svgElement('text');
    text.setAttribute('x', String(x));
    text.setAttribute('y', String(BAR.top + BAR.height + 15));
    text.textContent = c === 0 ? '0' : `${c > 0 ? '+' : '−'}${String(Math.abs(c))}`;
    ticks.append(line, text);
  }
}

/**
 * The cell, from the session's `MatchState`. `off` is the shell's own state
 * for a preset with no estimator; every other value is the session's word.
 */
function renderMatch(match: MatchState | null, frame: FrameMessage | null): void {
  const cell = required<HTMLElement>('readout-match');
  const glyph = required<HTMLElement>('readout-match-glyph');
  const text = required<HTMLElement>('readout-match-text');
  const needle = required<SVGGElement>('cents-bar-needle');

  const estimatorOff = frame !== null && frame.f0 === null;
  if (estimatorOff) {
    cell.dataset['state'] = 'off';
    glyph.textContent = '—';
    text.textContent = NO_F0_OVERLAY;
    needle.dataset['visible'] = 'false';
    shell.needleCents = null;
    announcer.announce('off', NO_F0_OVERLAY);
    return;
  }

  const state = match === null ? 'none' : match.state;
  cell.dataset['state'] = state;
  glyph.textContent = matchGlyph(match);
  const sentence = describeMatch(match);
  text.textContent = sentence;
  announcer.announce(state, sentence);

  if (match === null || match.cents === null) {
    needle.dataset['visible'] = 'false';
    // The filter is reset, never carried across a gap: a needle that slid back
    // in from where the last note ended would be reporting a pitch that is not
    // being sung.
    shell.needleCents = null;
    return;
  }
  const damped = dampCents(shell.needleCents, match.cents, shell.needleAlpha);
  shell.needleCents = damped;
  // The damped value goes through the SAME mapping as the raw one — this file
  // still owns no arithmetic beyond placing a fraction on an axis.
  const fraction = barFraction({ ...match, cents: damped }, activeConstants());
  if (fraction === null) {
    needle.dataset['visible'] = 'false';
    return;
  }
  needle.dataset['visible'] = 'true';
  needle.setAttribute('transform', `translate(${String(barX(fraction) - BAR.centre)} 0)`);
}

/* --- the reference cell and its controls --------------------------------------- */

function renderReference(): void {
  const cell = required<HTMLElement>('readout-reference');
  const warning = required<HTMLElement>('readout-reference-warning');
  const clear = required<HTMLButtonElement>('clear-reference');
  const reference = shell.reference;

  const stepButtons = [required<HTMLButtonElement>('note-down'), required<HTMLButtonElement>('note-up')];

  if (reference === null) {
    cell.textContent = 'none — hold a note and capture it, or type one';
    warning.hidden = true;
    warning.textContent = '';
    clear.disabled = true;
    // Nothing to step. The ladder moves the reference that exists; it does not
    // invent one, because "a semitone up from nothing" has no answer.
    stepButtons.forEach((button) => { button.disabled = true; });
    return;
  }
  clear.disabled = false;
  stepButtons.forEach((button) => { button.disabled = false; });
  const parts = [`ref ${formatNote(reference.note)}`, formatHz(reference.f0Hz)];
  if (reference.source === 'derived') {
    // Measured on a phase-randomised resynthesis: the spread and the hold
    // beside it describe the window's band, not a voice (ADR 0023 decision 4).
    const stretch = reference.provenance?.stretch;
    parts.push(`±${reference.f0SpreadCents.toFixed(0)}¢ over ${String(reference.holdFrames)} frames`);
    parts.push(stretch === undefined ? '(from stretch, not sung)' : `(from stretch ${stretch.toFixed(1)}×, not sung)`);
  } else if (reference.source === 'synthetic') {
    // TRUE OF BOTH WAYS A SYNTHETIC REFERENCE ARRIVES. It used to read
    // "(injected)", which described the debug surface's `setReferenceF0` and
    // nothing else; the same state is now reached by a singer typing a note,
    // and "injected" would tell them nothing. What the word has to carry is
    // the one property the cell would otherwise imply falsely: this pitch was
    // not measured from a voice, so there is no spread, no clarity and no
    // ghost behind it.
    parts.push('(set, not sung)');
  } else {
    parts.push(`±${reference.f0SpreadCents.toFixed(0)}¢ over ${String(reference.holdFrames)} frames`);
  }
  if (!shell.referencePersisted) {
    parts.push('kept for this page only');
  }
  cell.textContent = parts.join(' · ');

  // The SESSION's verdict, not a second call to `compatibility()` here: the
  // session decided whether to hand the ghost to the view from this same
  // object, so the warning and the missing ghost can never disagree.
  const verdict = shell.session?.compatibility() ?? null;
  if (verdict !== null && !verdict.comparable) {
    warning.textContent = verdict.message;
    warning.hidden = false;
  } else {
    warning.textContent = '';
    warning.hidden = true;
  }
}

/** The capture button and its hint, from the session's readiness. */
function renderReadiness(readiness: CaptureReadiness | null): void {
  const button = required<HTMLButtonElement>('capture-reference');
  const hint = required<HTMLElement>('reference-hint');
  const session = shell.session;
  // The typed refusal outranks the readiness sentence. This function runs
  // every fifth frame; without the pin, "H4 does not start with a note letter"
  // would be replaced by "hold steady — 25 of 25 frames voiced" within 100 ms
  // and the singer would never see why nothing happened.
  if (shell.typedRefusal !== null) {
    hint.textContent = shell.typedRefusal;
    button.disabled = session === null || !(readiness?.ready ?? false);
    return;
  }
  if (session === null) {
    button.disabled = true;
    hint.textContent = `start capture, then hold a note for ${String(activeConstants().holdFrames)} frames`;
    return;
  }
  if (!session.preset.display.overlays.includes('f0')) {
    button.disabled = true;
    hint.textContent = NO_F0_OVERLAY;
    return;
  }
  if (readiness === null) {
    button.disabled = true;
    hint.textContent = 'waiting for frames…';
    return;
  }
  button.disabled = !readiness.ready;
  hint.textContent = readiness.ready
    ? `hold steady — ${String(readiness.voicedFrames)} of ${String(readiness.framesHeld)} frames voiced, press to capture`
    : (readiness.refusal?.message ?? 'not ready');
}

/**
 * The conventions line. The hold's duration in seconds depends on the preset's
 * column rate, so it is quoted for the running preset, else the selected one,
 * else left as a frame count.
 */
function renderConstants(): void {
  const c = activeConstants();
  const preset = shell.session?.preset ?? (shell.selected === null ? undefined : shell.presets.get(shell.selected));
  const holdSeconds = preset === undefined ? '' : ` = ${(c.holdFrames / expectedColumnsPerSecond(preset)).toFixed(2)} s`;
  const low = noteName(noteHz(REFERENCE_MIDI_MIN));
  const high = noteName(noteHz(REFERENCE_MIDI_MAX));
  const typedRange =
    low === null || high === null
      ? ''
      : ` · typed ${low.name}${String(low.octave)}…${high.name}${String(high.octave)} (prov.)`;
  required<HTMLElement>('constants-line').textContent =
    `A4 = ${String(A4_HZ)} Hz (prov.) · in tune ±${String(c.inTuneCents)} ¢ (user-set, prov.) · ` +
    `near ±${String(c.nearCents)} ¢ (prov.) · hold ${String(c.holdFrames)} frames${holdSeconds} (prov.) · ` +
    `K = ${String(DEFAULT_PEAK_PICKER.maxPeaks)} peaks (prov.)${typedRange}`;
}

/** Install a reference everywhere it is read: the shell, the store, the session, the cells. */
function installReference(reference: Reference | null): void {
  shell.reference = reference;
  shell.referencePersisted = reference === null ? store.clear() : store.save(reference);
  shell.session?.setReference(reference);
  renderReference();
  renderMatch(
    shell.session?.lastMatch() ?? matchState(null, reference, activeConstants()),
    shell.session?.lastFrame() ?? null,
  );
}

function captureReference(): CaptureResult {
  const session = shell.session;
  if (session === null) {
    throw new Error('capture needs a running session; press Start capture first');
  }
  const result = session.captureReference();
  if (isRefusal(result)) {
    required<HTMLElement>('reference-hint').textContent = result.message;
    return result;
  }
  installReference(result);
  return result;
}

function setReferenceF0(hz: number): Reference {
  const session = shell.session;
  let identity: { id: string; sha256: string };
  if (session !== null) {
    identity = session.referencePreset;
  } else {
    const summary = shell.summaries.find((p) => p.id === shell.selected);
    if (summary === undefined) {
      throw new Error('setReferenceF0 needs a running session or a selected preset');
    }
    identity = { id: summary.id, sha256: summary.sha256 };
  }
  const reference = syntheticReference(hz, identity);
  installReference(reference);
  return reference;
}

/**
 * Set the reference from what was typed — the same `syntheticReference` path
 * the debug surface uses, reached through `setReferenceF0`.
 *
 * The parse is `app/note-input.ts`'s and the arithmetic is `dsp/cents.ts`'s;
 * this function moves a string to one of them and a sentence to the hint.
 */
function setTypedReference(raw: string): Reference | NoteInputRefusal {
  const parsed = parseNoteInput(raw, A4_HZ);
  if (isNoteInputRefusal(parsed)) {
    pinTypedRefusal(parsed.message);
    return parsed;
  }
  clearTypedRefusal();
  const reference = setReferenceF0(parsed.hz);
  required<HTMLElement>('reference-hint').textContent = describeNoteInput(parsed, A4_HZ);
  required<HTMLInputElement>('note-input').value = '';
  return reference;
}

/**
 * One rung of the ladder. The step is applied to the reference that exists,
 * so a captured note keeps its own cents offset on the way up (`stepHz` →
 * `transposeHz`), and the last rung refuses rather than walking off the scale.
 */
function stepReference(semitones: 1 | -1): Reference | NoteInputRefusal {
  const reference = shell.reference;
  if (reference === null) {
    const refusal: NoteInputRefusal = {
      refused: true,
      reason: 'empty',
      message: 'there is no reference to step — capture one or type a note first',
    };
    pinTypedRefusal(refusal.message);
    return refusal;
  }
  const stepped = stepHz(reference.f0Hz, semitones, A4_HZ);
  if (isNoteInputRefusal(stepped)) {
    pinTypedRefusal(stepped.message);
    return stepped;
  }
  clearTypedRefusal();
  const next = setReferenceF0(stepped);
  required<HTMLElement>('reference-hint').textContent =
    `reference ${semitones > 0 ? 'up' : 'down'} a semitone to ${formatNote(next.note)} · ${formatHz(next.f0Hz)}`;
  return next;
}

/** Pin a refusal under the field and mark the field itself — never colour alone. */
function pinTypedRefusal(message: string): void {
  shell.typedRefusal = message;
  required<HTMLElement>('reference-hint').textContent = message;
  required<HTMLInputElement>('note-input').setAttribute('aria-invalid', 'true');
}

function clearTypedRefusal(): void {
  shell.typedRefusal = null;
  required<HTMLInputElement>('note-input').removeAttribute('aria-invalid');
}

/* --- the stretch: a loop rendered into a drone (ADR 0023) -------------------- */

/** The slider's law: `2^(v/10)` over v ∈ [0, 50] — 1× to 32× in doublings. */
function factorForSliderValue(value: number): number {
  return Math.round(2 ** (value / 10) * 10) / 10;
}

function sliderValueForFactor(factor: number): number {
  return Math.round(10 * Math.log2(factor));
}

/** The region the stretch would render, in seconds. The whole file when no A–B is set. */
function stretchRegionS(): number {
  const file = shell.file;
  if (file === null) {
    return 0;
  }
  const region = shell.fileRegion ?? { startS: 0, endS: file.buffer.duration };
  return Math.max(0, region.endS - region.startS);
}

/**
 * The largest factor this region can be stretched by under the cap.
 *
 * THE BAR MUST NOT OFFER WHAT THE CAP WILL REFUSE. The first build had a
 * slider running to 32× and a cap of 300 s of output, and the owner loaded a
 * four-minute song: everything above about 1.2× was refused after the fact, by
 * a warning, from a control that still showed thirty-two. A ceiling that
 * follows the region says the same thing before the click, and the readout
 * says why — a whole song cannot be stretched 32× because that is two hours of
 * audio, and the answer is to mark a phrase with A and B.
 */
function maxFactorForRegion(): number {
  const regionS = stretchRegionS();
  if (!(regionS > 0)) {
    return 32;
  }
  return Math.max(1, Math.min(32, Math.floor((STRETCH_CAP_S / regionS) * 10) / 10));
}

/** `1× (raw)` at the bottom stop; the word *raw* appears nowhere else. */
function describeFactor(factor: number): string {
  return factor <= 1.001 ? '1× (raw)' : `${factor.toFixed(factor < 10 ? 1 : 0)}× stretched`;
}

/** What the slider is about to produce — the outcome, not the setting. */
function describeStretchOutcome(factor: number): string {
  const regionS = stretchRegionS();
  if (!(regionS > 0)) {
    return describeFactor(factor);
  }
  if (factor <= 1.001) {
    return '1× (raw)';
  }
  const outS = regionS * factor;
  const of = shell.fileRegion === null ? 'the whole file' : `${regionS.toFixed(1)} s`;
  return `${describeFactor(factor)} · ${of} → ${formatSeconds(outS)}`;
}

/** The sentence under the bar when the region is too long for the factor to be reachable. */
function describeStretchCeiling(): string | null {
  const ceiling = maxFactorForRegion();
  if (ceiling >= 32) {
    return null;
  }
  const regionS = stretchRegionS();
  return (
    `${formatSeconds(regionS)} of audio caps the stretch at ${ceiling.toFixed(1)}× ` +
    `(${String(STRETCH_CAP_S)} s of drone) — mark a phrase with A and B for more`
  );
}

let stretchWorker: Worker | null = null;

function makeStretchWorker(): Worker {
  // The literal-path form Vite statically analyses, exactly as `session.ts`
  // builds the spectrum Worker; a computed specifier emits nothing and the
  // built bundle 404s at runtime.
  // `./worker/…` and not `../worker/…`: this file is `src/main.ts`, one level
  // above the directory, where `session.ts` is inside `src/app/`. Vite
  // resolves the literal at build time, so a wrong prefix is a build error
  // rather than a 404 at runtime — which is the good failure of the two.
  return new Worker(new URL('./worker/stretch.worker.ts', import.meta.url), {
    type: 'module',
    name: 'spectral-stretch',
  });
}

/**
 * Render the current loop region of the current file at `factor`.
 *
 * Cancellation is `terminate()`, not a flag: the Worker's loop is synchronous
 * and could not observe one. A superseded reply is discarded by its id in any
 * case, so the two mechanisms overlap on purpose.
 */
async function renderStretch(factor: number): Promise<DecodedAudioFile | null> {
  const file = shell.file;
  const preset = activePreset();
  if (file === null || preset === undefined) {
    return null;
  }
  const region = shell.fileRegion ?? { startS: 0, endS: file.buffer.duration };
  const rate = file.buffer.sampleRate;
  const from = Math.max(0, Math.round(region.startS * rate));
  const to = Math.min(file.buffer.length, Math.round(region.endS * rate));
  if (to - from < 1) {
    setStatus('the loop region is empty — set A and B further apart', 'error');
    return null;
  }

  // The DOWN-MIX happens here, once, and is the same 0.5·(L+R) the analysis
  // node applies to a raw stereo file — so a stretched stem and a raw one are
  // heard through the same mixing rule (ADR 0023 decision 7: mono render).
  const channels = file.buffer.numberOfChannels;
  const mono = new Float32Array(to - from);
  for (let c = 0; c < channels; c += 1) {
    const data = file.buffer.getChannelData(c);
    for (let i = 0; i < mono.length; i += 1) {
      mono[i] = (mono[i] as number) + (data[from + i] as number) / channels;
    }
  }

  stretchWorker?.terminate();
  stretchWorker = makeStretchWorker();
  const worker = stretchWorker;
  shell.renderId += 1;
  const id = shell.renderId;

  setStatus(`rendering ${factor.toFixed(1)}× of ${file.name}…`);
  const request: StretchRequest = {
    type: 'render',
    id,
    channels: [mono],
    sampleRateHz: rate,
    stretch: factor,
    windowSamples: stretchWindowSamplesFor(rate, shell.smearS),
    seed: STRETCH_SEED,
    circular: true,
  };

  return await new Promise<DecodedAudioFile | null>((resolve) => {
    worker.onmessage = (event: MessageEvent<StretchResponse>): void => {
      const message = event.data;
      if (message.id !== id) {
        return; // a superseded render answering late
      }
      if (message.type === 'progress') {
        const percent = Math.round((100 * message.doneSamples) / message.totalSamples);
        setStatus(`rendering ${factor.toFixed(1)}× of ${file.name}… ${String(percent)} %`);
        return;
      }
      worker.onmessage = null;
      if (message.type === 'refused' || message.type === 'error') {
        setStatus(message.message, 'error');
        resolve(null);
        return;
      }

      const rendered = message.channels[0];
      if (rendered === undefined) {
        setStatus('the render came back empty', 'error');
        resolve(null);
        return;
      }
      // Built at the PRESET's rate with no `decodeAudioData` and no resample:
      // `io/wav.ts`'s "the one call in the repository" sentence stays true.
      const buffer = new AudioBuffer({ numberOfChannels: 1, length: rendered.length, sampleRate: message.sampleRateHz });
      // `copyToChannel` wants a `Float32Array<ArrayBuffer>`; what crosses a
      // Worker boundary is typed `ArrayBufferLike`, which could in principle
      // be shared memory. It is not — the Worker allocated it — so the cast is
      // the same one `protocol.ts` makes on the transfer list.
      buffer.copyToChannel(rendered as Float32Array<ArrayBuffer>, 0);
      const derived: DerivedProvenance = {
        kind: 'stretch',
        sourceName: file.name,
        regionS: [region.startS, region.endS],
        stretch: message.stretch,
        windowSamples: message.windowSamples,
        seed: message.seed,
        gain: message.gain,
        peakGuardDb: message.peakGuardDb,
        renderMs: message.renderMs,
      };
      resolve({ name: file.name, bytes: file.bytes, probe: file.probe, buffer, file: file.file, derived });
    };
    worker.onerror = (event: ErrorEvent): void => {
      worker.onmessage = null;
      setStatus(`the stretch worker failed: ${event.message}`, 'error');
      resolve(null);
    };
    worker.postMessage(request, [mono.buffer]);
  });
}

/** The slider moved and was let go: render, or drop back to the raw file. */
async function applyStretch(factor: number): Promise<void> {
  const before = shell.stretched;
  shell.stretch = factor;
  renderStretchControl();
  if (shell.file === null) {
    return;
  }

  if (factor <= 1.001) {
    shell.stretched = null;
  } else {
    const rendered = await renderStretch(factor);
    if (rendered === null) {
      // Refused — the reason is already in the state cell, and it STAYS there.
      // Falling back to the raw file keeps the singer off a source that does
      // not exist; restarting the session on top of that would overwrite the
      // message with "live — …" before it could be read, which is what the
      // first version of this function did and what scenario (d) caught.
      shell.stretch = 1;
      shell.stretched = null;
      renderStretchControl();
      renderSource();
      return;
    }
    shell.stretched = rendered;
  }

  renderSource();
  // Only when the buffer actually changed: at 1× with nothing rendered there
  // is no new graph to build, and a restart would cost the singer the 128 ms
  // hole for nothing.
  if (shell.session !== null && shell.stretched !== before) {
    setStatus(`switching to ${describeFactor(shell.stretch)}…`);
    switching = true;
    try {
      await stop();
      await start();
    } finally {
      switching = false;
    }
  }
}

function renderStretchControl(): void {
  const slider = required<HTMLInputElement>('stretch-slider');
  const value = required<HTMLElement>('stretch-value');
  const ceiling = maxFactorForRegion();
  // The ceiling is on the CONTROL, so the refusal happens before the click.
  const maxValue = String(Math.max(0, sliderValueForFactor(ceiling)));
  if (slider.max !== maxValue) {
    slider.max = maxValue;
  }
  const text = describeStretchOutcome(shell.stretch);
  const wanted = String(sliderValueForFactor(shell.stretch));
  if (slider.value !== wanted && document.activeElement !== slider) {
    slider.value = wanted;
  }
  slider.setAttribute('aria-valuetext', text);
  value.textContent = text;
  slider.disabled = shell.file === null;

  const smear = required<HTMLInputElement>('smear-slider');
  const smearValue = required<HTMLElement>('smear-value');
  const index = STRETCH_SMEAR_CHOICES.indexOf(shell.smearS);
  if (document.activeElement !== smear) {
    smear.value = String(index < 0 ? 1 : index);
  }
  smear.setAttribute('aria-valuetext', describeSmear(shell.smearS));
  smearValue.textContent = `${shell.smearS.toFixed(2)} s`;
  smear.disabled = shell.file === null;

  // The ceiling's reason goes where the file's facts are, so a singer who
  // cannot reach 8× is told why and what to do about it in one sentence.
  const ceilingText = describeStretchCeiling();
  const facts = required<HTMLElement>('player-facts');
  if (ceilingText !== null && shell.file !== null && shell.stretched === null) {
    facts.textContent = ceilingText;
  }
}

/** What each smear setting does to the sound, in the words the control is for. */
function describeSmear(smearS: number): string {
  if (smearS <= 0.05) {
    return '0.05 s — roughest, keeps the most movement';
  }
  if (smearS <= 0.1) {
    return '0.10 s — keeps the voice moving';
  }
  if (smearS <= 0.25) {
    return '0.25 s — the reference\'s length, more of a pad';
  }
  return '0.50 s — a motionless tone, easiest to tune to';
}

/** The buffer a session should open: the render when there is one, else the decode. */
function sourceFileForSession(): DecodedAudioFile | null {
  return shell.stretched ?? shell.file;
}

/* --- the source: microphone, or a file played through the same chain --------- */

/** The preset whose rate a decode must target — the running one, else the selected one. */
function activePreset(): LivePreset | undefined {
  return shell.session?.preset ?? (shell.selected === null ? undefined : shell.presets.get(shell.selected));
}

/** The sentence under the source control. It is where "not remembered" has to be said. */
function renderSourceHint(text: string | null): void {
  const hint = required<HTMLElement>('source-hint');
  if (text === null) {
    hint.hidden = true;
    hint.textContent = '';
    return;
  }
  hint.textContent = text;
  hint.hidden = false;
}

function renderSource(): void {
  const group = required<HTMLElement>('source-control');
  for (const item of group.querySelectorAll<HTMLElement>('[role="radio"]')) {
    const checked = item.dataset['value'] === shell.source;
    item.setAttribute('aria-checked', checked ? 'true' : 'false');
    item.tabIndex = checked ? 0 : -1;
  }
  const file = shell.file;
  const fileRadio = required<HTMLButtonElement>('source-file');
  // A source with nothing behind it is not a source: the radio is unusable
  // until a file has actually decoded.
  fileRadio.disabled = file === null;
  fileRadio.textContent = file === null ? 'File' : `File: ${file.name}`;
  if (file !== null) {
    fileRadio.title = file.name;
  }
  required<HTMLElement>('player').hidden = file === null || shell.source !== 'file';
  renderStretchControl();

  // THE FACTS GO ON THE BAR, THE REFUSALS STAY IN THE RAIL. A decoded file's
  // rate and duration are the file's own furniture and belong with its
  // transport — and in the rail they cost a preset row at the 620 px floor. A
  // REFUSAL is different: the bar is hidden when no file loaded, so a refusal
  // written there would be invisible exactly when it matters. `loadFile`
  // writes those to the rail's hint, and this function never clears one.
  const facts = required<HTMLElement>('player-facts');
  if (file !== null) {
    const native =
      file.probe.sampleRateHz === null
        ? 'rate not in its header'
        : `${String(file.probe.sampleRateHz)} Hz`;
    const stretched = shell.stretched?.derived;
    facts.textContent =
      stretched === undefined
        ? `${file.name} · ${file.probe.summary} · ${native} → decoded ${String(file.buffer.sampleRate)} Hz · ` +
          `${file.buffer.duration.toFixed(2)} s · not remembered across reloads`
        : `${file.name} · stretched ${stretched.stretch.toFixed(1)}× — DERIVED, not the file · ` +
          `${(shell.stretched?.buffer.duration ?? 0).toFixed(1)} s rendered in ` +
          `${stretched.renderMs.toFixed(0)} ms · not remembered across reloads`;
    const diagnostics = required<HTMLElement>('player-diagnostics');
    diagnostics.textContent =
      stretched === undefined
        ? ''
        : `N = ${String(stretched.windowSamples)} · seed 0x${stretched.seed.toString(16)} · ` +
          `gain ×${stretched.gain.toFixed(4)} · guard ${stretched.peakGuardDb.toFixed(1)} dB`;
    renderSourceHint(shell.source === 'file' ? null : 'a file is loaded; the microphone is the active source');
  } else {
    facts.textContent = '';
  }
  // The permission sentence is about the microphone and is false for a file.
  required<HTMLElement>('capture-hint').textContent =
    shell.source === 'file'
      ? 'No microphone is opened for a file source; it plays to your output. Nothing is uploaded.'
      : 'Your browser will ask for microphone permission. Nothing is uploaded.';
}

/* --- the player bar ---------------------------------------------------------
 *
 * Everything below reads `transport.positionS()` and writes pixels. The rules
 * about WHEN a node is rebuilt are `app/transport.ts`'s and are not repeated
 * here; what this file owns is the discipline that keeps a scrub from
 * rebuilding it sixty times a second, and the one that keeps a screen reader
 * from being read a number that is moving under it.
 * -------------------------------------------------------------------------- */

/** How far ⏮/«5/5» move, in seconds. `(prov.)` — a sung phrase is 2–6 s, so 5 s lands one phrase either side. */
const SKIP_SECONDS = 5;

/** The playhead's own tick, ms. Faster than the 500 ms counters (too coarse to scrub against), slower than the hop (a DOM write per frame). */
const PLAYHEAD_TICK_MS = 100;

let playheadTimer: number | null = null;

/**
 * True while the singer is dragging the seek, or has it focused.
 *
 * Two different reasons, one flag. A ticker that wrote `.value` mid-drag would
 * fight the thumb under the pointer; a ticker that wrote it while the slider
 * has keyboard focus would move the value a screen reader is sitting on, which
 * is the announcement storm ADR 0012 d.6 forbids — and the reader would then
 * be told a number the user did not choose.
 */
let seekHeld = false;

function seekInput(): HTMLInputElement {
  return required<HTMLInputElement>('transport-seek');
}

/** The transport row, from the session's own state. Never writes a held or focused control. */
function renderTransport(): void {
  const transport = shell.session?.transport ?? null;
  const play = required<HTMLButtonElement>('transport-play');
  const loop = required<HTMLButtonElement>('transport-loop');
  const glyph = loop.querySelector<HTMLElement>('.transport__glyph');
  const seek = seekInput();

  const state: TransportState | null = transport?.state() ?? null;
  const looping = state?.loop ?? shell.fileLoop;
  loop.setAttribute('aria-pressed', looping ? 'true' : 'false');
  if (glyph !== null) {
    glyph.textContent = looping ? '◉' : '○';
  }
  // Play/Pause is an ACTION, so its label is the action and it carries no
  // `aria-pressed`; Loop is a STATE, so it carries one and keeps its label.
  play.textContent = state?.phase === 'playing' ? '⏸ Pause' : '▶ Play';
  play.disabled = transport === null;
  for (const id of ['transport-home', 'transport-back', 'transport-fwd', 'region-set-a', 'region-set-b']) {
    required<HTMLButtonElement>(id).disabled = transport === null;
  }
  // The two resets stamp the FILE'S OWN EDGES, so they need a decoded file and
  // not a running transport — unlike A and B, which stamp a playhead that does
  // not exist until Play has been pressed.
  const decodedS = shell.session?.transport?.state().durationS ?? shell.file?.buffer.duration ?? 0;
  for (const id of ['region-reset-a', 'region-reset-b']) {
    required<HTMLButtonElement>(id).disabled = decodedS <= 0;
  }
  seek.disabled = transport === null;

  const durationS = state?.durationS ?? shell.file?.buffer.duration ?? 0;
  if (seek.max !== durationS.toFixed(1)) {
    seek.max = durationS.toFixed(1);
  }

  const region = state?.region ?? shell.fileRegion ?? (durationS > 0 ? { startS: 0, endS: durationS } : null);
  if (region !== null && region !== undefined) {
    // A reset whose endpoint is already at the file's edge would do nothing;
    // a button that does nothing when pressed is worse than one that is
    // visibly unavailable, and `disabled` is a state a screen reader reads.
    required<HTMLButtonElement>('region-reset-a').disabled ||= region.startS === 0;
    required<HTMLButtonElement>('region-reset-b').disabled ||= region.endS === durationS;
    renderLoopBand(region, durationS);
  }
  renderPlayhead();
}

/**
 * The hatched band behind the seek track.
 *
 * Positioned in percent of the track's own box, so it needs no measurement and
 * survives a resize without a listener. The thumb travels the full width of
 * the input, so band and thumb share one coordinate system and the e2e can
 * check one against the other in pixels.
 */
function renderLoopBand(region: Region, durationS: number): void {
  const band = required<HTMLElement>('player-region');
  if (!(durationS > 0)) {
    band.style.left = '0%';
    band.style.width = '0%';
    return;
  }
  const left = Math.max(0, Math.min(1, region.startS / durationS));
  const right = Math.max(left, Math.min(1, region.endS / durationS));
  band.style.left = `${String(left * 100)}%`;
  band.style.width = `${String((right - left) * 100)}%`;
}

/** The thumb and the clock. Called on the tick and on every state change. */
function renderPlayhead(): void {
  const transport = shell.session?.transport ?? null;
  const seek = seekInput();
  const time = required<HTMLElement>('transport-time');
  const positionS = transport?.positionS() ?? shell.fileRegion?.startS ?? 0;
  const durationS = transport?.state().durationS ?? shell.file?.buffer.duration ?? 0;

  time.textContent = `${formatSeconds(positionS)} / ${formatSeconds(durationS)}`;
  if (seekHeld) {
    // The singer owns the thumb until they let go; see `seekHeld`.
    return;
  }
  const shown = positionS.toFixed(1);
  if (seek.value !== shown) {
    seek.value = shown;
  }
  // `aria-valuetext` moves with the value and NOT more often: it is written
  // here only because the value it describes was just written here.
  seek.setAttribute('aria-valuetext', formatSeconds(positionS));
}

/** Run the playhead only while something is playing — a timer over a paused file writes the same pixels forever. */
function syncPlayheadTimer(): void {
  const playing = shell.session?.transport?.state().phase === 'playing';
  if (playing && playheadTimer === null) {
    playheadTimer = window.setInterval(renderPlayhead, PLAYHEAD_TICK_MS);
  } else if (!playing && playheadTimer !== null) {
    window.clearInterval(playheadTimer);
    playheadTimer = null;
  }
}

/** The state cell's sentence for a running file session. */
function transportSentence(): string {
  const session = shell.session;
  const transport = session?.transport ?? null;
  const name = shell.file?.name ?? 'file';
  if (session === null || transport === null) {
    return '';
  }
  const state = transport.state();
  const derived = session.chain.source === 'file' ? session.chain.derived : null;
  const what = derived === null ? `File: ${name}` : `File: ${name} · stretched ${derived.stretch.toFixed(1)}×`;
  switch (state.phase) {
    case 'playing':
      return `live — ${session.preset.name} · ${what} · playing`;
    case 'paused':
      return `live — ${session.preset.name} · ${what} · paused at ${formatSeconds(state.positionS)}`;
    case 'ended':
      return `live — ${session.preset.name} · ${what} · ended — Play restarts at ${formatSeconds(state.region.startS)}`;
    default:
      return `live — ${session.preset.name} · ${what} · stopped — press Play`;
  }
}

function wireTransport(session: Session): void {
  shell.transportOff?.();
  shell.transportOff = null;
  const transport = session.transport;
  if (transport === null) {
    renderTransport();
    return;
  }
  shell.transportOff = transport.subscribe((event) => {
    if (event !== 'state') {
      return;
    }
    // The shell keeps the loop and region so they survive a preset switch,
    // which tears the session down and builds a new one.
    const state = transport.state();
    shell.fileLoop = state.loop;
    shell.fileRegion = state.region;
    renderTransport();
    // A new A–B changes what the stretch would render, and therefore what the
    // slider may offer.
    renderStretchControl();
    syncPlayheadTimer();
    setStatus(transportSentence(), 'live');
  });
  renderTransport();
  syncPlayheadTimer();
}

/**
 * Read, probe and decode a chosen file. Refusals land in the state cell with
 * the browser's own reason — an undecodable file is something the singer did,
 * and a console is not where they will look.
 */
async function loadFile(file: File): Promise<DecodedAudioFile | FileLoadRefusal> {
  const preset = activePreset();
  if (preset === undefined) {
    const refusal: FileLoadRefusal = {
      refused: true,
      reason: 'read',
      message: 'the presets have not loaded yet — a file is decoded at the preset\'s own rate',
    };
    setStatus(refusal.message, 'error');
    return refusal;
  }
  setStatus(`decoding ${file.name} at ${String(preset.sampleRateHz)} Hz…`);
  shell.decodeCount += 1;
  const result = await decodeAudioFile(file, preset.sampleRateHz, preset.fftSize);
  if (isFileLoadRefusal(result)) {
    setStatus(result.message, 'error');
    renderSourceHint(result.message);
    return result;
  }
  // A new file replaces every rate's buffer: they were the old file's.
  shell.decodedByRate.clear();
  shell.decodedByRate.set(result.buffer.sampleRate, result);
  // A render belongs to the file and the region it was made from; a new file
  // invalidates it, and the slider goes back to 1× rather than silently
  // describing the old stem.
  shell.stretched = null;
  shell.stretch = 1;
  shell.file = result;
  shell.source = 'file';
  shell.fileLoop = false;
  shell.fileRegion = { startS: 0, endS: result.buffer.duration };
  renderSource();
  renderTransport();
  if (shell.session === null) {
    setStatus(`${result.name} ready — press Start`);
  }
  return result;
}

/** Decode this file for `sampleRateHz` if no buffer for it exists yet. */
async function decodedForRate(sampleRateHz: number, fftSize: number): Promise<DecodedAudioFile | FileLoadRefusal> {
  const cached = shell.decodedByRate.get(sampleRateHz);
  if (cached !== undefined) {
    return cached;
  }
  const file = shell.file;
  if (file === null) {
    return { refused: true, reason: 'read', message: 'no file is loaded' };
  }
  // The `File` is re-read rather than the ArrayBuffer reused: decodeAudioData
  // detaches what it is handed, so the bytes of the first decode are gone.
  setStatus(`decoding ${file.name} at ${String(sampleRateHz)} Hz…`);
  shell.decodeCount += 1;
  const result = await decodeAudioFile(file.file, sampleRateHz, fftSize);
  if (isFileLoadRefusal(result)) {
    setStatus(result.message, 'error');
    return result;
  }
  shell.decodedByRate.set(sampleRateHz, result);
  return result;
}

async function selectSource(kind: SourceKind): Promise<void> {
  if (kind === shell.source) {
    return;
  }
  if (kind === 'file' && shell.file === null) {
    return;
  }
  shell.source = kind;
  renderSource();
  if (shell.session === null) {
    return;
  }
  // A source change is a different graph: restart, the way a preset switch
  // does, and say so while the gap lasts.
  setStatus(kind === 'file' ? `switching to ${shell.file?.name ?? 'the file'}…` : 'switching to the microphone…');
  switching = true;
  try {
    await stop();
    await start();
  } finally {
    switching = false;
  }
}

/** `validateRegion` without importing it twice; the shell has no duration of its own. */
function validateRegionForShell(startS: number, endS: number | null, durationS: number): Region | RegionRefusal {
  return validateRegion(startS, endS, durationS);
}

function renderClip(latched: boolean): void {
  const cell = required<HTMLElement>('readout-clip');
  cell.textContent = latched ? 'CLIP' : 'clear';
  cell.dataset['kind'] = latched ? 'clip' : 'clear';
}

/* --- the rail: presets, tolerance, mode ------------------------------------- */

/**
 * One radio group's keyboard behaviour, used by all three.
 *
 * Roving tabindex and arrow keys are what `role="radiogroup"` promises a
 * screen-reader user; a group of six buttons that each take a tab stop is six
 * tab stops between Start and the canvas. Selection follows focus, which is the
 * ARIA pattern for a radio group and is also what makes the arrow keys useful
 * on this page — arrowing through the presets while stopped changes the
 * selection and nothing else.
 *
 * The listeners are DELEGATED to the group, not attached per item, because the
 * preset rail is rebuilt when the served list arrives.
 */
function wireRadiogroup(group: HTMLElement, onSelect: (value: string) => void): void {
  const radios = (): HTMLElement[] => Array.from(group.querySelectorAll<HTMLElement>('[role="radio"]'));
  const choose = (item: HTMLElement | null): void => {
    if (item === null || (item as HTMLButtonElement).disabled) {
      return;
    }
    const value = item.dataset['value'];
    if (value !== undefined) {
      onSelect(value);
    }
  };

  group.addEventListener('click', (event) => {
    const target = event.target as Element | null;
    choose(target?.closest<HTMLElement>('[role="radio"]') ?? null);
  });

  group.addEventListener('keydown', (event) => {
    const forward = event.key === 'ArrowRight' || event.key === 'ArrowDown';
    const back = event.key === 'ArrowLeft' || event.key === 'ArrowUp';
    const home = event.key === 'Home';
    const end = event.key === 'End';
    if (!forward && !back && !home && !end) {
      return;
    }
    const items = radios();
    if (items.length === 0) {
      return;
    }
    const target = event.target as Element | null;
    const active = target?.closest<HTMLElement>('[role="radio"]') ?? null;
    const index = active === null ? -1 : items.indexOf(active);
    const wrapped = (i: number): HTMLElement => items[((i % items.length) + items.length) % items.length] as HTMLElement;
    const next = home
      ? wrapped(0)
      : end
        ? wrapped(items.length - 1)
        : wrapped(index < 0 ? 0 : index + (forward ? 1 : -1));
    event.preventDefault();
    next.focus();
    choose(next);
  });
}

/**
 * One preset, as a radio.
 *
 * Marked THREE ways when it is the selected one — the ◉/○ glyph, the 4 px
 * accent bar from `app.css`, and the weight — because a rail that marked it by
 * tint alone would encode state in colour (WCAG 1.4.1, ADR 0012 d.6). The
 * guidance line is filled later, from the SERVED preset: `check-no-bundled-
 * presets.mjs` greps the backend build for that exact text, so a copy in this
 * bundle would fail the build (ADR 0021 decision 7a).
 */
function presetOption(summary: PresetSummary): HTMLOptionElement {
  const option = document.createElement('option');
  option.value = summary.id;
  // `id` kept so `#preset-<id>` still addresses the choice from a harness and
  // from the roadmap's own prose, even though an <option> is not a control.
  option.id = `preset-${summary.id}`;
  option.textContent = summary.name;
  return option;
}

function presetSelect(): HTMLSelectElement {
  return required<HTMLSelectElement>('preset-select');
}

function renderPresetRail(): void {
  const select = presetSelect();
  select.replaceChildren(...shell.summaries.map(presetOption));
  select.disabled = shell.summaries.length === 0;
  markPresetRail();
  renderPresetGuidance();
}

/**
 * Which one is selected.
 *
 * Never written while the menu has focus: on a `<select>` that would fight the
 * keyboard the way writing a focused slider's `.value` fights the thumb, and
 * for the same reason (`renderTransport`'s note on the seek).
 */
function markPresetRail(): void {
  const select = presetSelect();
  if (document.activeElement !== select && shell.selected !== null) {
    select.value = shell.selected;
  }
}

/** The first sentence of the SELECTED preset's own `guidance`. */
function renderPresetGuidance(): void {
  const preset = shell.selected === null ? undefined : shell.presets.get(shell.selected);
  required<HTMLElement>('preset-guidance').textContent =
    preset === undefined ? '' : firstSentence(preset.guidance);
}

/**
 * The six digests, in full. They are provenance, not a control, so they live
 * behind the footer's door with the rest of the diagnostics — but they are
 * rendered whole rather than truncated, because a truncated hash is a hash
 * nobody can compare against `sha256sum protocols/presets/<id>.json`.
 */
function renderPresetDigests(): void {
  const list = required<HTMLUListElement>('preset-digests');
  if (shell.summaries.length === 0) {
    return;
  }
  list.replaceChildren(
    ...shell.summaries.map((summary) => {
      const item = document.createElement('li');
      const name = document.createElement('span');
      name.textContent = summary.name;
      const digest = document.createElement('code');
      digest.className = 'preset__sha';
      digest.textContent = summary.sha256;
      digest.title = `sha256 of ${String(summary.bytes)} bytes served at ${summary.url}`;
      item.append(name, digest);
      return item;
    }),
  );
}

function renderTolerance(): void {
  const group = required<HTMLElement>('tolerance-control');
  for (const item of group.querySelectorAll<HTMLElement>('[role="radio"]')) {
    const checked = item.dataset['value'] === String(shell.tolerance);
    item.setAttribute('aria-checked', checked ? 'true' : 'false');
    item.tabIndex = checked ? 0 : -1;
  }
}

function renderMode(): void {
  required<HTMLElement>('app').dataset['mode'] = shell.mode;
  const group = required<HTMLElement>('mode-control');
  for (const item of group.querySelectorAll<HTMLElement>('[role="radio"]')) {
    const checked = item.dataset['value'] === shell.mode;
    item.setAttribute('aria-checked', checked ? 'true' : 'false');
    item.tabIndex = checked ? 0 : -1;
  }
}

/** Everything a change of band moves, in one place. */
function applyTolerance(tolerance: Tolerance): void {
  shell.tolerance = tolerance;
  shell.constants = withTolerance(REFERENCE_CONSTANTS, tolerance);
  renderTolerance();
  layoutCentsBar();
  renderConstants();
  if (shell.session === null) {
    renderMatch(matchState(null, shell.reference, activeConstants()), null);
  } else {
    // The session re-judges its last frame under the new band and reports it
    // through `onMatch`, which lands back in `renderMatch` — one path, so the
    // cell and the session's own `lastMatch` cannot end up in different bands.
    shell.session.setTolerance(tolerance);
  }
}

function wireTolerance(): void {
  wireRadiogroup(required<HTMLElement>('tolerance-control'), (value) => {
    tolerancePref.set(parseTolerance(value));
  });
  tolerancePref.subscribe(applyTolerance);
}

/* --- The rail's two levels ---------------------------------------------
 *
 * The width query, once, as a module constant: `matchMedia` is the only way to
 * ask CSS which layout is in force without measuring, and asking it twice with
 * two strings is how the two halves of a breakpoint drift apart. This string
 * and the `@media (min-width: 840px)` in `app.css` are the same breakpoint and
 * must stay so (ADR 0024 decision 2).
 * ---------------------------------------------------------------------- */
const WIDE_LAYOUT = window.matchMedia('(min-width: 840px)');

/**
 * Open or closed, resolving the *no stored choice* case against the width.
 *
 * Open by default on a laptop, closed on a phone. That asymmetry is the whole
 * point: hiding desktop navigation by default costs measured discoverability
 * ([12 R13]), while a phone analyzer should open on the analyzer ([12 R24]).
 */
function effectiveRail(): RailState {
  return railPref.get() ?? (WIDE_LAYOUT.matches ? 'open' : 'closed');
}

function renderRail(): void {
  const open = effectiveRail() === 'open';
  const app = required<HTMLElement>('app');
  // Only an explicit choice reaches the DOM as `data-rail`; the CSS reads its
  // ABSENCE as "this width's default", which is what lets one stylesheet serve
  // a laptop that defaults open and a phone that defaults closed.
  const stored = railPref.get();
  if (stored === null) {
    delete app.dataset['rail'];
  } else {
    app.dataset['rail'] = stored;
  }
  const toggle = required<HTMLButtonElement>('rail-toggle');
  toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  // Four labels, because the same control does two different things: on a
  // laptop it hides a column, on a phone it closes a sheet, and a label that
  // said "hide" while a sheet slid up would be describing the wrong gesture.
  const wide = WIDE_LAYOUT.matches;
  const label = wide
    ? (open ? 'Hide controls' : 'Controls')
    : (open ? 'Close' : 'Controls');
  required<HTMLElement>('rail-toggle-label').textContent = label;
  const glyph = toggle.querySelector<HTMLElement>('.rail__toggle-glyph');
  if (glyph !== null) {
    glyph.textContent = wide ? (open ? '◂' : '▸') : (open ? '▾' : '▴');
  }
}

/**
 * While an overlay is over the content, WHAT IT COVERS — and only what it
 * covers — is inert.
 *
 * The page has exactly two overlays and both open upward: `.chain-body`, the
 * diagnostics door, at either layout; and `#rail-more`, the bottom sheet, on a
 * narrow one, where it rises over the canvas column and so over the player
 * bar. Neither is modal and neither has a scrim, which is why this exists.
 *
 * `.chain-body` opens UPWARD out of the footer's flow so that the canvases
 * never resize; on a wide layout the footer spans both grid columns, so the
 * panel lies over the rail as well, and measured at 898x620 it covered TWELVE
 * focusable controls that were still in the tab ring. A component that takes
 * focus while entirely hidden is WCAG 2.4.11, and the criterion's own
 * Understanding names this remedy first: make the thing modal, so it has to be
 * dismissed before you navigate past it.
 *
 * The overlap is COMPUTED, PER CONTROL, rather than assumed per container. It
 * differs with the viewport — measured 2026-08-23, the panel covers the rail
 * at every size but reaches the player bar only on a short window (at 898x420
 * yes; at 898x620, 1280x800 and 390x844 no) — and it differs WITHIN a
 * container: at 898x620 the rail runs 123..574 and the panel only 335..583, so
 * Start, at the top of the rail, is nowhere near it. Two successive versions
 * of this function inerted a container and killed a control that was plainly
 * visible and covered by nothing. A dead control that looks alive is the thing
 * this interface spends its comments avoiding.
 *
 * The glance bar sits above the panel and keeps its mode control, and the
 * `<summary>` is outside every region — so the way out is always focusable,
 * which is the other half of the same rule.
 */
function shieldUnderOverlays(): void {
  const door = required<HTMLDetailsElement>('capture-chain');
  const chainBody = door.querySelector<HTMLElement>('.chain-body');
  const sheet = required<HTMLElement>('rail-more');
  const app = required<HTMLElement>('app');
  const regions = [required<HTMLElement>('rail'), required<HTMLElement>('canvas-column')];
  const controls = (): HTMLElement[] =>
    regions.flatMap((region) =>
      Array.from(region.querySelectorAll<HTMLElement>('button, input, [role="radio"]')),
    );
  const overlaps = (a: DOMRect, b: DOMRect): boolean =>
    !(a.bottom <= b.top || a.top >= b.bottom || a.right <= b.left || a.left >= b.right);
  /** An overlay that is currently OVER the content, with its rect. */
  interface Overlay {
    readonly element: HTMLElement;
    readonly rect: DOMRect;
  }
  const overlay = (element: HTMLElement | null, open: boolean): Overlay | null => {
    if (element === null || !open || element.offsetParent === null) {
      return null;
    }
    // On a laptop `#rail-more` is `position: static` — part of the rail's own
    // column, over nothing at all. Only an out-of-flow overlay shields.
    return getComputedStyle(element).position === 'static'
      ? null
      : { element, rect: element.getBoundingClientRect() };
  };
  const apply = (): void => {
    const panels = [
      overlay(chainBody, door.open),
      overlay(sheet, app.dataset['rail'] !== 'closed'),
    ].filter((panel): panel is Overlay => panel !== null);
    for (const control of controls()) {
      // PER CONTROL, not per container. Inerting `#rail` wholesale disabled
      // Start — which sits at the top of the rail, well clear of a panel that
      // opens from the bottom — and inerting the canvas column disabled the
      // player bar at every viewport where the panel does not reach it. A
      // control that is visible, uncovered and dead is worse than one that is
      // hidden, which is the whole reason this is geometry and not a list.
      //
      // A control inside an overlay is never shielded BY THAT overlay — the
      // sheet's own presets would otherwise switch themselves off the moment
      // it opened — but it is still shielded by the OTHER one. The
      // containment test is therefore per panel and not global: on a laptop
      // `#rail-more` is a plain container, and the fifteen controls inside it
      // are exactly the ones the footer's panel covers.
      const box = control.getBoundingClientRect();
      control.inert =
        control.offsetParent !== null &&
        panels.some((panel) => !panel.element.contains(control) && overlaps(panel.rect, box));
    }
  };
  door.addEventListener('toggle', apply);
  // The sheet has no toggle event of its own; `renderRail` writes `data-rail`
  // on `#app`, and a mode change moves what is under it.
  new MutationObserver(apply).observe(app, { attributes: true, attributeFilter: ['data-rail', 'data-mode'] });
  // Both overlaps move with the viewport, and either can be open across a
  // resize.
  window.addEventListener('resize', apply);
  apply();
}

function wireRail(): void {
  const toggle = required<HTMLButtonElement>('rail-toggle');
  toggle.addEventListener('click', () => {
    railPref.set(effectiveRail() === 'open' ? 'closed' : 'open');
  });
  railPref.subscribe(() => { renderRail(); });
  // The label and the default both depend on the width, so a resize past the
  // breakpoint has to re-render even when nothing was stored.
  WIDE_LAYOUT.addEventListener('change', () => { renderRail(); });
  // Escape closes the sheet and gives the focus back to the control that
  // opened it — the disclosure pattern's own rule, and the one thing that
  // makes an overlay on a phone dismissible without hunting for its edge.
  required<HTMLElement>('rail').addEventListener('keydown', (event) => {
    if (event.key !== 'Escape' || WIDE_LAYOUT.matches || effectiveRail() !== 'open') {
      return;
    }
    railPref.set('closed');
    toggle.focus();
  });
}

/* --- Tune ---------------------------------------------------------------
 *
 * A DISPLAY, NOT A SECOND ESTIMATOR. Every number here comes from the same
 * frame the glance bar reads; `app/tuner-display.ts` filters it for a human
 * and keeps the raw one beside it, and this function is the only place the
 * filtered one reaches the DOM.
 * ---------------------------------------------------------------------- */

/** The one-pole coefficient for the running preset's hop at the set damping. */
function alphaFor(hopS: number): number {
  return shell.dampingMs <= 0 ? 1 : dampingAlpha(hopS, shell.dampingMs / 1000);
}

/** One setting, two surfaces: the glance bar's needle and Tune's big number. */
function applyDamping(ms: number): void {
  shell.dampingMs = ms;
  const preset = shell.session?.preset ?? null;
  shell.needleAlpha = alphaFor(preset === null ? 0.02 : preset.hopSamples / preset.sampleRateHz);
  const slider = required<HTMLInputElement>('tuner-damping');
  if (document.activeElement !== slider) {
    slider.value = String(ms);
  }
  const label = ms <= 0 ? 'off' : `${String(ms)} ms`;
  slider.setAttribute('aria-valuetext', label);
  required<HTMLElement>('tuner-damping-out').textContent = label;
  required<HTMLElement>('tuner-damping-value').textContent = describeDamping(ms, shell.tunerHeld);
}

/**
 * Advance the filter by one frame, then paint. Called from `onMatch`, and from
 * nowhere else — which is once per hop, plus one extra step on a deliberate
 * tolerance change, where `session.ts` re-posts the last frame so the band is
 * re-judged at once.
 */
function stepTuner(frame: FrameMessage | null, match: MatchState | null): void {
  if (shell.mode !== 'tune') {
    return;
  }
  const preset = shell.session?.preset ?? null;
  const hopS = preset === null ? 0.02 : preset.hopSamples / preset.sampleRateHz;
  // `frame.f0 === null` is the shell's own "this preset has no f0 overlay",
  // the same test `renderMatch` makes; a running session with an estimator
  // reports an f0 object whose `f0Hz` may itself be null for a silent frame.
  const estimatorOff = frame !== null && frame.f0 === null;
  shell.tuner = tunerStep(
    shell.tuner,
    {
      f0Hz: frame?.f0?.f0Hz ?? null,
      clarity: frame?.f0?.clarity ?? 0,
      match,
      estimatorOff,
    },
    {
      alpha: alphaFor(hopS),
      hysteresisCents: TUNER_HYSTERESIS_CENTS,
      acceptFrames: TUNER_ACCEPT_FRAMES,
      staleFrames: TUNER_STALE_FRAMES,
      a4Hz: A4_HZ,
      held: shell.tunerHeld,
    },
    activeConstants(),
  );
  paintTuner();
}

/**
 * Write the state that is already in hand to the DOM. Separate from the step
 * because HOLD has to redraw AT ONCE — a freeze that waited for the next frame
 * would look like a missed press — and advancing the machine to do it would
 * feed it a frame that never existed. It used to be called with a `null`
 * frame, which the machine correctly read as SILENCE: every release of HOLD
 * added a spurious unvoiced frame to the stale counter.
 */
function paintTuner(): void {
  const { drawn, measured } = shell.tuner;
  const section = required<HTMLElement>('tuner');
  section.dataset['state'] = drawn.state;
  section.dataset['held'] = shell.tunerHeld ? 'true' : 'false';
  section.dataset['stale'] = drawn.stale ? 'true' : 'false';
  required<HTMLElement>('tuner-note').textContent = drawn.label ?? '—';
  required<HTMLElement>('tuner-cents').textContent =
    drawn.cents === null ? '—' : formatCents(drawn.cents);

  const glyph = required<HTMLElement>('tuner-match-glyph');
  const text = required<HTMLElement>('tuner-match-text');
  if (drawn.state === 'off') {
    glyph.textContent = '—';
    text.textContent = NO_F0_OVERLAY;
  } else if (drawn.cents === null) {
    glyph.textContent = '—';
    text.textContent = 'no pitch';
  } else if (drawn.state === 'in') {
    glyph.textContent = '✓';
    text.textContent = 'in tune';
  } else {
    glyph.textContent = drawn.direction === 'sharp' ? '▲' : '▼';
    text.textContent = `${drawn.direction ?? 'sharp'} ${String(Math.round(Math.abs(drawn.cents)))}¢`;
  }

  // THE MEASURED LINE, and it is not the drawn one. It goes silent the instant
  // the voice does, even while the reading above it is still being held.
  required<HTMLElement>('tuner-hz').textContent =
    measured.f0Hz === null
      ? `unvoiced · clarity ${measured.clarity.toFixed(2)}`
      : `${measured.f0Hz.toFixed(2)} Hz · clarity ${measured.clarity.toFixed(2)}`;
  required<HTMLElement>('tuner-reference').textContent = tunerReferenceLine(shell.reference, A4_HZ);
  required<HTMLElement>('tuner-damping-value').textContent = describeDamping(shell.dampingMs, shell.tunerHeld);

  const needle = required<SVGGElement>('tuner-meter-needle');
  const fraction =
    drawn.cents === null ? null : Math.max(-1, Math.min(1, drawn.cents / activeConstants().barSpanCents));
  if (fraction === null) {
    needle.dataset['visible'] = 'false';
  } else {
    needle.dataset['visible'] = 'true';
    needle.setAttribute('transform', `translate(${String(barX(fraction) - BAR.centre)} 0)`);
  }
}

function wireTuner(): void {
  const hold = required<HTMLButtonElement>('tuner-hold');
  hold.addEventListener('click', () => {
    shell.tunerHeld = !shell.tunerHeld;
    hold.setAttribute('aria-pressed', shell.tunerHeld ? 'true' : 'false');
    // Redraw from the state already in hand; do not advance the machine.
    if (shell.mode === 'tune') {
      paintTuner();
    }
    required<HTMLElement>('tuner-damping-value').textContent = describeDamping(shell.dampingMs, shell.tunerHeld);
  });
  const slider = required<HTMLInputElement>('tuner-damping');
  // The markup's bounds and the parser's are one source: a slider that could
  // reach a value `parseDampingMs` snaps away from would fight the singer.
  slider.min = String(DAMPING_MS.min);
  slider.max = String(DAMPING_MS.max);
  slider.step = String(DAMPING_MS.step);
  slider.addEventListener('input', () => { dampingPref.set(parseDampingMs(slider.value)); });
  dampingPref.subscribe(applyDamping);
}

/**
 * Put a mode on screen. Idempotent, and it does NOT touch the preference.
 *
 * Separate from persisting it because `?mode=` deliberately leaves the two out
 * of step: the URL decides the page view, the preference decides the next
 * visit. Driving the control through the preference alone then breaks one
 * button — `createStoredPreference.set` returns early when the value is
 * unchanged, so clicking the segment for the STORED mode notifies nobody and
 * that segment is dead for the rest of the page view. `tuner.spec.ts` (g)
 * presses exactly that button.
 */
function applyMode(mode: Mode): void {
  if (shell.mode === mode) {
    renderMode();
    return;
  }
  shell.mode = mode;
  // A mode change is a new phrase as far as the reading is concerned: the
  // note it was smoothing towards may not even be drawn any more.
  shell.tuner = TUNER_INITIAL;
  renderMode();
  // Every canvas has a new box now. The ResizeObserver catches the ones whose
  // measured box changed, but the spectrum going from `display: none` to
  // visible with capture STOPPED has no next frame to be repainted by, and
  // would keep the backing store it was sized with while hidden.
  shell.session?.refreshPalette();
}

function wireMode(): void {
  wireRadiogroup(required<HTMLElement>('mode-control'), (value) => {
    const mode = parseMode(value);
    // Apply first, THEN persist: an explicit click is a choice and is
    // remembered, and the apply does not depend on the preference having
    // changed for it to happen.
    applyMode(mode);
    modePref.set(mode);
  });
  modePref.subscribe(applyMode);
}

/**
 * Choose a preset — and, if one is running, restart under it.
 *
 * A hot switch is not available: `stem_analysis` runs at 48 kHz and a rate
 * change cannot be applied to a live `AudioContext` at all, W2's `switchPreset`
 * is unbuilt, and a rail button that visibly does nothing is the complaint this
 * layout exists to answer. The reference is the shell's and survives the
 * restart, so the only cost is the gap the status cell names.
 */
let switching = false;

async function selectPreset(id: string): Promise<void> {
  if (id === shell.selected || !shell.summaries.some((p) => p.id === id)) {
    return;
  }
  shell.selected = id;
  markPresetRail();
  renderConstants();
  if (shell.session === null) {
    return;
  }
  setStatus(`switching to ${shell.presets.get(id)?.name ?? id}…`);
  switching = true;
  try {
    await stop();
    await start(id);
  } finally {
    switching = false;
  }
}

function errorLine(what: string, error: unknown): HTMLParagraphElement {
  const line = document.createElement('p');
  line.className = 'error rail__hint';
  line.textContent =
    error instanceof ApiError
      ? `${what}: ${error.code} — ${error.message} (HTTP ${String(error.status)})`
      : `${what}: ${error instanceof Error ? error.message : String(error)}`;
  return line;
}

async function loadPresets(): Promise<void> {
  try {
    required<HTMLElement>('presets-provenance').textContent = `(${presetsSource.provenance})`;
    const summaries = await presetsSource.list();
    shell.summaries = summaries;
    // `live_singing` is the preset the founding document's waterfall is about,
    // so it is the one a visitor should land on. Falling back to the first
    // served id keeps this working if the set is ever edited.
    shell.selected =
      summaries.find((p) => p.id === 'live_singing')?.id ?? summaries[0]?.id ?? null;
    renderPresetRail();
    renderPresetDigests();

    // Sources are fetched as TEXT and parsed here; the digest shown in the
    // footer is over the bytes, and this parse never feeds it (decision 7a).
    await Promise.all(
      summaries.map(async (summary) => {
        try {
          const source = await presetsSource.source(summary.id);
          shell.presets.set(summary.id, readLivePreset(JSON.parse(source)));
        } catch (error) {
          // Beside the menu, not inside it: an <option> is not a place to put
          // a sentence, and the one preset that failed must not be the one the
          // menu is showing.
          required<HTMLElement>('preset-list').append(
            errorLine(
              summary.id,
              error instanceof PresetRejected ? new Error(`rejected at ${error.pointer}: ${error.message}`) : error,
            ),
          );
        }
      }),
    );
    renderPresetGuidance();
  } catch (error) {
    presetSelect().disabled = true;
    required<HTMLElement>('preset-list').append(errorLine('presets unavailable', error));
  }
}

async function renderVersion(): Promise<void> {
  const target = required<HTMLElement>('backend-version');
  if (!presetsSource.capabilities.backend) {
    // A STATUS, never an error: on the owner's site there is no backend by
    // design, and a red "unreachable" would report a fault where there is none.
    // What matters to a reader is where the digests below came from.
    target.textContent = `standalone build — ${presetsSource.provenance}`;
    return;
  }
  try {
    const version = await api.getVersion();
    const api_ = version.api === undefined ? '' : ` · api ${version.api}`;
    target.textContent = `backend: ${version.version}${api_}`;
  } catch (error) {
    target.textContent =
      error instanceof ApiError
        ? `backend unreachable: ${error.code} (HTTP ${String(error.status)})`
        : `backend unreachable: ${error instanceof Error ? error.message : String(error)}`;
    target.classList.add('error');
  }
}

/* --- start / stop --------------------------------------------------------- */

let countersTimer: number | null = null;

function renderTelemetry(): void {
  renderCounters();
  renderFooterSummary();
}

async function start(presetId?: string): Promise<void> {
  if (shell.session !== null) {
    return;
  }
  const id = presetId ?? shell.selected;
  if (id === null) {
    setStatus('no preset selected', 'error');
    return;
  }
  const preset = shell.presets.get(id);
  if (preset === undefined) {
    setStatus(`preset ${id} was not loaded — see the preset list`, 'error');
    return;
  }
  const button = required<HTMLButtonElement>('capture-button');
  button.disabled = true;

  // The source, resolved before anything is opened. For a file this may mean a
  // decode — `stem_analysis` runs at 48 kHz and the buffer in hand was decoded
  // for 32 — and a refusal here must not leave a half-open graph.
  let source: SourceRequest = { kind: 'microphone' };
  if (shell.source === 'file') {
    if (shell.file === null) {
      setStatus('choose a file first — the "Choose file…" control opens the picker', 'error');
      button.disabled = false;
      return;
    }
    // The RENDER when the slider is off 1×, the decode otherwise. A render is
    // already at the preset's rate (it was made from that rate's decode), so
    // it never goes through `decodedForRate`.
    const rendered = sourceFileForSession();
    const decoded =
      rendered?.derived === undefined
        ? await decodedForRate(preset.sampleRateHz, preset.fftSize)
        : rendered;
    if (isFileLoadRefusal(decoded)) {
      button.disabled = false;
      return;
    }
    source = {
      kind: 'file',
      file: decoded,
      // A render IS the region, so its own loop runs end to end; the raw
      // file's region is the shell's and is restored when the slider returns
      // to 1×.
      loop: decoded.derived === undefined ? shell.fileLoop : true,
      region: decoded.derived === undefined ? shell.fileRegion : null,
      // Start PLAYS. One press: the owner's choice — the microphone starts
      // making sound the moment it opens, and a file that sat silent until a
      // second press would be the odd one out.
      autoplay: true,
    };
  }

  setStatus(
    shell.source === 'file'
      ? `opening ${shell.file?.name ?? 'the file'} for ${preset.name}…`
      : `opening the microphone for ${preset.name}…`,
  );
  try {
    const sha256 = shell.summaries.find((p) => p.id === id)?.sha256;
    shell.session = await startSession({
      preset,
      source,
      canvas: required<HTMLCanvasElement>('spectrum-canvas'),
      waterfallCanvas: required<HTMLCanvasElement>('waterfall-canvas'),
      overlayCanvas: required<HTMLCanvasElement>('waterfall-overlay'),
      axisCanvas: required<HTMLCanvasElement>('axis-canvas'),
      pitchCanvas: required<HTMLCanvasElement>('pitch-canvas'),
      tolerance: shell.tolerance,
      ...(sha256 === undefined ? {} : { presetSha256: sha256 }),
      callbacks: {
        onChain: () => { renderChain(shell.session); },
        onFrame: (frame) => {
          renderFrame(frame);
          frameListeners.forEach((listener) => { listener(frame); });
        },
        onMatch: (match, frame) => {
          renderMatch(match, frame);
          // TUNE ADVANCES HERE AND NOWHERE ELSE. `onMatch` fires on EVERY
          // frame — `session.ts` calls it with `lastMatch`, which is `null`
          // when no reference is set — so this one call covers the chromatic
          // case and the reference case both. It was briefly also called from
          // `onFrame` for the chromatic path, which gave the filter TWO steps
          // per hop whenever no reference was set: the default state, and the
          // one where the damping the interface prints would have been half
          // what it said.
          //
          // ONE PATH POSTS A FRAME TWICE, and it is not a frame: `setTolerance`
          // re-posts `onMatch` for the LAST frame so the band is re-judged at
          // once, which costs the filter one extra step per deliberate
          // tolerance change. Left as it is — a single step at a moment the
          // singer chose, against a guard that would have to carry a frame
          // identity through the shell to catch it.
          stepTuner(frame, match);
          matchListeners.forEach((listener) => { listener(match); });
        },
        onReadiness: renderReadiness,
        onClip: renderClip,
        onError: (message) => { setStatus(message, 'error'); },
      },
    });
    // The reference the shell already holds goes to the new session before its
    // first frame, so the ghost and the match are there from the first column.
    shell.session.setReference(shell.reference);
    shell.startedAtMs = performance.now();
    // The needle's filter belongs to the HOP, and the hop is the preset's:
    // 640/32000 under `live_singing` is 20 ms, 1280/32000 under
    // `sustained_pitch_lab` is 40 ms, and one alpha for both would be a
    // different time constant on each.
    shell.needleAlpha = alphaFor(preset.hopSamples / preset.sampleRateHz);
    shell.needleCents = null;
    shell.tuner = TUNER_INITIAL;
    renderChain(shell.session);
    renderClip(false);
    renderReference();
    renderReadiness(null);
    renderConstants();
    renderTelemetry();
    wireTransport(shell.session);
    setStatus(shell.session.source === 'file' ? transportSentence() : `live — ${preset.name}`, 'live');
    button.textContent = shell.source === 'file' ? 'Stop' : 'Stop capture';
    countersTimer = window.setInterval(renderTelemetry, 500);
  } catch (error) {
    // Three failures worth telling apart, because the fix differs: no API at
    // all, a rate the preset cannot accept, and a denied permission.
    if (error instanceof RateRefused) {
      setStatus(error.message, 'error');
    } else if (error instanceof DecodeRateMismatch) {
      // Reachable only if the per-rate cache and the preset disagree. Say the
      // two numbers rather than "capture failed".
      setStatus(error.message, 'error');
    } else if (error instanceof CaptureUnavailable) {
      setStatus(error.message, 'error');
    } else if (error instanceof DOMException && error.name === 'NotAllowedError') {
      setStatus('microphone permission was denied — the browser blocked the request', 'error');
    } else {
      setStatus(`capture failed: ${error instanceof Error ? error.message : String(error)}`, 'error');
    }
  } finally {
    button.disabled = false;
  }
}

async function stop(): Promise<void> {
  const session = shell.session;
  if (session === null) {
    return;
  }
  shell.session = null;
  shell.startedAtMs = null;
  shell.needleCents = null;
  shell.transportOff?.();
  shell.transportOff = null;
  if (playheadTimer !== null) {
    window.clearInterval(playheadTimer);
    playheadTimer = null;
  }
  if (countersTimer !== null) {
    window.clearInterval(countersTimer);
    countersTimer = null;
  }
  await session.stop();
  renderChain(null);
  renderTelemetry();
  renderReference();
  renderReadiness(null);
  renderMatch(matchState(null, shell.reference, activeConstants()), null);
  renderConstants();
  // Not while switching presets: the state cell is already saying which preset
  // is being switched to, and "idle — stopped" for one frame in the middle of
  // it would be a message about a state the singer never asked for.
  if (!switching) {
    setStatus('idle — stopped');
  }
  renderTransport();
  required<HTMLButtonElement>('capture-button').textContent =
    shell.source === 'file' ? 'Start' : 'Start capture';
}

/* --- boot ----------------------------------------------------------------- */

function applySecureContextVerdict(verdict: SecureContextVerdict): boolean {
  const banner = required<HTMLElement>('insecure-banner');
  const detail = required<HTMLElement>('insecure-banner-detail');
  const button = required<HTMLButtonElement>('capture-button');

  if (verdict.usable) {
    banner.hidden = true;
    button.disabled = false;
    setStatus('idle — press Start capture');
    return true;
  }
  detail.textContent = verdict.reason;
  banner.hidden = false;
  button.disabled = true;
  setStatus('capture unavailable — insecure origin', 'error');
  return false;
}

/**
 * Light/dark, and the repaint a canvas needs that the DOM does not.
 *
 * A CSS custom property change restyles every DOM node for free; a canvas holds
 * pixels that were painted with the OLD values and will keep them until
 * something draws again. So the controller's subscription re-reads the palette
 * and forces a repaint — which is also why `refreshPalette` calls `resize()`
 * rather than waiting for the next frame: when capture is stopped there is no
 * next frame, and the axes would stay the previous theme's colour indefinitely.
 */
function wireTheme(): ThemeController {
  const controller = createThemeController();
  const toggle = required<HTMLButtonElement>('theme-toggle');
  const label = required<HTMLElement>('theme-toggle-label');

  if (controller.embedded) {
    // The surrounding page owns the setting; the control would be a lie.
    toggle.hidden = true;
  } else {
    toggle.hidden = false;
    toggle.addEventListener('click', () => { controller.cycle(); });
  }

  controller.subscribe((theme) => {
    label.textContent = `theme: ${controller.choice()}`;
    toggle.setAttribute('aria-label', `Theme: ${controller.choice()} (showing ${theme}). Click to change.`);
    shell.session?.refreshPalette();
  });
  return controller;
}

function main(): void {
  wireTheme();
  // The mode first: it decides which panes exist before anything measures one.
  wireMode();
  // THEN the URL's override, and the order is load-bearing: `wireMode`
  // subscribes to the stored preference and the subscription fires at once
  // with the stored value, so an override applied before it would be written
  // straight back over. Measured 2026-08-23 — `?mode=tune` painted Tune and
  // then reverted to the stored mode as the module loaded.
  //
  // `shell.mode` directly rather than `modePref.set`, because this is a PAGE
  // VIEW and not a preference: the al-folio page embeds this file twice, and
  // the short tuner card must not change what the analyzer opens in next time.
  const asked = modeFromSearch(window.location.search);
  if (asked !== null && asked !== shell.mode) {
    shell.mode = asked;
    renderMode();
    // `shell.mode` and `modePref` are deliberately out of step from here on;
    // `applyMode` is what makes every segment keep working anyway.
  }
  // Then the rail, which decides how wide the canvas column is.
  wireRail();
  shieldUnderOverlays();
  wireTuner();
  const usable = applySecureContextVerdict(inspectSecureContext());
  renderChain(null);
  renderTelemetry();

  const button = required<HTMLButtonElement>('capture-button');
  button.addEventListener('click', () => {
    void (shell.session === null ? start() : stop());
  });

  // The reference: load it, draw the bar's geometry, render the cells, and
  // wire the two buttons — all before any session, so a reload shows the note
  // that was captured yesterday and not an empty cell until capture starts.
  shell.reference = store.load();
  // `wireTolerance`'s first subscription call lays the bar out and renders the
  // match from the reference just loaded, so it comes after the load and before
  // the cells below.
  wireTolerance();
  presetSelect().addEventListener('change', (event) => {
    void selectPreset((event.target as HTMLSelectElement).value);
  });
  renderReference();
  renderReadiness(null);
  renderConstants();
  required<HTMLButtonElement>('capture-reference').addEventListener('click', () => {
    captureReference();
  });
  required<HTMLButtonElement>('clear-reference').addEventListener('click', () => {
    installReference(null);
  });

  // Enter in the field submits, because the field is in a <form> and Set is
  // its submit button — native behaviour, no key handling of our own. Typing
  // again clears the pinned refusal: the singer is answering it.
  const noteInput = required<HTMLInputElement>('note-input');
  required<HTMLFormElement>('note-form').addEventListener('submit', (event) => {
    event.preventDefault();
    setTypedReference(noteInput.value);
  });
  noteInput.addEventListener('input', () => {
    if (shell.typedRefusal !== null) {
      clearTypedRefusal();
      renderReadiness(null);
    }
  });
  required<HTMLButtonElement>('note-down').addEventListener('click', () => { stepReference(-1); });
  required<HTMLButtonElement>('note-up').addEventListener('click', () => { stepReference(1); });

  // The source. The radiogroup only SWITCHES; the picker is its own button,
  // because selection follows focus here and a radio that opened a file dialog
  // would open it on an arrow key.
  wireRadiogroup(required<HTMLElement>('source-control'), (value) => {
    void selectSource(value === 'file' ? 'file' : 'microphone');
  });
  const fileInput = required<HTMLInputElement>('file-input');
  required<HTMLButtonElement>('file-choose').addEventListener('click', () => { fileInput.click(); });
  fileInput.addEventListener('change', () => {
    const chosen = fileInput.files?.[0];
    if (chosen === undefined) {
      return;
    }
    // Held so the harness can await a `setInputFiles`, and so a second pick
    // while the first is decoding cannot interleave.
    shell.decoding = loadFile(chosen).then(() => undefined);
    void shell.decoding.finally(() => {
      // The same file picked twice must fire `change` again.
      fileInput.value = '';
    });
  });

  required<HTMLButtonElement>('transport-play').addEventListener('click', () => {
    const transport = shell.session?.transport;
    if (transport === undefined || transport === null) {
      return;
    }
    if (transport.state().phase === 'playing') {
      transport.pause();
    } else {
      transport.play();
    }
  });
  required<HTMLButtonElement>('transport-loop').addEventListener('click', () => {
    const transport = shell.session?.transport ?? null;
    if (transport === null) {
      shell.fileLoop = !shell.fileLoop;
      renderTransport();
      return;
    }
    transport.setLoop(!transport.state().loop);
  });
  // ⏮ and the two skips. `seek` clamps into the loop region while one is
  // looping (`transport.ts`'s `intoRegion`), which is what a skip inside a
  // loop should do: the region IS the phrase being worked on.
  required<HTMLButtonElement>('transport-home').addEventListener('click', () => {
    const transport = shell.session?.transport;
    transport?.seek(transport.state().region.startS);
  });
  const skipBy = (seconds: number): void => {
    const transport = shell.session?.transport;
    if (transport === undefined || transport === null) {
      return;
    }
    transport.seek(transport.positionS() + seconds);
  };
  required<HTMLButtonElement>('transport-back').addEventListener('click', () => { skipBy(-SKIP_SECONDS); });
  required<HTMLButtonElement>('transport-fwd').addEventListener('click', () => { skipBy(SKIP_SECONDS); });

  // A and B stamp the playhead into the region's ends; reset A and reset B
  // stamp the file's own edges. All four go through one path — the accessible
  // shape, because two stacked ranges fight for the pointer and put the focus
  // order at odds with the visual one.
  //
  // `said` is what the live region gets. A stamp is visible in the hatched
  // band; a RESET can look like nothing happened, which is exactly the case
  // `#player-announce` exists for. It cannot go in the state cell: the
  // `set-region` event this function produces makes `wireTransport` rewrite
  // that cell with `transportSentence()` before anyone could read it.
  const applyRegion = (build: (region: Region, durationS: number) => Region, said: (region: Region) => string): void => {
    const transport = shell.session?.transport ?? null;
    // BEFORE PLAY THERE IS NO TRANSPORT, and the marks still have to work. The
    // two number fields used to be the only control that did anything in this
    // state — they wrote `shell.fileRegion` against the decoded duration — and
    // removing them (W8) would otherwise have removed the capability with
    // them. The shell's region is what a new session is built with, so a mark
    // set here is in force the moment Play is pressed.
    if (transport === null) {
      const durationS = shell.file?.buffer.duration ?? 0;
      if (durationS <= 0) {
        return;
      }
      const current = shell.fileRegion ?? { startS: 0, endS: durationS };
      const wanted = build(current, durationS);
      const result = validateRegionForShell(wanted.startS, wanted.endS, durationS);
      if (isRegionRefusal(result)) {
        setStatus(result.message, 'error');
        renderTransport();
        return;
      }
      shell.fileRegion = result;
      required<HTMLElement>('player-announce').textContent = said(result);
      renderTransport();
      renderStretchControl();
      return;
    }
    const state = transport.state();
    const wanted = build(state.region, state.durationS);
    const result = transport.setRegion(wanted.startS, wanted.endS);
    if (isRegionRefusal(result)) {
      // Unreachable: every builder below is a stamp, and a stamp moves the
      // other end rather than leaving a region `validateRegion` would refuse
      // (`transport.ts`). Kept because `setRegion` is also the debug hook's
      // path and a refusal must never be swallowed.
      setStatus(result.message, 'error');
      renderTransport();
      return;
    }
    shell.fileRegion = result;
    required<HTMLElement>('player-announce').textContent = said(result);
  };
  const loopSaid = (what: string) => (region: Region): string =>
    `${what} — loop ${formatSeconds(region.startS)} to ${formatSeconds(region.endS)}`;
  // The playhead is rounded to the seek's own 0.1 s step, so what A stamps is
  // what the clock beside it reads.
  const playhead = (): number => Math.round((shell.session?.transport?.positionS() ?? 0) * 10) / 10;
  required<HTMLButtonElement>('region-set-a').addEventListener('click', () => {
    applyRegion((region, durationS) => stampRegionStart(playhead(), region, durationS), loopSaid('loop start set'));
  });
  required<HTMLButtonElement>('region-set-b').addEventListener('click', () => {
    applyRegion((region, durationS) => stampRegionEnd(playhead(), region, durationS), loopSaid('loop end set'));
  });
  required<HTMLButtonElement>('region-reset-a').addEventListener('click', () => {
    applyRegion(resetRegionStart, loopSaid('loop start reset'));
  });
  required<HTMLButtonElement>('region-reset-b').addEventListener('click', () => {
    applyRegion(resetRegionEnd, loopSaid('loop end reset'));
  });

  // THE SCRUB COMMITS ONCE. `input` fires per pixel of drag and per arrow key,
  // and every one of those would rebuild the source node and reset both rings
  // — the 128 ms hole, tens of times a second. So `input` moves the clock
  // beside the thumb and nothing else; `change` is the single seek.
  const seek = seekInput();
  const holdSeek = (): void => { seekHeld = true; };
  const releaseSeek = (): void => {
    seekHeld = false;
    renderPlayhead();
  };
  seek.addEventListener('pointerdown', holdSeek);
  seek.addEventListener('focus', holdSeek);
  seek.addEventListener('blur', releaseSeek);
  seek.addEventListener('input', () => {
    seekHeld = true;
    const at = Number(seek.value);
    const durationS = shell.session?.transport?.state().durationS ?? shell.file?.buffer.duration ?? 0;
    required<HTMLElement>('transport-time').textContent = `${formatSeconds(at)} / ${formatSeconds(durationS)}`;
    seek.setAttribute('aria-valuetext', formatSeconds(at));
  });
  seek.addEventListener('change', () => {
    shell.session?.transport?.seek(Number(seek.value));
    // A click on the track fires `change` with the pointer still down; the
    // pointer and focus events below are what actually release the hold.
    if (document.activeElement !== seek) {
      releaseSeek();
    }
  });
  seek.addEventListener('pointerup', releaseSeek);
  seek.addEventListener('pointercancel', releaseSeek);

  // THE STRETCH SLIDER COMMITS ONCE, for the same reason the seek does: every
  // move would otherwise start a render and a restart. `input` names the
  // factor the thumb is over; `change` renders it.
  const stretchSlider = required<HTMLInputElement>('stretch-slider');
  stretchSlider.addEventListener('input', () => {
    const factor = factorForSliderValue(Number(stretchSlider.value));
    const text = describeFactor(factor);
    required<HTMLElement>('stretch-value').textContent = text;
    stretchSlider.setAttribute('aria-valuetext', text);
  });
  stretchSlider.addEventListener('change', () => {
    shell.rendering = applyStretch(factorForSliderValue(Number(stretchSlider.value)));
  });

  // Smear commits on `change` like everything else that costs a render. A
  // change at 1× costs nothing and is remembered for the next stretch.
  const smearSlider = required<HTMLInputElement>('smear-slider');
  smearSlider.addEventListener('input', () => {
    const chosen = STRETCH_SMEAR_CHOICES[Number(smearSlider.value)] ?? STRETCH_SMEAR_DEFAULT_S;
    required<HTMLElement>('smear-value').textContent = `${chosen.toFixed(2)} s`;
    smearSlider.setAttribute('aria-valuetext', describeSmear(chosen));
  });
  smearSlider.addEventListener('change', () => {
    const chosen = STRETCH_SMEAR_CHOICES[Number(smearSlider.value)] ?? STRETCH_SMEAR_DEFAULT_S;
    shell.smearS = chosen;
    renderStretchControl();
    if (shell.stretch > 1.001) {
      // A different window is a different sound: re-render what is playing.
      shell.rendering = applyStretch(shell.stretch);
    }
  });
  renderSource();
  renderTransport();

  // Deliberately not awaited together with a failure that aborts the other:
  // a dead /api/version must not blank the preset list, and vice versa.
  void renderVersion();
  const ready = loadPresets().then(() => {
    if (usable) {
      required<HTMLElement>('capture-hint').textContent =
        'Your browser will ask for microphone permission. Nothing is uploaded.';
    }
    // The typed controls wait for the preset list for the same reason the
    // capture button waits for the microphone: a reference records the preset
    // it was set under (`setReferenceF0` throws without one), and a field that
    // threw on Enter would be a control that looks ready and is not.
    required<HTMLInputElement>('note-input').disabled = false;
    required<HTMLButtonElement>('note-set').disabled = false;
    renderReference();
    // Now that a preset is selected, the hold can be quoted in seconds too.
    renderConstants();
  });

  const host: DebugHost = {
    ready,
    current: () => shell.session,
    startedAtMs: () => shell.startedAtMs,
    presetIds: () => shell.summaries.map((p) => p.id),
    start,
    stop,
    onFrame: (listener) => {
      frameListeners.add(listener);
      return () => frameListeners.delete(listener);
    },
    reference: () => shell.reference,
    capture: captureReference,
    clearReference: () => { installReference(null); },
    setReferenceF0,
    setReferenceText: setTypedReference,
    stepReference,
    source: () => ({
      kind: shell.source,
      name: shell.file?.name ?? null,
      bytes: shell.file?.bytes ?? null,
      container: shell.file?.probe.container ?? null,
      nativeSampleRateHz: shell.file?.probe.sampleRateHz ?? null,
      nativeChannels: shell.file?.probe.channels ?? null,
      decodedSampleRateHz: shell.file?.buffer.sampleRate ?? null,
      decodedChannels: shell.file?.buffer.numberOfChannels ?? null,
      durationS: shell.file?.buffer.duration ?? null,
      decodeCount: shell.decodeCount,
    }),
    selectSource: (kind) => selectSource(kind),
    stretch: () => ({
      factor: shell.stretch,
      smearS: shell.smearS,
      maxFactor: maxFactorForRegion(),
      regionS: stretchRegionS(),
      derived: shell.stretched?.derived ?? null,
      outputSamples: shell.stretched?.buffer.length ?? null,
      durationS: shell.stretched?.buffer.duration ?? null,
    }),
    setStretch: async (factor: number) => { await applyStretch(factor); },
    setSmear: async (smearS: number) => {
      shell.smearS = (STRETCH_SMEAR_CHOICES.find((choice) => choice === smearS) ?? STRETCH_SMEAR_DEFAULT_S);
      renderStretchControl();
      if (shell.stretch > 1.001) {
        await applyStretch(shell.stretch);
      }
    },
    // Resolves after the decode a `setInputFiles` started, so a harness never
    // reads the source between the change event and the buffer.
    fileReady: () => shell.decoding ?? Promise.resolve(),
    transport: () => shell.session?.transport ?? null,
    setRegion: (startS, endS) => {
      const transport = shell.session?.transport ?? null;
      if (transport === null) {
        return validateRegionForShell(startS, endS, shell.file?.buffer.duration ?? 0);
      }
      const result = transport.setRegion(startS, endS);
      if (!isRegionRefusal(result)) {
        shell.fileRegion = result;
      }
      return result;
    },
    match: () => shell.session?.lastMatch() ?? null,
    onMatch: (listener) => {
      matchListeners.add(listener);
      return () => matchListeners.delete(listener);
    },
    // The ACTIVE constants, so a harness reads the band the page is judging by
    // rather than the frozen defaults it started from.
    constants: (): DebugConstants => ({
      ...activeConstants(),
      a4Hz: A4_HZ,
      maxPeaks: DEFAULT_PEAK_PICKER.maxPeaks,
    }),
    tolerance: () => shell.tolerance,
    setTolerance: (tolerance) => { tolerancePref.set(tolerance); },
    tuner: () => ({
      drawn: shell.tuner.drawn,
      measured: shell.tuner.measured,
      dampingMs: shell.dampingMs,
      held: shell.tunerHeld,
    }),
    setMode: (mode) => { modePref.set(mode); },
  };
  installDebugSurface(host);
}

main();
