//
// The reference lane and the f0 trace, drawn OVER the spectrogram.
//
// WHY A SECOND CANVAS AND NOT THE SHADER. Everything this file draws is one
// line of Canvas2D and would be a program of its own in GL: a 45° hatch, a
// cased stroke, a text chip, and a `state()` a test can read without a pixel
// readback. The cost is one transparent canvas composited per animation frame
// (≤ 1 ms measured on this machine at 1280 × 800, 2026-08-22) against a
// second shader pass, a second set of uniforms and a second place for the
// axis to be computed. The spectrogram keeps the GPU; the marks that mean
// something to a singer keep the API that can draw them.
//
// WHY THE LANE IS A THIN VERTICAL BAND HERE AND A TALL HORIZONTAL ONE ON THE
// PITCH STRIP. On `live_singing`'s 60–8000 Hz log axis a ±10-cent lane around
// A3 is 2.8 px wide. That is the geometry, not a drawing choice: the pane is a
// frequency axis four octaves wide and ten cents is a hundredth of a semitone.
// So this pane draws the lane EXACTLY — the edges are `laneHz`'s frequencies
// mapped through the shared axis, never widened to a legible minimum, because a
// widened lane would say a singer was in tune when they were not — and the
// DECORATION degrades instead: the hatch is dropped below 8 px, the casing
// below 4 px, and what remains is a hairline in the right place. The pane a
// singer performs against is `pitch-strip.ts`, where cents are the y axis and
// the same lane is tens of pixels tall.
//
// NO SMOOTHING ON THE TRACE, and `moveTo` at every unvoiced row. A smoothed
// pitch trace is a lie about vibrato — the wiggle IS the measurement — and a
// trace drawn straight through an unvoiced gap invents a glide the singer never
// sang. `trace-ring.ts` keeps unvoiced as NaN precisely so that the gap cannot
// be read as a frequency.
//
// THE ROW COMES FROM THE SPECTROGRAM. `push(row, f0)` is handed the row
// `waterfall-view.push()` just wrote, so the trace and the harmonics under it
// are the same moment in time even when a frame is dropped. This file has no
// counter of its own.
// ---------------------------------------------------------------------------

import type { Lane } from '../app/reference';
import { PLOT_GUTTER, axisMapper, plotWidthFor, type FrequencyAxis } from './axis';
import { readSpectrumPalette, type CanvasPalette } from './palette';
import { browserRafHost, createFrameScheduler, type FrameScheduler, type RafHost } from './scheduler';
import { createTraceRing } from './trace-ring';
import { HISTORY_ROWS } from './waterfall-view';

/**
 * What the overlay is drawing. Every number is a pixel or a frequency it was
 * GIVEN — the pane reports its geometry, it does not measure anything.
 *
 * Named for the pane rather than for the role, to match `PitchStripState`: two
 * panes now publish a `state()` and a bare `OverlayState` would not say which.
 */
export interface WaterfallOverlayState {
  readonly laneHz: number | null;
  readonly laneInTuneHz: readonly [number, number] | null;
  readonly laneNearHz: readonly [number, number] | null;
  /** The in-tune edges in CSS x, `[left, right]`. `null` with no lane. */
  readonly laneInTunePx: readonly [number, number] | null;
  /** Voiced rows in the ring that fall inside the axis span — the points the polyline is made of. */
  readonly tracePoints: number;
  readonly rowsHeld: number;
  readonly newestRow: number | null;
  /** The newest voiced frequency, and its x. `null` when nothing voiced is held. */
  readonly lastTraceHz: number | null;
  readonly lastTraceX: number | null;
  readonly cssWidth: number;
  readonly cssHeight: number;
  readonly dpr: number;
}

export interface WaterfallOverlay {
  /** Record the f0 of the spectrogram row `row`, and request a repaint. */
  push(row: number, f0Hz: number | null): void;
  setLane(lane: Lane | null): void;
  setOptions(axis: FrequencyAxis): void;
  setPalette(palette: CanvasPalette): void;
  /** Rows per second, for the time ticks. GIVEN, never derived here (ADR 0021 decision 3). */
  setRowsPerSecond(rows: number): void;
  resize(): void;
  state(): WaterfallOverlayState;
  destroy(): void;
}

/**
 * Where the decoration gives up, in CSS pixels of band width.
 *
 * Below `hatchMinPx` a 45° hatch at this spacing puts fewer than two lines in
 * the band and reads as noise; below `casingMinPx` the casing (1.5 px on each
 * side of each edge) would meet in the middle and paint the band the casing's
 * colour, i.e. hide the very thing it exists to make legible. `(prov.)` —
 * chosen from the geometry, not measured against readers.
 */
export const LANE_DECORATION = Object.freeze({
  hatchMinPx: 8,
  casingMinPx: 4,
  hatchSpacingPx: 6,
});

/** The two washes. Opaque tokens, transparency applied here — see `palette.ts` on why tokens stay opaque. */
const WASH = { inTune: 0.16, near: 0.1 } as const;

/** Casing and core widths, CSS pixels. */
const STROKE = { casing: 3.5, trace: 1.75, edge: 1 } as const;

const LABEL_FONT = '11px ui-monospace, "DejaVu Sans Mono", monospace';

/**
 * The y of the spectrogram row `age` rows behind the newest, in CSS pixels.
 *
 * `(age + 0.5)` because the shader samples texel CENTRES: the newest row's
 * centre sits half a display row below the top edge, and a trace drawn at
 * `age · h/rows` would ride half a row above the harmonics it belongs to. The
 * `+ 0.5` here and the absent one in the fragment shader are the same
 * convention seen from the two ends.
 */
export function rowYOf(age: number, cssHeight: number, rows: number = HISTORY_ROWS): number {
  return ((age + 0.5) * cssHeight) / rows;
}

/**
 * The time-tick interval in seconds, or `null` when there is nothing to tick.
 *
 * Picks the smallest interval from a fixed ladder whose spacing on this pane
 * clears `minGapPx`, so the gutter never carries labels closer together than
 * they can be read. Pure pixel arithmetic on a rate the session MEASURED and
 * passed in; nothing here computes a rate.
 */
export function timeTickStepS(
  rowsPerSecond: number,
  cssHeight: number,
  rows: number = HISTORY_ROWS,
  minGapPx: number = 28,
): number | null {
  if (!(rowsPerSecond > 0) || !Number.isFinite(rowsPerSecond) || !(cssHeight > 0)) {
    return null;
  }
  for (const step of [0.25, 0.5, 1, 2, 5, 10]) {
    if ((step * rowsPerSecond * cssHeight) / rows >= minGapPx) {
      return step;
    }
  }
  return null;
}

/**
 * 45° hatch over a rectangle, clipped to it.
 *
 * One angle, one spacing, used by both lanes — the spectrogram's vertical band
 * and the pitch strip's horizontal one. Two different hatches would read as two
 * different states rather than as the same lane seen on two axes.
 */
export function hatchRect(
  context: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  spacing: number = LANE_DECORATION.hatchSpacingPx,
): void {
  context.save();
  context.beginPath();
  context.rect(x, y, w, h);
  context.clip();
  context.beginPath();
  for (let k = -h; k <= w + h; k += spacing) {
    context.moveTo(x + k, y + h);
    context.lineTo(x + k + h, y);
  }
  context.stroke();
  context.restore();
}

export function createWaterfallOverlay(
  canvas: HTMLCanvasElement,
  axis: FrequencyAxis,
  palette: CanvasPalette = readSpectrumPalette(canvas),
  host: RafHost = browserRafHost(canvas.ownerDocument.defaultView ?? window),
): WaterfallOverlay {
  const context = ((): CanvasRenderingContext2D => {
    const found = canvas.getContext('2d');
    if (found === null) {
      throw new Error('this browser did not give a 2d context for the waterfall overlay');
    }
    return found;
  })();

  let currentAxis = axis;
  let currentPalette = palette;
  let currentLane: Lane | null = null;
  let rowsPerSecond = 0;
  let cssWidth = canvas.clientWidth > 0 ? canvas.clientWidth : canvas.width;
  let cssHeight = canvas.clientHeight > 0 ? canvas.clientHeight : canvas.height;
  let backingDpr = 1;
  /** One head, and it is the spectrogram's — see the header and `trace-ring.ts`. */
  const ring = createTraceRing(HISTORY_ROWS);
  /** Incremented per repaint request; the scheduler's payload, so the newest request wins. */
  let paintSeq = 0;

  function mapper(): ReturnType<typeof axisMapper> {
    return axisMapper(currentAxis, PLOT_GUTTER.left, plotWidthFor(cssWidth));
  }

  function inSpan(hz: number): boolean {
    return hz >= currentAxis.freqMinHz && hz <= currentAxis.freqMaxHz;
  }

  /**
   * A vertical line the full height of the pane, cased or bare.
   *
   * NOT snapped to the half-pixel grid the way the grid lines are. This edge is
   * a FREQUENCY; snapping it would move it by up to half a pixel, and on a lane
   * 2.8 px wide half a pixel is a fifth of the tolerance. An anti-aliased line
   * in the right place beats a crisp one in the wrong one.
   */
  function edge(x: number, cased: boolean): void {
    const draw = (): void => {
      context.beginPath();
      context.moveTo(x, 0);
      context.lineTo(x, cssHeight);
      context.stroke();
    };
    if (cased) {
      context.strokeStyle = currentPalette.overlayCasing;
      context.lineWidth = STROKE.edge + 2;
      draw();
    }
    context.strokeStyle = currentPalette.lane;
    context.lineWidth = STROKE.edge;
    draw();
  }

  function drawLane(lane: Lane): void {
    const m = mapper();
    const nearLeft = m.xOf(lane.nearHz[0]);
    const nearRight = m.xOf(lane.nearHz[1]);
    const inLeft = m.xOf(lane.inTuneHz[0]);
    const inRight = m.xOf(lane.inTuneHz[1]);
    const inWidth = inRight - inLeft;
    const nearWidth = nearRight - nearLeft;

    context.save();

    // --- the near band: a wash and two dotted edges -------------------------
    context.globalAlpha = WASH.near;
    context.fillStyle = currentPalette.laneNear;
    context.fillRect(nearLeft, 0, nearWidth, cssHeight);
    context.globalAlpha = 1;
    context.setLineDash([2, 3]);
    context.strokeStyle = currentPalette.laneNear;
    context.lineWidth = STROKE.edge;
    for (const x of [nearLeft, nearRight]) {
      context.beginPath();
      context.moveTo(x, 0);
      context.lineTo(x, cssHeight);
      context.stroke();
    }
    context.setLineDash([]);

    // --- the in-tune band: a wash, a hatch, and two cased edges -------------
    context.globalAlpha = WASH.inTune;
    context.fillStyle = currentPalette.lane;
    context.fillRect(inLeft, 0, inWidth, cssHeight);
    context.globalAlpha = 1;
    if (inWidth >= LANE_DECORATION.hatchMinPx) {
      context.save();
      context.globalAlpha = 0.5;
      context.strokeStyle = currentPalette.lane;
      context.lineWidth = 1;
      hatchRect(context, inLeft, 0, inWidth, cssHeight);
      context.restore();
    }
    const cased = inWidth >= LANE_DECORATION.casingMinPx;
    edge(inLeft, cased);
    edge(inRight, cased);

    context.restore();
  }

  /**
   * The lane's name, in WORDS — SC 1.4.1: a band that differed only by hue
   * would be unreadable to a singer who cannot tell this blue from the ramp
   * under it.
   *
   * Drawn AFTER the trace, unlike everything else about the lane. The chip sits
   * at the top of the pane, which is where the newest rows are, so the trace
   * crosses it exactly when the singer is at the lane's frequency — the moment
   * the label matters most. Its casing is what makes that legal: the same
   * exception `spectrum-view.ts` documents for the reference's markers, for the
   * same reason (a symbol nobody can see is not one).
   */
  function drawLaneChip(lane: Lane): void {
    const m = mapper();
    const inLeft = m.xOf(lane.inTuneHz[0]);
    const inRight = m.xOf(lane.inTuneHz[1]);
    context.save();
    context.font = LABEL_FONT;
    context.textBaseline = 'top';
    const flip = inRight + 6 + context.measureText(lane.label).width > PLOT_GUTTER.left + plotWidthFor(cssWidth);
    context.textAlign = flip ? 'right' : 'left';
    const anchor = flip ? inLeft - 6 : inRight + 6;
    context.lineJoin = 'round';
    context.lineWidth = STROKE.casing;
    context.strokeStyle = currentPalette.overlayCasing;
    context.strokeText(lane.label, anchor, 4);
    context.fillStyle = currentPalette.lane;
    context.fillText(lane.label, anchor, 4);
    context.restore();
  }

  /** The polyline, newest at the top, broken at every unvoiced or off-axis row. */
  function tracePath(m: ReturnType<typeof axisMapper>): void {
    const held = ring.held;
    context.beginPath();
    let open = false;
    for (let age = 0; age < held; age += 1) {
      const hz = ring.at(age);
      if (hz === null || !inSpan(hz)) {
        // A gap, and it stays a gap: `moveTo` on the next point rather than a
        // line across it.
        open = false;
        continue;
      }
      const x = m.xOf(hz);
      const y = rowYOf(age, cssHeight);
      if (open) {
        context.lineTo(x, y);
      } else {
        context.moveTo(x, y);
        open = true;
      }
    }
  }

  /** Seconds, down the left gutter, from the rate the session measured. */
  function drawTimeTicks(): void {
    const step = timeTickStepS(rowsPerSecond, cssHeight);
    if (step === null) {
      return;
    }
    context.save();
    context.font = LABEL_FONT;
    context.textAlign = 'right';
    context.textBaseline = 'middle';
    context.strokeStyle = currentPalette.grid;
    context.fillStyle = currentPalette.axisText;
    context.lineWidth = 1;
    for (let t = step; ; t += step) {
      const y = rowYOf(t * rowsPerSecond, cssHeight);
      if (y > cssHeight) {
        break;
      }
      const yy = Math.round(y) + 0.5;
      context.beginPath();
      context.moveTo(PLOT_GUTTER.left - 5, yy);
      context.lineTo(PLOT_GUTTER.left, yy);
      context.stroke();
      context.fillText(`${t % 1 === 0 ? String(t) : t.toFixed(2)} s`, PLOT_GUTTER.left - 7, yy);
    }
    context.restore();
  }

  function paint(): void {
    // TRANSPARENT, not filled: the spectrogram is underneath and this pane is
    // the only one in the column that must not paint a background.
    context.save();
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.clearRect(0, 0, canvas.width, canvas.height);
    context.scale(backingDpr, backingDpr);

    // The ticks live in the GUTTER, so they are drawn before the clip.
    drawTimeTicks();

    // Everything else is clipped to the plot rectangle: a reference within half
    // a semitone of the axis edge has a near band that reaches past it, and a
    // wash spilling over the time labels would read as a second pane.
    const m = mapper();
    context.save();
    context.beginPath();
    context.rect(PLOT_GUTTER.left, 0, plotWidthFor(cssWidth), cssHeight);
    context.clip();

    if (currentLane !== null) {
      drawLane(currentLane);
    }

    // The trace last: what the singer is doing now is never under the target.
    context.lineJoin = 'round';
    context.lineCap = 'round';
    tracePath(m);
    context.strokeStyle = currentPalette.overlayCasing;
    context.lineWidth = STROKE.casing;
    context.stroke();
    context.strokeStyle = currentPalette.f0Trace;
    context.lineWidth = STROKE.trace;
    context.stroke();

    if (currentLane !== null) {
      drawLaneChip(currentLane);
    }

    context.restore();
    context.restore();
  }

  const scheduler: FrameScheduler<number> = createFrameScheduler<number>(() => {
    paint();
  }, host);

  function request(): void {
    paintSeq += 1;
    scheduler.submit(paintSeq);
  }

  function resize(): void {
    const view = canvas.ownerDocument.defaultView;
    const dpr = view?.devicePixelRatio ?? 1;
    backingDpr = dpr;
    const measuredWidth = canvas.clientWidth;
    const measuredHeight = canvas.clientHeight;
    cssWidth = measuredWidth > 0 ? measuredWidth : cssWidth;
    cssHeight = measuredHeight > 0 ? measuredHeight : cssHeight;
    const backingWidth = Math.max(1, Math.round(cssWidth * dpr));
    const backingHeight = Math.max(1, Math.round(cssHeight * dpr));
    if (canvas.width !== backingWidth || canvas.height !== backingHeight) {
      canvas.width = backingWidth;
      canvas.height = backingHeight;
    }
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.scale(dpr, dpr);
    paint();
  }

  resize();

  return {
    push: (row, f0Hz) => {
      // Recorded per hop — every row is a moment in time — and painted per
      // animation callback. The waterfall's own rule, for the same reason.
      ring.push(row, f0Hz);
      request();
    },
    setLane: (lane) => {
      currentLane = lane;
      request();
    },
    setOptions: (next) => {
      currentAxis = next;
      request();
    },
    setPalette: (next) => {
      currentPalette = next;
      request();
    },
    setRowsPerSecond: (rows) => {
      rowsPerSecond = rows;
      request();
    },
    resize,
    state: (): WaterfallOverlayState => {
      // Read from the RING, not from the last paint: paints coalesce to the
      // display rate, and a harness that asserted on the last painted frame
      // would be asserting on the browser's scheduling.
      const m = mapper();
      let points = 0;
      let lastHz: number | null = null;
      for (let age = 0; age < ring.held; age += 1) {
        const hz = ring.at(age);
        if (hz === null || !inSpan(hz)) {
          continue;
        }
        points += 1;
        if (lastHz === null) {
          lastHz = hz;
        }
      }
      return {
        laneHz: currentLane === null ? null : currentLane.centreHz,
        laneInTuneHz: currentLane === null ? null : currentLane.inTuneHz,
        laneNearHz: currentLane === null ? null : currentLane.nearHz,
        laneInTunePx:
          currentLane === null
            ? null
            : [m.xOf(currentLane.inTuneHz[0]), m.xOf(currentLane.inTuneHz[1])],
        tracePoints: points,
        rowsHeld: ring.held,
        newestRow: ring.newestRow,
        lastTraceHz: lastHz,
        lastTraceX: lastHz === null ? null : m.xOf(lastHz),
        cssWidth,
        cssHeight,
        dpr: backingDpr,
      };
    },
    destroy: () => {
      scheduler.cancel();
    },
  };
}
