import { createSpectrumView, type SpectrumView } from '../render/spectrum-view';
import { createWaterfallView, type WaterfallView } from '../render/waterfall-view';
import { createAxisStrip, type AxisStrip } from '../render/axis-strip';
import { createWaterfallOverlay, type WaterfallOverlay, type WaterfallOverlayState } from '../render/waterfall-overlay';
import { createPitchStrip, type PitchStrip, type PitchStripState } from '../render/pitch-strip';
import { readSpectrumPalette, type SpectrumPalette } from '../render/palette';
