//
// The two preferences the page remembers, and the storage that may refuse.
//
// `theme.ts` established the pattern and the reason: inside a third-party
// iframe — which is exactly how this application is served from
// alexander-gomez.com — `localStorage` can THROW on read and on write, not
// return null. A preference that cannot be persisted must still apply for the
// page view, so every call is wrapped and a failure degrades to the default.
//
// Keys are namespaced `superspectral.*` because the surrounding site owns the
// bare ones on the same origin.
// ---------------------------------------------------------------------------

/**
 * Perform is the singer's screen, Study the instrument's, Tune the one thing
 * you can look at while singing.
 *
 * Tune is a MODE and not a page (ADR 0024 decision 8): same capture chain,
 * same session, same preferences, same footer, same bundle. What changes is
 * that the canvases give way to a single fused readout — "the user can only
 * look at one thing at a time … the best app will be one that finds a way to
 * show the coarse view and the fine view simultaneously in the same place"
 * ([12 R20]).
 */
export type Mode = 'perform' | 'study' | 'tune';

/** The in-tune band, in cents. The set every serious tuner offers as a level. */
export const TOLERANCES = Object.freeze([5, 10, 25] as const);
export type Tolerance = (typeof TOLERANCES)[number];

/**
 * Whether the rail's second level is showing. `null` is not a third state —
 * it is the ABSENCE of a choice, and it means "take whatever this width's
 * default is": open on a laptop, closed on a phone.
 *
 * Only an explicit choice is stored, so a singer who has never touched the
 * toggle gets the right thing on both machines rather than a laptop's habit
 * carried onto a phone. The pre-paint script in `index.html` applies the same
 * rule to the same key before the first frame; the two must agree or the sheet
 * flickers open and shut on load.
 */
export type RailState = 'open' | 'closed';

export const MODE_STORAGE_KEY = 'superspectral.mode';
export const TOLERANCE_STORAGE_KEY = 'superspectral.tolerance';
export const RAIL_STORAGE_KEY = 'superspectral.rail';
export const DAMPING_STORAGE_KEY = 'superspectral.damping-ms';

/**
 * The needle's time constant, in milliseconds, as a control rather than a
 * constant. `(prov.)` — the default is the owner's to confirm by ear (Q65).
 *
 * DEFAULTED HIGH, on the review evidence: "I would set the 'Needle Damping'
 * option to 'High' … 'Medium' or 'Off' both seem to make the needle waver
 * quite a bit" ([12 R23]), and for a VOICE more than for a horn — "not enough
 * damping results in a shaky display, due to the intrinsic shakiness of vocal
 * pitch" ([12 R20]). 150 ms raises the 100 ms that shipped as `NEEDLE_TAU_S`.
 *
 * 0 is off, and it means off: the filter passes the reading straight through.
 * The step is coarse because the difference between 150 and 155 ms is not
 * something an ear can find, and a slider with 500 stops is a slider nobody
 * can land on.
 */
export const DAMPING_MS = Object.freeze({ min: 0, max: 500, step: 25, default: 150 });

export function parseDampingMs(raw: unknown): number {
  const value = typeof raw === 'string' ? Number(raw) : raw;
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    return DAMPING_MS.default;
  }
  // Onto the grid, then into the range: a stored value from a future build
  // with a finer step still lands somewhere this build's slider can show.
  const snapped = Math.round(value / DAMPING_MS.step) * DAMPING_MS.step;
  return Math.min(DAMPING_MS.max, Math.max(DAMPING_MS.min, snapped));
}

/**
 * Anything that is not `study` is `perform`.
 *
 * Perform is the default because rich feedback is not free: Wilson et al. 2008
 * (bibliography 05 #71, via 09 §A) measured a DECREASE in skilled singers'
 * pitch accuracy when the display carried more than they needed, and Sing&See
 * ships the same split as two product tiers. A corrupt key must land there too.
 */
export function parseMode(raw: unknown): Mode {
  return raw === 'study' || raw === 'tune' ? raw : 'perform';
}

/**
 * A mode asked for by the URL — `?mode=tune` — for the page view only.
 *
 * It is deliberately NOT persisted. The al-folio page embeds this application
 * twice: the full analyzer, and a short card that is nothing but the tuner
 * (ADR 0024 decision 10). A card that wrote the stored mode would change what
 * the singer sees the next time they open the analyzer proper, from a page
 * they only scrolled past.
 */
export function modeFromSearch(search: string): Mode | null {
  const asked = new URLSearchParams(search).get('mode');
  return asked === 'perform' || asked === 'study' || asked === 'tune' ? asked : null;
}

/** Anything that is not one of the two literals is *no stored choice*. */
export function parseRail(raw: unknown): RailState | null {
  return raw === 'open' || raw === 'closed' ? raw : null;
}

export function parseTolerance(raw: unknown): Tolerance {
  const value = typeof raw === 'string' ? Number(raw) : raw;
  return (TOLERANCES as readonly number[]).includes(value as number) ? (value as Tolerance) : 10;
}

export interface StoredPreference<T> {
  get(): T;
  set(value: T): void;
  /** Called immediately with the current value, then on every change. Returns an unsubscribe. */
  subscribe(listener: (value: T) => void): () => void;
}

export function createStoredPreference<T>(
  key: string,
  parse: (raw: unknown) => T,
  view: Window = window,
): StoredPreference<T> {
  let current: T;
  try {
    current = parse(view.localStorage.getItem(key));
  } catch {
    current = parse(null);
  }
  const listeners = new Set<(value: T) => void>();

  return {
    get: () => current,
    set: (value) => {
      const parsed = parse(value);
      try {
        view.localStorage.setItem(key, String(parsed));
      } catch {
        // Applies for this page view; see the header.
      }
      if (parsed === current) {
        return;
      }
      current = parsed;
      listeners.forEach((listener) => { listener(current); });
    },
    subscribe: (listener) => {
      listeners.add(listener);
      listener(current);
      return () => listeners.delete(listener);
    },
  };
}
