//
// Cents, note names, and the one convention nobody had written down.
//
// Every cents figure in this application — the peak row's ≤ 3 cents, the f0
// row's ≤ 5, the "reached the note" band, the harmonic labels — comes through
// `cents()` below, and nowhere else. The Python side has the same single
// function (`golden_compare.pitch.cents`, `capture.peak.cents`); a second
// definition in either language is how two readouts come to disagree by a
// rounding.
//
// A4 = 440 Hz is a CONVENTION, and until this file it was an unstated one: the
// note cell said "A4" and nothing said against what. It is `(prov.)` here and
// displayed in the interface, because a choir tuned to 442 or a baroque
// ensemble at 415 is not out of tune — it is measured against a different
// reference, and the reference has to be on screen for the reading to mean
// anything.
// ---------------------------------------------------------------------------

/** Concert pitch, Hz. `(prov.)` — displayed in the interface until an ADR fixes it. */
export const A4_HZ = 440;

/** MIDI note number of A4. */
export const A4_MIDI = 69;

export const NOTE_NAMES = ['C', 'C♯', 'D', 'D♯', 'E', 'F', 'F♯', 'G', 'G♯', 'A', 'A♯', 'B'] as const;

export type NoteLetter = (typeof NOTE_NAMES)[number];

export interface NoteName {
  readonly name: NoteLetter;
  /** Scientific pitch notation: the octave number changes at C, and MIDI 60 is C4. */
  readonly octave: number;
  /** The nearest MIDI note; 69 is A4. */
  readonly midi: number;
  /** Signed deviation from that note, in (−50, 50]. Positive = sharp. */
  readonly cents: number;
}

/**
 * The interval from `refHz` up to `hz`, in cents: `1200·log2(hz/refHz)`.
 * Positive = sharp of the reference.
 *
 * Refuses non-positive or non-finite input outright. Praat writes `0` for an
 * unvoiced frame (`unvoiced_sentinel: 0` in the golden manifest), and a `0`
 * read as a frequency would come out as −∞ cents — a number that would then be
 * medianed into a residual. Failing loudly here is what golden-files.md's
 * "never read it as a frequency" means in code.
 */
export function cents(hz: number, refHz: number): number {
  if (!(hz > 0) || !(refHz > 0) || !Number.isFinite(hz) || !Number.isFinite(refHz)) {
    throw new RangeError(`cents() needs two positive finite frequencies, got ${String(hz)} and ${String(refHz)}`);
  }
  return 1200 * Math.log2(hz / refHz);
}

/** The note nearest to `hz`, or `null` for a frequency that is not one (≤ 0, NaN, ∞). */
export function noteName(hz: number, a4Hz: number = A4_HZ): NoteName | null {
  if (!(hz > 0) || !Number.isFinite(hz) || !(a4Hz > 0) || !Number.isFinite(a4Hz)) {
    return null;
  }
  const semitones = 12 * Math.log2(hz / a4Hz);
  const nearest = Math.round(semitones);
  const midi = nearest + A4_MIDI;
  // `Math.round` rounds .5 up, so a reading exactly half-way lands on the
  // upper note with −50 cents; the documented range is therefore (−50, 50].
  const deviation = (semitones - nearest) * 100;
  return {
    name: NOTE_NAMES[((midi % 12) + 12) % 12] as NoteLetter,
    octave: Math.floor(midi / 12) - 1,
    midi,
    cents: deviation,
  };
}

/**
 * The frequency of a MIDI note — `noteName`'s inverse, at the same convention.
 *
 * The axis strip needs it to place C2…C6, and the pitch strip to centre on a
 * note when no reference has been captured. Deriving it from `A4_HZ` rather
 * than from a table is what keeps a change of concert pitch honest: move A4 to
 * 442 and every tick moves with it.
 */
export function noteHz(midi: number, a4Hz: number = A4_HZ): number {
  return a4Hz * 2 ** ((midi - A4_MIDI) / 12);
}

/**
 * The MIDI notes a reference may be SET to: C0 (16.35 Hz) … C8 (4186 Hz). `(prov.)`
 *
 * A bound is needed because a typed reference has no estimator behind it to
 * refuse an absurdity: "C-1" and "50000" are both a frequency, and neither is
 * a note anyone sings. C0…C8 spans a piano plus a fourth at each end, it
 * contains every voice from a contrabass profondo to a whistle-register
 * soprano, and it is deliberately wider than the f0 estimator's own
 * 65 … 1100 Hz window (`dsp/mpm.ts`) — the reference is a TARGET, and a singer
 * may aim at a note the estimator would not track from a recording. Displayed
 * on the constants line with its tag, like every other taste number here.
 */
export const REFERENCE_MIDI_MIN = 12;
export const REFERENCE_MIDI_MAX = 108;

/**
 * `hz · 2^(semitones/12)` — the ONE transposition in this application.
 *
 * The warm-up ladder's step. It multiplies the CURRENT reference rather than
 * rounding to the next equal-tempered note, and the difference matters: a
 * reference captured 30 cents sharp of A3 steps to 30 cents sharp of A♯3,
 * which is the note the singer actually sang, moved by a semitone. Rounding
 * first would silently retune the reference to the grid on the first press of
 * ▲, and a singer stepping a ladder would find their own note replaced by ours.
 *
 * Here rather than in the shell for the reason the header gives: a
 * `2 ** (1/12)` literal anywhere else is the second definition of a semitone
 * that this file exists to prevent.
 */
export function transposeHz(hz: number, semitones: number): number {
  if (!(hz > 0) || !Number.isFinite(hz)) {
    throw new RangeError(`transposeHz() needs a positive finite frequency, got ${String(hz)}`);
  }
  if (!Number.isInteger(semitones)) {
    throw new RangeError(`transposeHz() steps whole semitones, got ${String(semitones)}`);
  }
  return hz * 2 ** (semitones / 12);
}

/** `+24¢`, `−3¢`, `0¢`. Unicode minus (U+2212), never the hyphen: it is a sign, not a dash. */
export function formatCents(value: number, digits: number = 0): string {
  if (!Number.isFinite(value)) {
    return '—';
  }
  const rounded = Number(value.toFixed(digits));
  if (rounded === 0) {
    return `${(0).toFixed(digits)}¢`;
  }
  const sign = rounded > 0 ? '+' : '−';
  return `${sign}${Math.abs(rounded).toFixed(digits)}¢`;
}

/** `A4 +24¢` / `B3 −3¢`, or `—` for no note. */
export function formatNote(note: NoteName | null): string {
  if (note === null) {
    return '—';
  }
  return `${note.name}${String(note.octave)} ${formatCents(note.cents)}`;
}
