//
// Play, pause, loop and the region — as a pure reducer, so the rules can be
// tested in node and the Web Audio file only obeys.
//
// WHY A REDUCER AND NOT FIVE METHODS ON THE NODE. An `AudioBufferSourceNode`
// is ONE-SHOT: it cannot be restarted, its `loop` flag cannot be meaningfully
// flipped after a `start(when, offset, duration)` scheduled its end, and a
// seek is a new node by definition. So every transport action is really the
// same three-part question — what is the new state, does the node have to be
// rebuilt, and at what offset — and answering it in five places is how a
// player comes to have a "pause then change the loop then play" path that
// nobody tried. Here the answer is one function with a table of cases, and
// `audio/file-source.ts` executes the commands it returns.
//
// PAUSE IS `suspend`, NOT `stop`. The commands distinguish them because the
// difference is audible in the ANALYSIS, not in the playback: suspending the
// context freezes the whole graph, so the worklet's ring keeps the samples it
// had and resuming continues the stream contiguously. Stopping the node and
// starting a new one at the same offset sounds identical and is not: the ring
// has to be reset (its contents are from before the gap) and the next full
// window is one `fftSize` away — 128 ms of no frames at `live_singing`, on
// every pause. Seek, loop and region DO rebuild, because there the stream
// genuinely changed and a stale window would be a spectrum of a signal that
// never existed.
//
// THE LOOP WRAP IS NOT AN EVENT. The browser wraps inside the node; nothing
// fires, nothing is reset, and the one window that straddles the wrap reads
// whatever those two ends make together. That is recorded in the README rather
// than suppressed: a suppression would need a reset per wrap, which would put
// a 128 ms hole in the spectrogram at the top of every loop.
//
// POSITION IS DERIVED, NEVER STORED WHILE PLAYING. `positionAt(state, now)` is
// the context clock minus the moment the node started, folded into the region
// when looping. A stored position would need a timer to update it, and a timer
// that missed a frame would report a position the audio was never at.
// ---------------------------------------------------------------------------

import type { Refusal } from './reference';

export interface Region {
  readonly startS: number;
  readonly endS: number;
}

export type RegionRefusal = Refusal<'not-a-number' | 'negative-start' | 'end-not-after-start' | 'end-past-duration'>;

export function isRegionRefusal(value: Region | RegionRefusal): value is RegionRefusal {
  return (value as RegionRefusal).refused === true;
}

/**
 * `0 ≤ start < end ≤ duration`, with `end === null` meaning "to the end".
 *
 * Refused rather than clamped, and the message carries the numbers: a region
 * silently clamped to the file's length is a loop the singer set and did not
 * get, and they would hear it before they understood it.
 */
export function validateRegion(startS: number, endS: number | null, durationS: number): Region | RegionRefusal {
  const end = endS === null ? durationS : endS;
  if (!Number.isFinite(startS) || !Number.isFinite(end)) {
    return {
      refused: true,
      reason: 'not-a-number',
      message: `a region needs two numbers, got ${String(startS)} and ${String(endS)}`,
    };
  }
  if (startS < 0) {
    return {
      refused: true,
      reason: 'negative-start',
      message: `the region starts at ${startS.toFixed(2)} s; a file starts at 0`,
    };
  }
  if (end > durationS) {
    return {
      refused: true,
      reason: 'end-past-duration',
      message: `the region ends at ${end.toFixed(2)} s and the file is ${durationS.toFixed(2)} s long`,
    };
  }
  if (!(end > startS)) {
    return {
      refused: true,
      reason: 'end-not-after-start',
      message: `the region ends at ${end.toFixed(2)} s, which is not after its start at ${startS.toFixed(2)} s`,
    };
  }
  return { startS, endS: end };
}

/**
 * The shortest region A and B may leave behind, in seconds. `(prov.)`
 *
 * Not a musical number — a floor that keeps the pair from collapsing onto one
 * point. 50 ms is long enough to be a loop anyone can hear and short enough
 * that it never gets in the way of a crop.
 */
export const MIN_REGION_S = 0.05;

/**
 * Stamp the region's START at `atS`, pushing the end out of the way.
 *
 * A AND B CANNOT PRODUCE AN INVALID REGION — that is the whole point of these
 * two functions. The owner hit `the region ends at 20.70 s, which is not after
 * its start at 20.70 s` while cropping a phrase, which is what happens when
 * both stamps land on one position (press B, then A, without moving) or when A
 * is pressed past an end left behind by an earlier crop. `validateRegion` was
 * right to refuse that region; the mistake was letting a BUTTON build it. A
 * stamp now says "this point is the start" and moves whatever else has to move
 * for that to be true, which is what the label promises and what every editor
 * with in/out points does.
 */
export function stampRegionStart(atS: number, region: Region, durationS: number): Region {
  const latest = Math.max(0, durationS - MIN_REGION_S);
  const startS = Math.min(Math.max(atS, 0), latest);
  const endS = Math.max(region.endS, Math.min(durationS, startS + MIN_REGION_S));
  return { startS, endS };
}

/** Stamp the region's END at `atS`, pulling the start back if it would collide. */
export function stampRegionEnd(atS: number, region: Region, durationS: number): Region {
  const endS = Math.min(Math.max(atS, MIN_REGION_S), durationS);
  const startS = Math.min(region.startS, Math.max(0, endS - MIN_REGION_S));
  return { startS, endS };
}

/**
 * Clear the mark: A back to the beginning of the file, B back to its end.
 *
 * A RESET IS A STAMP AT THE FILE'S EDGE, and is written as exactly that — so
 * the one property the stamps were rewritten for on 2026-08-23 (a button can
 * never build a region `validateRegion` would refuse) holds here for free
 * rather than by a second argument. `resetRegionStart` keeps whatever B is,
 * `resetRegionEnd` keeps whatever A is; each moves the other end only when the
 * `MIN_REGION_S` floor demands it, which is the same promise the labels make.
 *
 * They exist because the owner said so on 2026-08-23 — *"sometimes I fuck up
 * on that"* — and because a mark that can be set and not cleared is a trap.
 * Two buttons, one per endpoint, never one "reset the loop": a single reset
 * beside Play is the control NN/g's own review of reset buttons ([12 R16]) says
 * gets pressed by mistake, and there is nothing to undo it with.
 */
export function resetRegionStart(region: Region, durationS: number): Region {
  return stampRegionStart(0, region, durationS);
}

/** Clear B: the region runs to the end of the file, and A stays where it is. */
export function resetRegionEnd(region: Region, durationS: number): Region {
  return stampRegionEnd(durationS, region, durationS);
}

export type TransportPhase = 'stopped' | 'playing' | 'paused' | 'ended';

export interface TransportState {
  readonly phase: TransportPhase;
  readonly loop: boolean;
  readonly region: Region;
  readonly durationS: number;
  /** Where playback is, or would resume from, in seconds into the FILE. */
  readonly positionS: number;
  /** The context clock at the moment the current node started; `null` when none is running. */
  readonly startedAtS: number | null;
  /** The file offset that node started at. */
  readonly nodeOffsetS: number;
  /** True when the running node no longer matches the state (loop or region changed while paused). */
  readonly nodeStale: boolean;
}

export type TransportEvent =
  | { readonly type: 'play'; readonly nowS: number }
  | { readonly type: 'pause'; readonly nowS: number }
  | { readonly type: 'ended'; readonly nowS: number }
  | { readonly type: 'seek'; readonly toS: number; readonly nowS: number }
  | { readonly type: 'set-loop'; readonly loop: boolean; readonly nowS: number }
  | { readonly type: 'set-region'; readonly region: Region; readonly nowS: number };

export type TransportCommand =
  /** Build and start a source node. THIS IS THE STREAM CHANGE: ring and accumulators reset. */
  | { readonly type: 'start-node'; readonly offsetS: number; readonly loop: boolean; readonly region: Region }
  | { readonly type: 'stop-node' }
  | { readonly type: 'suspend' }
  | { readonly type: 'resume' };

export interface TransportStep {
  readonly state: TransportState;
  readonly commands: readonly TransportCommand[];
}

export function initialTransport(durationS: number, loop: boolean = false, region?: Region): TransportState {
  const bounded = region ?? { startS: 0, endS: durationS };
  return {
    phase: 'stopped',
    loop,
    region: bounded,
    durationS,
    positionS: bounded.startS,
    startedAtS: null,
    nodeOffsetS: bounded.startS,
    nodeStale: false,
  };
}

/**
 * Where the audio is now.
 *
 * While playing: the offset the node started at plus the elapsed context time,
 * folded into the region when looping (the browser wraps, so the position
 * does) and clamped to the region's end when not (the node stopped there and
 * `ended` has not been processed yet). Otherwise the stored position, which is
 * only written when playback is not running.
 */
export function positionAt(state: TransportState, nowS: number): number {
  if (state.phase !== 'playing' || state.startedAtS === null) {
    return state.positionS;
  }
  const elapsed = Math.max(0, nowS - state.startedAtS);
  const raw = state.nodeOffsetS + elapsed;
  if (!state.loop) {
    return Math.min(raw, state.region.endS);
  }
  const span = state.region.endS - state.region.startS;
  if (!(span > 0)) {
    return state.region.startS;
  }
  // The first pass may start mid-region; every later one starts at its top.
  const past = raw - state.region.startS;
  return state.region.startS + (past % span);
}

/**
 * Where a seek may land.
 *
 * WHILE LOOPING the region is a cage: the phrase is what is being worked on,
 * and a skip that left it would be a skip out of the exercise. WITH THE LOOP
 * OFF the region is only a pair of MARKS, and playback runs the whole file —
 * which is the fix for the first thing the owner said about this bar: "the
 * loop got the song stuck". It did, and unconditionally: A and B once set
 * confined every seek for the rest of the session, whether or not anything
 * was looping, so a song could not be scrubbed past the phrase it had been
 * marked on.
 */
function seekBound(position: number, state: TransportState): number {
  const low = state.loop ? state.region.startS : 0;
  const high = state.loop ? state.region.endS : state.durationS;
  return Math.min(Math.max(position, low), high);
}

/** Clamp into the region proper — used where the region genuinely is the subject. */
function intoRegion(position: number, region: Region): number {
  return Math.min(Math.max(position, region.startS), region.endS);
}

function playing(state: TransportState, offsetS: number, nowS: number): TransportState {
  return { ...state, phase: 'playing', positionS: offsetS, startedAtS: nowS, nodeOffsetS: offsetS, nodeStale: false };
}

/**
 * The whole rule table. Every case returns the new state and the commands the
 * Web Audio side must run, in order.
 */
export function transportReduce(state: TransportState, event: TransportEvent): TransportStep {
  switch (event.type) {
    case 'play': {
      if (state.phase === 'playing') {
        return { state, commands: [] };
      }
      if (state.phase === 'paused' && !state.nodeStale) {
        // The node is still there, mid-buffer, with the graph suspended. Resume
        // it: the worklet's ring keeps its samples and the stream is contiguous.
        return {
          state: { ...state, phase: 'playing', startedAtS: event.nowS - (state.positionS - state.nodeOffsetS) },
          commands: [{ type: 'resume' }],
        };
      }
      // From `stopped`, `ended`, or a pause whose node no longer matches the
      // loop or region the singer has since changed: a fresh node. `ended`
      // restarts at the top of the region, which is what "press Play again"
      // has to mean when the file has run out.
      const offset = state.phase === 'ended' ? (state.loop ? state.region.startS : 0) : seekBound(state.positionS, state);
      const commands: TransportCommand[] = [];
      if (state.startedAtS !== null || state.nodeStale) {
        commands.push({ type: 'stop-node' });
      }
      commands.push({ type: 'start-node', offsetS: offset, loop: state.loop, region: state.region }, { type: 'resume' });
      return { state: playing(state, offset, event.nowS), commands };
    }

    case 'pause': {
      if (state.phase !== 'playing') {
        return { state, commands: [] };
      }
      return {
        state: { ...state, phase: 'paused', positionS: positionAt(state, event.nowS) },
        commands: [{ type: 'suspend' }],
      };
    }

    case 'ended': {
      // Only a node that is actually playing can end. A node stopped by a seek
      // or a region change fires `onended` too, and processing that as "the
      // file finished" would stop a playback the singer just restarted.
      if (state.phase !== 'playing') {
        return { state, commands: [] };
      }
      return {
        state: { ...state, phase: 'ended', positionS: state.region.startS, startedAtS: null, nodeStale: false },
        commands: [],
      };
    }

    case 'seek': {
      const target = seekBound(event.toS, state);
      if (state.phase !== 'playing') {
        // Nothing is running: remember where to start. The node, if one is
        // suspended mid-buffer, no longer matches.
        return {
          state: { ...state, positionS: target, phase: state.phase === 'ended' ? 'paused' : state.phase, nodeStale: state.startedAtS !== null },
          commands: [],
        };
      }
      return {
        state: playing(state, target, event.nowS),
        commands: [
          { type: 'stop-node' },
          { type: 'start-node', offsetS: target, loop: state.loop, region: state.region },
        ],
      };
    }

    case 'set-loop': {
      if (state.loop === event.loop) {
        return { state, commands: [] };
      }
      const next = { ...state, loop: event.loop };
      if (state.phase !== 'playing') {
        // A suspended node was started with the old flag and a scheduled end;
        // neither can be changed on a one-shot, so Play will rebuild it.
        return { state: { ...next, nodeStale: state.startedAtS !== null }, commands: [] };
      }
      // Turning the loop ON somewhere outside the region has to enter it, or
      // the node would be told to loop over a span the playhead is not in.
      const now = positionAt(state, event.nowS);
      const at = event.loop ? intoRegion(now, state.region) : now;
      return {
        state: playing(next, at, event.nowS),
        commands: [
          { type: 'stop-node' },
          { type: 'start-node', offsetS: at, loop: event.loop, region: state.region },
        ],
      };
    }

    case 'set-region': {
      const next = { ...state, region: event.region };
      if (state.phase !== 'playing') {
        return {
          state: {
            ...next,
            positionS: state.loop ? intoRegion(state.positionS, event.region) : state.positionS,
            nodeStale: state.startedAtS !== null,
          },
          commands: [],
        };
      }
      if (!state.loop) {
        // Marks moved on a transport that is not looping: nothing about
        // playback changes. Stamping B while listening should not teleport the
        // singer back to A.
        return { state: { ...next, positionS: positionAt(state, event.nowS) }, commands: [] };
      }
      // A new region while LOOPING restarts at its top: the singer moved the
      // loop because they want to hear THAT phrase, and dropping them into its
      // middle because that is where the playhead happened to be is not it.
      return {
        state: playing(next, event.region.startS, event.nowS),
        commands: [
          { type: 'stop-node' },
          { type: 'start-node', offsetS: event.region.startS, loop: state.loop, region: event.region },
        ],
      };
    }
  }
}

/** `1:23.4` — the transport's own clock, for the state cell. */
export function formatSeconds(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) {
    return '—';
  }
  const minutes = Math.floor(seconds / 60);
  const rest = seconds - minutes * 60;
  return `${String(minutes)}:${rest < 10 ? '0' : ''}${rest.toFixed(1)}`;
}
