//
// THE TUNER'S DISPLAY FILTER — a pure function over the same f0 the rest of
// the page already has (ADR 0024 decisions 8 and 9).
//
// WHAT THIS IS NOT. It is not a second estimator, and nothing here changes a
// measurement. Every number the footer, the debug surface and the validation
// rows read is the raw one; what this module produces is a SMOOTHED and
// HYSTERETIC version for a human to read, kept beside the raw one in the same
// state object so the two can never be confused. `TunerState.measured` is what
// was measured; `TunerState.drawn` is what is drawn; the interface prints the
// time constant that separates them.
//
// THREE RULES, AND EACH ONE COMES FROM SOMEBODY WHO BUILT A TUNER AND WATCHED
// PEOPLE USE IT:
//
//   1. DAMPING IS A SETTING, AND IT DEFAULTS HIGH. A reviewer of Cleartune's
//      needle damping: "I would set the 'Needle Damping' option to 'High' to
//      make it easier to see your average pitch level — 'Medium' or 'Off' both
//      seem to make the needle waver quite a bit" ([12 R23]). And the reason a
//      SINGING tuner needs more of it than a guitar tuner: "not enough damping
//      results in a shaky display, due to the intrinsic shakiness of vocal
//      pitch" ([12 R20]). The same source insists the user be told the time
//      constant, which is why `describeDamping` exists and why the figure is
//      on screen rather than buried in this file.
//
//   2. THE NOTE NAME NEEDS HYSTERESIS, THE CENTS DO NOT. Half-way between two
//      notes the nearest-note calculation flips on noise, and a name that
//      alternates C♯4 / D4 is unreadable while the cents number beside it is
//      perfectly steady. So the NAME sticks until the pitch has clearly left
//      it — "a new degree is only accepted if it remains stable for a few
//      frames, and the needle follows a smoothed display value while the raw
//      measurement stays unchanged" ([12 R21]).
//
//   3. NEVER TWEEN ACROSS A NOTE BOUNDARY. When the held note changes, the
//      cents axis it is measured on changes with it, and smoothing across that
//      discontinuity draws a needle sweeping through positions the voice was
//      never at: "too much tweening can result in the presentation of
//      completely false information" ([12 R20]). The smoother is reset on
//      every note change and on every return from silence — the same rule
//      `dampCents` already applies to the glance bar's needle, which this
//      module reuses rather than reimplements.
//
// HOLD is the fourth thing, and it is the whole always-visible control surface
// of the best-known free singing monitor ([12 R25]). It freezes `drawn` and
// leaves `measured` running, so the footer keeps telling the truth while the
// big number stops moving.
// ---------------------------------------------------------------------------

import { A4_HZ, cents, noteHz, noteName } from '../dsp/cents';
import {
  REFERENCE_CONSTANTS,
  dampCents,
  matchBand,
  type MatchBand,
  type MatchState,
  type Reference,
  type ReferenceConstants,
} from './reference';

/**
 * How far past the half-way point the held note keeps its claim, in cents.
 * `(prov.)` — the owner's ear closes it (roadmap Q65).
 *
 * Inside `(50, 50 + h]` the reading is closer to the neighbour but not clearly
 * so, and the neighbour has to hold the claim for `TUNER_ACCEPT_FRAMES` to win
 * it. Past `50 + h` the reading is unambiguous and the switch is immediate —
 * a singer sliding to the next note must not watch the display lag behind.
 */
export const TUNER_HYSTERESIS_CENTS = 15;

/** Consecutive frames a neighbour must be nominated inside the overlap band. `(prov.)` */
export const TUNER_ACCEPT_FRAMES = 5;

/**
 * How long the drawn reading survives silence before it blanks. `(prov.)`
 *
 * Cleartune holds; the honest variant holds AND says so, which is what
 * `TunerDrawn.stale` is for — the reading greys out and the Hz line says
 * `unvoiced` from the very first silent frame, so nobody reads a held number
 * as a live one.
 */
export const TUNER_STALE_FRAMES = 25;

/** One frame, as the tuner sees it. */
export interface TunerSample {
  readonly f0Hz: number | null;
  readonly clarity: number;
  /** The match against a set reference, or `null` when the tuner is chromatic. */
  readonly match: MatchState | null;
  /** The preset declares no f0 overlay: there is nothing to tune against. */
  readonly estimatorOff: boolean;
}

export interface TunerParams {
  /** `dampingAlpha(hop, tau)`; 1 is no damping at all. */
  readonly alpha: number;
  readonly hysteresisCents: number;
  readonly acceptFrames: number;
  readonly staleFrames: number;
  readonly a4Hz: number;
  readonly held: boolean;
}

/** What the big readout shows. Smoothed, hysteretic, and possibly frozen. */
export interface TunerDrawn {
  readonly midi: number | null;
  /** `A4`, or `null` when there is nothing to name. */
  readonly label: string | null;
  /** Deviation from `midi` (chromatic) or from the reference, SMOOTHED. */
  readonly cents: number | null;
  readonly state: MatchBand | 'unvoiced' | 'off' | 'none';
  readonly direction: 'flat' | 'sharp' | null;
  /** The voice stopped and this reading is being held; it is not live. */
  readonly stale: boolean;
}

/** What was actually measured this frame. Never smoothed, never held. */
export interface TunerMeasured {
  readonly f0Hz: number | null;
  readonly clarity: number;
  /** The raw deviation the drawn one is a filtered version of. */
  readonly cents: number | null;
}

export interface TunerState {
  readonly drawn: TunerDrawn;
  readonly measured: TunerMeasured;
  /** The neighbour currently making a claim inside the overlap band. */
  readonly candidateMidi: number | null;
  readonly candidateFrames: number;
  readonly unvoicedFrames: number;
  /**
   * The previous frame was measured against a REFERENCE rather than against
   * the nearest equal-tempered note.
   *
   * Those are two different axes even when they name the same note: a
   * reference set 30 cents sharp of A4 is still "A4", and the cents beside it
   * jump by 30 the instant it is set or cleared. Without this the smoother
   * would carry across that jump and draw the needle sweeping through
   * positions the voice never had — the same defect the note-boundary rule
   * exists to prevent, arriving by a different door.
   */
  readonly wasReference: boolean;
  /**
   * The reference the previous frame was measured against, in Hz, or `null`.
   *
   * `wasReference` alone catches a reference ARRIVING and being CLEARED; it
   * does not catch one being REPLACED. Type a new note while the old one is
   * set and the axis moves under the reading without the note name having to
   * change at all — the ladder buttons do exactly that, one semitone at a
   * time. Same defect, third door.
   */
  readonly referenceHz: number | null;
  /**
   * The previous frame was frozen by HOLD.
   *
   * Releasing HOLD must RESET the smoother, not ease out of it. The frozen
   * value can be seconds old and from a different phrase, so easing from it
   * draws the needle sliding in from a stale position — the very thing
   * `dampCents(null, …)` exists to prevent, and the reason the first reading
   * after silence is not smoothed either.
   */
  readonly wasHeld: boolean;
}

const BLANK_DRAWN: TunerDrawn = {
  midi: null,
  label: null,
  cents: null,
  state: 'none',
  direction: null,
  stale: false,
};

export const TUNER_INITIAL: TunerState = {
  drawn: BLANK_DRAWN,
  measured: { f0Hz: null, clarity: 0, cents: null },
  candidateMidi: null,
  candidateFrames: 0,
  unvoicedFrames: 0,
  wasReference: false,
  referenceHz: null,
  wasHeld: false,
};

function labelOf(midi: number, a4Hz: number): string {
  const named = noteName(noteHz(midi, a4Hz), a4Hz);
  return named === null ? '—' : `${named.name}${String(named.octave)}`;
}

/**
 * May the previous drawn value be smoothed into this one?
 *
 * Only when it is on the SAME AXIS and genuinely the frame before: not across
 * a note change, not across the arrival or removal of a reference (which
 * changes what the cents are measured FROM, even when the note is unchanged),
 * not out of silence, and not out of a freeze.
 */
function canCarry(
  prev: TunerState,
  midi: number | null,
  isReference: boolean,
  referenceHz: number | null,
): boolean {
  return (
    prev.drawn.midi === midi &&
    prev.wasReference === isReference &&
    prev.referenceHz === referenceHz &&
    prev.unvoicedFrames === 0 &&
    !prev.wasHeld
  );
}

function directionOf(centsOffset: number): 'flat' | 'sharp' | null {
  return centsOffset > 0 ? 'sharp' : centsOffset < 0 ? 'flat' : null;
}

/**
 * Advance the tuner by one frame.
 *
 * Pure: the same `(prev, sample, params, constants)` always gives the same
 * next state, which is what lets the step response, the hysteresis and the
 * no-tween rule be unit tests rather than something judged by eye.
 */
export function tunerStep(
  prev: TunerState,
  sample: TunerSample,
  params: TunerParams,
  constants: ReferenceConstants = REFERENCE_CONSTANTS,
): TunerState {
  // A preset with no f0 overlay has nothing to tune against, and saying so is
  // better than drawing a dash that looks like silence.
  if (sample.estimatorOff) {
    return {
      ...TUNER_INITIAL,
      wasReference: sample.match !== null,
      referenceHz: sample.match?.referenceHz ?? null,
      drawn: { ...BLANK_DRAWN, state: 'off' },
      measured: { f0Hz: sample.f0Hz, clarity: sample.clarity, cents: null },
    };
  }

  // The raw reading, computed before anything is smoothed or held, so it is
  // available even in the branches that draw nothing.
  const rawCents =
    sample.match !== null
      ? sample.match.cents
      : sample.f0Hz !== null && sample.f0Hz > 0
        ? (noteName(sample.f0Hz, params.a4Hz)?.cents ?? null)
        : null;
  const measured: TunerMeasured = { f0Hz: sample.f0Hz, clarity: sample.clarity, cents: rawCents };

  // HOLD freezes the picture and nothing else. The measurement below it keeps
  // running, and every surface that is not this readout keeps showing it.
  if (params.held) {
    return { ...prev, measured, wasHeld: true };
  }

  if (sample.f0Hz === null || rawCents === null) {
    const unvoicedFrames = prev.unvoicedFrames + 1;
    const holding = prev.drawn.midi !== null && unvoicedFrames <= params.staleFrames;
    return {
      drawn: holding
        ? { ...prev.drawn, stale: true }
        : { ...BLANK_DRAWN, state: sample.match === null ? 'none' : 'unvoiced' },
      measured,
      candidateMidi: null,
      candidateFrames: 0,
      unvoicedFrames,
      wasReference: sample.match !== null,
      referenceHz: sample.match?.referenceHz ?? null,
      wasHeld: false,
    };
  }

  // A reference fixes the note: there is nothing to name and nothing to
  // hysterise, because the singer chose the target and it does not move.
  if (sample.match !== null) {
    const target = noteName(sample.match.referenceHz, params.a4Hz);
    const midi = target?.midi ?? null;
    // Reset the smoother when the target itself changed, or when the voice has
    // just come back: either way the previous drawn value is on a different
    // axis or from a different phrase.
    const carry = canCarry(prev, midi, true, sample.match.referenceHz) ? prev.drawn.cents : null;
    const drawnCents = dampCents(carry, sample.match.cents ?? 0, params.alpha);
    return {
      drawn: {
        midi,
        label: midi === null ? null : labelOf(midi, params.a4Hz),
        cents: drawnCents,
        state: sample.match.state,
        direction: sample.match.direction,
        stale: false,
      },
      measured,
      candidateMidi: null,
      candidateFrames: 0,
      unvoicedFrames: 0,
      wasReference: true,
      referenceHz: sample.match.referenceHz,
      wasHeld: false,
    };
  }

  // CHROMATIC. The held note keeps its claim until the reading has clearly
  // left it; `nearest` is only ever a candidate.
  const nearest = noteName(sample.f0Hz, params.a4Hz);
  if (nearest === null) {
    return { ...prev, measured, unvoicedFrames: 0, wasReference: false, referenceHz: null, wasHeld: false };
  }
  const held = prev.drawn.midi;
  let midi = nearest.midi;
  let candidateMidi: number | null = null;
  let candidateFrames = 0;
  if (held !== null && held !== nearest.midi) {
    const fromHeld = cents(sample.f0Hz, noteHz(held, params.a4Hz));
    const magnitude = Math.abs(fromHeld);
    if (magnitude <= 50 + params.hysteresisCents) {
      // Inside the overlap band: the neighbour has to earn it.
      const sameCandidate = prev.candidateMidi === nearest.midi;
      const frames = sameCandidate ? prev.candidateFrames + 1 : 1;
      if (frames >= params.acceptFrames) {
        midi = nearest.midi;
      } else {
        midi = held;
        candidateMidi = nearest.midi;
        candidateFrames = frames;
      }
    }
    // Beyond 50 + h, `midi` stays `nearest.midi`: an unambiguous reading
    // switches at once, so a singer sliding upward is never lagged.
  }

  const offset = midi === nearest.midi ? nearest.cents : cents(sample.f0Hz, noteHz(midi, params.a4Hz));
  // NO TWEEN ACROSS A BOUNDARY: a change of note is a change of axis, and a
  // smoother carried across it draws positions the voice never had.
  const carry = canCarry(prev, midi, false, null) ? prev.drawn.cents : null;
  const drawnCents = dampCents(carry, offset, params.alpha);
  return {
    drawn: {
      midi,
      label: labelOf(midi, params.a4Hz),
      cents: drawnCents,
      state: matchBand(offset, constants),
      direction: directionOf(offset),
      stale: false,
    },
    measured,
    candidateMidi,
    candidateFrames,
    unvoicedFrames: 0,
    wasReference: false,
    referenceHz: null,
    wasHeld: false,
  };
}

/**
 * The line under the drawn cents. It exists because the drawn number is not
 * the measured one, and a display filter that does not say its time constant
 * is a display that lies quietly ([12 R20]).
 */
export function describeDamping(ms: number, held: boolean): string {
  const base = ms <= 0 ? 'damping off' : `damping ${String(Math.round(ms))} ms (prov.)`;
  return held ? `${base} · held` : base;
}

/** `ref A3 · 220.00 Hz`, or the chromatic case with its concert pitch on show. */
export function tunerReferenceLine(reference: Reference | null, a4Hz: number = A4_HZ): string {
  if (reference === null) {
    return `chromatic · A4 = ${String(a4Hz)} Hz (prov.)`;
  }
  const named = noteName(reference.f0Hz, a4Hz);
  const label = named === null ? '—' : `${named.name}${String(named.octave)}`;
  return `ref ${label} · ${reference.f0Hz.toFixed(2)} Hz`;
}
