//
// The seam: one function that opens whichever source the session was asked
// for, and one shape it hands back.
//
// WHY A SEAM AND NOT AN `if` IN `session.ts`. The session's job is to be the
// single place that holds a running capture, a Worker and five panes at once
// (its header says so). Which KIND of sound is arriving is not part of that
// job, and an `if` there would spread across four places — the open, the chain
// it reports, the transport it exposes and the teardown. Here it is one
// switch, and everything downstream of `OpenSource` is written once.
//
// THE SHAPE IS THE MICROPHONE'S, WIDENED BY EXACTLY ONE FIELD. `transport` is
// `null` for a microphone, because there is nothing to play, pause or loop
// about a live input — you cannot rewind a room. Every other field means the
// same thing for both, which is what makes `session.ts`'s hop relay and
// teardown source-agnostic without knowing this file exists.
// ----------------------------------------------------------------------------

import { openCapture, type CaptureOptions } from './capture';
import { openFileSource, type DecodedAudioFile, type FileTransport } from './file-source';
import type { CaptureChain } from './chain';
import type { Region } from '../app/transport';

export type SourceRequest =
  | { readonly kind: 'microphone'; readonly deviceId?: string }
  | {
      readonly kind: 'file';
      readonly file: DecodedAudioFile;
      readonly loop?: boolean;
      readonly region?: Region | null;
      /** Start playing as the graph comes up — what "Start" means for a file. */
      readonly autoplay?: boolean;
    };

export interface OpenSource {
  readonly chain: CaptureChain;
  readonly context: AudioContext;
  /** The worklet node. Its `port` delivers one message per hop, whatever fed it. */
  readonly node: AudioWorkletNode;
  /** `null` for a microphone: a room has no transport. */
  readonly transport: FileTransport | null;
  close(): Promise<void>;
}

export async function openSource(request: SourceRequest, options: CaptureOptions): Promise<OpenSource> {
  if (request.kind === 'file') {
    const source = await openFileSource({
      ...options,
      decoded: request.file,
      ...(request.loop === undefined ? {} : { loop: request.loop }),
      ...(request.region === undefined ? {} : { region: request.region }),
      ...(request.autoplay === undefined ? {} : { autoplay: request.autoplay }),
    });
    return {
      chain: source.chain,
      context: source.context,
      node: source.node,
      transport: source.transport,
      close: () => source.close(),
    };
  }
  const capture = await openCapture({
    ...options,
    ...(request.deviceId === undefined ? {} : { deviceId: request.deviceId }),
  });
  return {
    chain: capture.chain,
    context: capture.context,
    node: capture.node,
    transport: null,
    close: () => capture.close(),
  };
}
