//
// A local audio file as the live source: decode it once, play it to the
// output, and feed the SAME worklet the microphone feeds.
//
// WHY THIS EXISTS (ADR 0021 decision 7(c), second note, 2026-08-22). The owner
// practises against isolated vocal stems. They are MP3, usually stereo at
// 44.1 kHz, and nothing hand-written in this repository decodes those — so
// this is the ONE place in the application that calls `decodeAudioData`, the
// call 7(c) refuses by name. The refusal's reason is that a Tier-0 file
// decoded through it "is not the file the manifest's sha256 names": it is an
// objection to a GOLDEN INPUT, and a stem is something to sing along to, not
// something to measure. So the call is permitted here and only here, and the
// three stages the browser adds — the codec and its unstated int16 → float
// convention, the resample, and the down-mix — are each DECLARED by
// `chain.ts`'s `describeFileDecode` and travel with every number this session
// produces. None of them meets a golden.
//
// DECODED ON AN OfflineAudioContext, AT THE PRESET'S RATE. Two reasons, both
// load-bearing. The buffer must OUTLIVE the session — a preset switch closes
// the live context (`capture.ts` `close()`), and re-reading and re-decoding a
// 40 MB stem on every switch is a visible stall — and an `AudioBuffer` is
// context-independent, so one decoded offline plays into any context. And
// decoding AT the preset's rate means `buffer.sampleRate === context.sampleRate`
// when it is played, so there is exactly one resample in the chain (the
// decoder's, declared) rather than a second one nobody would have named.
//
// THE `File` IS KEPT, THE `ArrayBuffer` IS NOT REUSED. `decodeAudioData`
// DETACHES the buffer it is handed. A second decode at another rate — which
// `stem_analysis` at 48 kHz needs — from the same `ArrayBuffer` throws, and
// the probe's `Uint8Array` view over it reads as empty afterwards. So the
// `File` is retained and re-read, and the probe runs BEFORE the decode.
//
// TWO EDGES OUT OF ONE NODE. `AudioBufferSourceNode → hopNode` is the analysis
// (zero outputs, a sink) and `AudioBufferSourceNode → destination` is what the
// singer hears. Sample-synchronous by construction, because they are the same
// node: what is analysed IS what is heard, with no second gain stage to
// declare.
//
// EVERY TRANSPORT DECISION IS `app/transport.ts`'s. This file owns no rule
// about when to rebuild a node; it runs the commands the reducer returns. The
// one thing it adds is node IDENTITY: `onended` fires for a node we stopped
// ourselves as well as for one that reached its end, so the handler checks it
// is still the current node before telling the reducer the file ended.
// ----------------------------------------------------------------------------

import {
  buildFileChain,
  type FileChain,
} from './chain';
import { createAnalysisContext, createHopNode, type CaptureOptions } from './capture';
import { probeAudio, type AudioProbe } from '../io/audio-probe';
import {
  initialTransport,
  isRegionRefusal,
  positionAt,
  transportReduce,
  validateRegion,
  type Region,
  type RegionRefusal,
  type TransportCommand,
  type TransportState,
} from '../app/transport';
import type { Refusal } from '../app/reference';

/** Why a file could not become a source. Shown in the state cell, never thrown at a console. */
export type FileLoadRefusal = Refusal<'read' | 'decode' | 'empty' | 'too-short'>;

export function isFileLoadRefusal(value: DecodedAudioFile | FileLoadRefusal): value is FileLoadRefusal {
  return (value as FileLoadRefusal).refused === true;
}

/**
 * What a DERIVED buffer is derived from (ADR 0023 decision 3).
 *
 * Present only on a render, absent on a decode, and that absence is the type's
 * way of saying "this is the file". Every label the interface shows about a
 * stretched source reads these fields; nothing infers "derived" from a name or
 * a flag somewhere else, because a label carried by a string is a label that
 * comes off.
 */
export interface DerivedProvenance {
  readonly kind: 'stretch';
  /** The file the render came from. */
  readonly sourceName: string;
  /** The region of that file, in seconds. */
  readonly regionS: readonly [number, number];
  readonly stretch: number;
  readonly windowSamples: number;
  readonly seed: number;
  readonly gain: number;
  /** What the peak guard did, in dB. 0 when it did not fire. */
  readonly peakGuardDb: number;
  readonly renderMs: number;
}

export interface DecodedAudioFile {
  readonly name: string;
  readonly bytes: number;
  /** What the container's own header said, read BEFORE the decode detached it. */
  readonly probe: AudioProbe;
  /** Decoded at `buffer.sampleRate`, which is the preset rate it was decoded for. */
  readonly buffer: AudioBuffer;
  /** Kept so another preset's rate can be decoded from it; `decodeAudioData` detaches ArrayBuffers. */
  readonly file: File;
  /** Absent on a decode. Present on a render — see `DerivedProvenance`. */
  readonly derived?: DerivedProvenance;
}

/**
 * Read, probe and decode a file for one analysis rate.
 *
 * Refuses with a sentence rather than throwing: every one of these is
 * something the singer did (picked a text file, picked a 40 ms sample) and the
 * state cell is where they will look.
 */
export async function decodeAudioFile(
  file: File,
  sampleRateHz: number,
  minFrames: number,
): Promise<DecodedAudioFile | FileLoadRefusal> {
  let raw: ArrayBuffer;
  try {
    raw = await file.arrayBuffer();
  } catch (error) {
    return {
      refused: true,
      reason: 'read',
      message: `${file.name} could not be read: ${error instanceof Error ? error.message : String(error)}`,
    };
  }
  // BEFORE the decode: `decodeAudioData` detaches the buffer, and a view over
  // a detached buffer reads as empty.
  const probe = probeAudio(new Uint8Array(raw));

  // An OfflineAudioContext of one frame: it is never rendered, it exists only
  // to own `decodeAudioData` at a rate of our choosing.
  const offline = new OfflineAudioContext(1, 1, sampleRateHz);
  let buffer: AudioBuffer;
  try {
    buffer = await offline.decodeAudioData(raw);
  } catch (error) {
    const name = error instanceof DOMException ? error.name : 'error';
    const detail = error instanceof Error ? error.message : String(error);
    return {
      refused: true,
      reason: 'decode',
      message:
        `${file.name} could not be decoded by this browser (${name}${detail === '' ? '' : `: ${detail}`}). ` +
        'WAV, MP3, FLAC and OGG are what its decoder reads.',
    };
  }
  if (buffer.length === 0) {
    return { refused: true, reason: 'empty', message: `${file.name} decoded to zero samples` };
  }
  if (buffer.length < minFrames) {
    return {
      refused: true,
      reason: 'too-short',
      message:
        `${file.name} is ${String(buffer.length)} frames at ${String(sampleRateHz)} Hz, shorter than one ` +
        `${String(minFrames)}-sample analysis window — no column could ever be computed from it`,
    };
  }
  return { name: file.name, bytes: file.size, probe, buffer, file };
}

/** Raised when a buffer decoded for one rate reaches a context at another. The shell re-decodes. */
export class DecodeRateMismatch extends Error {
  readonly bufferRateHz: number;
  readonly contextRateHz: number;
  constructor(bufferRateHz: number, contextRateHz: number) {
    super(
      `the file was decoded at ${String(bufferRateHz)} Hz and this AudioContext runs at ` +
        `${String(contextRateHz)} Hz; it must be decoded again for this preset`,
    );
    this.name = 'DecodeRateMismatch';
    this.bufferRateHz = bufferRateHz;
    this.contextRateHz = contextRateHz;
  }
}

export type TransportListener = (event: 'stream-change' | 'state') => void;

export interface FileTransport {
  state(): TransportState;
  /** The position right now, resolved against the context clock. */
  positionS(): number;
  play(): void;
  pause(): void;
  seek(toS: number): void;
  setLoop(loop: boolean): void;
  setRegion(startS: number, endS: number | null): Region | RegionRefusal;
  /** `stream-change` after every new node (the session resets the Worker); `state` after every step. */
  subscribe(listener: TransportListener): () => void;
}

export interface OpenFileSource {
  readonly chain: FileChain;
  readonly context: AudioContext;
  readonly node: AudioWorkletNode;
  readonly transport: FileTransport;
  close(): Promise<void>;
}

export interface FileSourceOptions extends CaptureOptions {
  readonly decoded: DecodedAudioFile;
  /** The loop and region to open with — the shell's, so they survive a preset switch. */
  readonly loop?: boolean;
  readonly region?: Region | null;
  /** Start playing as soon as the graph is up. The owner's choice: Start plays. */
  readonly autoplay?: boolean;
}

export async function openFileSource(options: FileSourceOptions): Promise<OpenFileSource> {
  const { decoded } = options;
  const context = await createAnalysisContext(
    options.sampleRateHz,
    decoded.probe.sampleRateHz,
    'file',
  );
  if (decoded.buffer.sampleRate !== context.sampleRate) {
    await context.close();
    throw new DecodeRateMismatch(decoded.buffer.sampleRate, context.sampleRate);
  }

  // `speakers`, not the microphone's `discrete`: see `createHopNode`. A stem is
  // stereo, and under `discrete` this would analyse the left channel alone
  // while the panel said the browser averaged both.
  const node = createHopNode(context, {
    windowLength: options.windowLength,
    hopSamples: options.hopSamples,
    channelInterpretation: 'speakers',
  });

  const durationS = decoded.buffer.duration;
  const chain = buildFileChain({
    presetSampleRate: options.sampleRateHz,
    contextSampleRate: context.sampleRate,
    ...(decoded.derived === undefined ? {} : { derived: decoded.derived }),
    fileName: decoded.name,
    fileBytes: decoded.bytes,
    probe: decoded.probe,
    decoded: {
      sampleRateHz: decoded.buffer.sampleRate,
      channels: decoded.buffer.numberOfChannels,
      durationS,
      frames: decoded.buffer.length,
    },
    baseLatencyS: context.baseLatency,
    outputLatencyS: typeof context.outputLatency === 'number' ? context.outputLatency : null,
    dcBlocker: options.dcBlocker,
    userAgent: navigator.userAgent,
  });

  const requested = options.region ?? null;
  const validated = requested === null ? null : validateRegion(requested.startS, requested.endS, durationS);
  const region = validated !== null && !isRegionRefusal(validated) ? validated : { startS: 0, endS: durationS };

  let state = initialTransport(durationS, options.loop ?? false, region);
  let current: AudioBufferSourceNode | null = null;
  let closed = false;
  const listeners = new Set<TransportListener>();

  const notify = (event: 'stream-change' | 'state'): void => {
    listeners.forEach((listener) => { listener(event); });
  };

  const stopNode = (): void => {
    if (current === null) {
      return;
    }
    const node_ = current;
    current = null;
    // Cleared FIRST: a node we stop fires `onended` too, and the handler would
    // otherwise report the file as finished.
    node_.onended = null;
    try {
      node_.stop();
    } catch {
      // Already stopped, or never started. Nothing to undo.
    }
    node_.disconnect();
  };

  const startNode = (command: Extract<TransportCommand, { type: 'start-node' }>): void => {
    if (closed) {
      return;
    }
    const source = new AudioBufferSourceNode(context, { buffer: decoded.buffer });
    source.loop = command.loop;
    source.loopStart = command.region.startS;
    source.loopEnd = command.region.endS;
    source.connect(node);
    source.connect(context.destination);
    source.onended = (): void => {
      // Identity, not a flag: this node may have been superseded between the
      // stop and the event, and only the current one reaching its end is "the
      // file ended".
      if (source === current) {
        step({ type: 'ended', nowS: context.currentTime });
      }
    };
    current = source;
    if (command.loop) {
      source.start(0, command.offsetS);
    } else {
      // NO DURATION when the loop is off. The region is then a pair of marks,
      // not a cage: playback runs to the end of the buffer, exactly as it
      // would if A and B had never been pressed. Giving it
      // `region.end − offset` is what used to make a marked song stop dead at
      // B with the loop switched off — the other half of "the loop got the
      // song stuck".
      source.start(0, command.offsetS);
    }
    // The ring holds samples from the position we just left. See the worklet.
    node.port.postMessage({ type: 'reset' });
    notify('stream-change');
  };

  const run = (commands: readonly TransportCommand[]): void => {
    for (const command of commands) {
      switch (command.type) {
        case 'stop-node':
          stopNode();
          break;
        case 'start-node':
          startNode(command);
          break;
        case 'suspend':
          void context.suspend();
          break;
        case 'resume':
          void context.resume();
          break;
      }
    }
  };

  function step(event: Parameters<typeof transportReduce>[1]): void {
    if (closed) {
      return;
    }
    const next = transportReduce(state, event);
    state = next.state;
    run(next.commands);
    notify('state');
  }

  const transport: FileTransport = {
    state: () => state,
    positionS: () => positionAt(state, context.currentTime),
    play: () => { step({ type: 'play', nowS: context.currentTime }); },
    pause: () => { step({ type: 'pause', nowS: context.currentTime }); },
    seek: (toS: number) => { step({ type: 'seek', toS, nowS: context.currentTime }); },
    setLoop: (loop: boolean) => { step({ type: 'set-loop', loop, nowS: context.currentTime }); },
    setRegion: (startS: number, endS: number | null): Region | RegionRefusal => {
      const result = validateRegion(startS, endS, durationS);
      if (isRegionRefusal(result)) {
        return result;
      }
      step({ type: 'set-region', region: result, nowS: context.currentTime });
      return result;
    },
    subscribe: (listener: TransportListener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };

  if (options.autoplay ?? false) {
    transport.play();
  }

  return {
    chain,
    context,
    node,
    transport,
    async close(): Promise<void> {
      if (closed) {
        return;
      }
      closed = true;
      listeners.clear();
      node.port.onmessage = null;
      stopNode();
      node.disconnect();
      await context.close();
    },
  };
}
