//
// What the browser's capture chain ACTUALLY IS — assembled as plain data, with
// no Web Audio and no DOM anywhere in this file.
//
// WHY THIS IS A MODULE OF ITS OWN. ADR 0021 decision 8: "Raw-capture
// constraints are **mandatory and insufficient** — some drivers and browsers
// process regardless ... so the app reads back `track.getSettings()` and shows
// what it actually got." A read-back that lives inside the function that opens
// the stream can only be checked by opening a stream, which needs a microphone,
// a user gesture and a browser. Everything that DECIDES anything therefore
// lives here, where `vitest --project unit` can drive it in node:
// `rateVerdict` (the refusal), `describeResampler` (the declaration) and
// `buildChain` (the snapshot). `capture.ts` supplies the facts and does as it
// is told.
//
// TWO RATES, TWO DIFFERENT RULES — the distinction this file exists to keep.
//
//   * The **AudioContext** rate is the rate the analysis runs at. ADR 0021
//     decision 7(c): a context rate that is not the preset's `sample_rate_hz`
//     makes `bin_width_hz` and `enbw_hz` fiction, so capture REFUSES to start
//     and the message names both numbers. The watch's validate-and-reject rule
//     (ADR 0010 decision 7: reject, never coerce), applied in the browser.
//   * The **track** rate is the rate the device is delivering to the browser's
//     own graph. When it differs from the context rate the browser is
//     resampling internally, before a single sample reaches us. That is a
//     DIFFERENT STAGE from the one ADR 0021 anticipated, we cannot refuse it
//     (the browser will not tell us in advance and often will not honour a
//     `sampleRate` constraint at all), and pretending it is not there is the
//     one thing ADR 0003 d.7 forbids: a rate conversion in the chain is linear
//     and **declared**. So it is DECLARED — a sentence in the capture-chain
//     panel and in every report — and never silently accepted.
// ----------------------------------------------------------------------------

import type { AudioProbe } from '../io/audio-probe';
import type { DerivedProvenance } from './file-source';

/** One channel: the watch has one PDM microphone and every preset is mono (ADR 0003). */
export const CAPTURE_CHANNEL_COUNT = 1;

/**
 * The constraint object handed to `getUserMedia`, as a fact we can print.
 *
 * The three processing flags are `false` LITERALS in the type, not `boolean`:
 * ADR 0021 decision 1 fixes them, and a build that could put `true` here would
 * be a build that could feed a noise-suppressed spectrum to a formant readout.
 * `tsc` is the thing that stops it (proposal §3 tenet 2; CLAUDE.md Never 8's
 * reason, applied to the browser's own AFE rather than ESP-SR's).
 */
export interface RequestedConstraints {
  readonly sampleRate: number;
  readonly channelCount: number;
  readonly echoCancellation: false;
  readonly noiseSuppression: false;
  readonly autoGainControl: false;
}

/** Build the request for a preset's rate. One place, so the panel and the call cannot disagree. */
export function requestedConstraints(
  sampleRateHz: number,
  channelCount: number = CAPTURE_CHANNEL_COUNT,
): RequestedConstraints {
  return {
    sampleRate: sampleRateHz,
    channelCount,
    echoCancellation: false,
    noiseSuppression: false,
    autoGainControl: false,
  };
}

/**
 * A plain snapshot of `MediaStreamTrack.getSettings()`.
 *
 * Every field is optional because every field is optional IN THE BROWSER: the
 * Media Capture spec requires a settings dictionary, not any particular member
 * of it, and Firefox omits `sampleRate` on some platforms while Chromium omits
 * `latency`. An absent field and a field that reads `false` are different
 * answers to "is auto-gain off?" — the first is *unknown*, the second is *no* —
 * and this type keeps them apart so `processing.allOff` can too.
 */
export interface TrackFacts {
  readonly deviceId?: string;
  readonly label?: string;
  readonly sampleRate?: number;
  readonly channelCount?: number;
  readonly echoCancellation?: boolean;
  readonly noiseSuppression?: boolean;
  readonly autoGainControl?: boolean;
  readonly latency?: number;
}

/** The three flags ADR 0021 decision 8 requires to be read back, and the verdict over them. */
export interface ProcessingVerdict {
  readonly echoCancellation: boolean | null;
  readonly noiseSuppression: boolean | null;
  readonly autoGainControl: boolean | null;
  /** True only when all three read back `false`. An UNREPORTED flag is not an off flag. */
  readonly allOff: boolean;
}

export type SourceKind = 'microphone' | 'file';

/**
 * What every chain carries, whatever the sound came from — and what the footer
 * summary and the harness's mirror read without narrowing.
 *
 * `trackSampleRate` is deliberately the same field for both: for a microphone
 * it is `getSettings().sampleRate`, for a file it is the rate its own header
 * states. Both answer the one question the footer asks — what rate did this
 * sound arrive at, before the browser converted it to the context's — so
 * `44 kHz → 32 kHz` is printed by one line of code for both sources.
 */
interface ChainCommon {
  readonly requestedSampleRate: number;
  readonly contextSampleRate: number;
  /** `null` when the browser does not expose it (microphone) or the header did not say (file). */
  readonly trackSampleRate: number | null;
  /**
   * Non-null when there is a rate conversion to declare: a sentence naming
   * BOTH rates and saying the browser did it, inside its own graph or inside
   * its decoder. ADR 0003 d.7 — a conversion in the chain is declared.
   */
  readonly browserResampler: string | null;
  readonly deviceLabel: string;
  readonly processing: ProcessingVerdict;
  readonly baseLatencyS: number | null;
  readonly outputLatencyS: number | null;
  /** ADR 0006 D7's two numbers for the blocker this session runs, or `null` when it is off. */
  readonly dcBlocker: { readonly cutoffHz: number; readonly R: number } | null;
  readonly userAgent: string;
}

/** Everything the capture-chain panel shows for a microphone session. */
export interface MicrophoneChain extends ChainCommon {
  readonly source: 'microphone';
  readonly requested: RequestedConstraints;
  readonly track: TrackFacts;
  readonly capabilities: Readonly<Record<string, unknown>>;
}

/**
 * The same, for a file (ADR 0021 decision 7(c), second note).
 *
 * A UNION rather than optional fields on one shape, because the microphone's
 * three read-back fields have no honest value for a file: there is no
 * `MediaStreamTrack` to report settings for, no constraint was requested of
 * anything, and `capabilities` describes a device that is not in the chain.
 * An empty `TrackFacts` would render as "not reported by this browser", which
 * says the browser withheld something it was asked for. It was not asked.
 */
export interface FileChain extends ChainCommon {
  readonly source: 'file';
  readonly fileName: string;
  readonly fileBytes: number;
  /** What the container's own header said, or `'unknown'`. */
  readonly probe: AudioProbe;
  readonly decoded: {
    readonly sampleRateHz: number;
    readonly channels: number;
    readonly durationS: number;
    readonly frames: number;
  };
  /** The decoder, declared: what it is, and that its conversion convention is unstated. */
  readonly decode: string;
  /** The `0.5·(L+R)` sentence, or `null` when the decoded buffer is already mono. */
  readonly downmix: string | null;
  /** Present when this buffer is a RENDER rather than the file (ADR 0023). */
  readonly derived: DerivedProvenance | null;
  /** The sentence the panel shows for that render, or `null` when there is none. */
  readonly stretch: string | null;
}

export type CaptureChain = MicrophoneChain | FileChain;

/** The answer to "may this session start?" and the sentence that says why. */
export interface RateVerdict {
  readonly ok: boolean;
  readonly reason: string;
}

/**
 * ADR 0021 decision 7(c). A CONTEXT rate that is not the preset's rate REFUSES
 * to start, and the message names both numbers. A TRACK rate that differs is
 * NOT a refusal — it is reported in the same sentence and declared separately.
 *
 * The refusal text is written for the person holding the phone, not for a
 * console: it names the two numbers, says nothing is resampled and says what
 * to do about it. "A rate refusal renders as the banner text naming both rates
 * — never a thrown TypeError in a console nobody has open" is the shell's rule
 * and this string is what makes it possible.
 */
export function rateVerdict(
  presetRateHz: number,
  contextRateHz: number,
  trackRateHz: number | null,
  source: SourceKind = 'microphone',
): RateVerdict {
  if (!(presetRateHz > 0) || !(contextRateHz > 0)) {
    throw new RangeError(
      `sample rates must be positive, got preset ${String(presetRateHz)} Hz and context ${String(contextRateHz)} Hz`,
    );
  }
  // The same fact — where the sound's own rate differs from the context's —
  // told in the words of the source it came from. "The browser does not report
  // the track's own rate" is a true sentence about a microphone and a
  // nonsensical one about a file, which has no track and whose rate was not
  // withheld by anyone: its header simply did not say.
  const trackClause =
    source === 'file'
      ? trackRateHz === null
        ? ' The file’s own rate is not stated by its header.'
        : trackRateHz === contextRateHz
          ? ` The file states the same ${String(trackRateHz)} Hz.`
          : ` The file states ${String(trackRateHz)} Hz, which the browser resamples as it decodes.`
      : trackRateHz === null
        ? ' The browser does not report the track’s own rate.'
        : trackRateHz === contextRateHz
          ? ` The input track reports the same ${String(trackRateHz)} Hz.`
          : ` The input track reports ${String(trackRateHz)} Hz, which the browser resamples on its way in.`;

  if (contextRateHz !== presetRateHz) {
    return {
      ok: false,
      reason:
        `The preset asks for ${String(presetRateHz)} Hz and this browser opened the AudioContext at ` +
        `${String(contextRateHz)} Hz. Capture will not start: nothing here resamples, and analysing at ` +
        `${String(contextRateHz)} Hz under a preset written for ${String(presetRateHz)} Hz would make its ` +
        'bin_width_hz and enbw_hz fiction (ADR 0021 decision 7c — the watch’s validate-and-reject rule). ' +
        'Choose a preset at this device’s rate, or set the operating system’s input rate to ' +
        `${String(presetRateHz)} Hz and reload.${trackClause}`,
    };
  }
  return {
    ok: true,
    reason: `AudioContext.sampleRate is ${String(contextRateHz)} Hz, the preset’s own rate.${trackClause}`,
  };
}

/**
 * The declaration of decision 7(c)'s *other* stage: a resampler inside the
 * browser, between the device and the AudioContext.
 *
 * `null` — nothing to declare — when the track rate is unknown or equals the
 * context rate. Otherwise a sentence naming both rates, which the panel shows
 * and which travels with every number the session produces.
 */
export function describeResampler(contextRateHz: number, trackRateHz: number | null): string | null {
  if (trackRateHz === null || trackRateHz === contextRateHz) {
    return null;
  }
  return (
    `The input track runs at ${String(trackRateHz)} Hz and this AudioContext at ${String(contextRateHz)} Hz, ` +
    'so the browser is resampling between them inside its own graph, before any sample reaches this ' +
    'application. Nothing here added that stage and nothing here can remove it — it is DECLARED, which is ' +
    'ADR 0003 d.7’s rule for a conversion in the chain (linear and declared), and ADR 0021 decision 7(c) ' +
    'names only the CONTEXT-rate mismatch, which is a different stage. Every number from this session ' +
    'carries this sentence.'
  );
}

/** Read the three processing flags back, keeping "unreported" apart from "off". */
export function processingVerdict(track: TrackFacts): ProcessingVerdict {
  const ec = track.echoCancellation ?? null;
  const ns = track.noiseSuppression ?? null;
  const agc = track.autoGainControl ?? null;
  return {
    echoCancellation: ec,
    noiseSuppression: ns,
    autoGainControl: agc,
    allOff: ec === false && ns === false && agc === false,
  };
}

/**
 * What `buildChain` is given. Deliberately plain data — no `MediaStreamTrack`,
 * no `AudioContext` — so the assembly is testable and so a browser object can
 * never be retained by a snapshot that outlives the stream.
 */
export interface ChainParts {
  readonly presetSampleRate: number;
  readonly contextSampleRate: number;
  readonly requested: RequestedConstraints;
  readonly track: TrackFacts;
  readonly capabilities?: Readonly<Record<string, unknown>> | undefined;
  readonly baseLatencyS?: number | null | undefined;
  readonly outputLatencyS?: number | null | undefined;
  readonly dcBlocker?: { readonly cutoffHz: number; readonly R: number } | null | undefined;
  readonly userAgent?: string | undefined;
}

/** The label shown when the browser gives none — permission was granted but the label was withheld. */
export const UNLABELLED_DEVICE = '(unlabelled input — the browser withheld the device label)';

/** Pure assembly. Every derived field is derived HERE, so the panel renders and never computes. */
export function buildChain(parts: ChainParts): MicrophoneChain {
  const trackSampleRate = parts.track.sampleRate ?? null;
  return {
    source: 'microphone',
    requestedSampleRate: parts.presetSampleRate,
    contextSampleRate: parts.contextSampleRate,
    trackSampleRate,
    browserResampler: describeResampler(parts.contextSampleRate, trackSampleRate),
    deviceLabel:
      parts.track.label !== undefined && parts.track.label !== '' ? parts.track.label : UNLABELLED_DEVICE,
    requested: parts.requested,
    track: parts.track,
    capabilities: parts.capabilities ?? {},
    processing: processingVerdict(parts.track),
    baseLatencyS: parts.baseLatencyS ?? null,
    outputLatencyS: parts.outputLatencyS ?? null,
    dcBlocker: parts.dcBlocker ?? null,
    userAgent: parts.userAgent ?? '',
  };
}


/* --- the file source: three stages, each declared --------------------------- */

/** What `buildFileChain` is given. Plain data; no `AudioBuffer`, no context. */
export interface FileChainParts {
  readonly presetSampleRate: number;
  readonly contextSampleRate: number;
  readonly fileName: string;
  readonly fileBytes: number;
  readonly probe: AudioProbe;
  readonly decoded: FileChain['decoded'];
  readonly baseLatencyS?: number | null | undefined;
  readonly outputLatencyS?: number | null | undefined;
  readonly dcBlocker?: { readonly cutoffHz: number; readonly R: number } | null | undefined;
  readonly userAgent?: string | undefined;
  readonly derived?: DerivedProvenance | undefined;
}

/**
 * A decoder has no automatic gain control, no noise suppression and no echo
 * canceller — not "they read back false", but "there is no such stage".
 *
 * Stated as a literal rather than passed through `processingVerdict({})`,
 * which would report all three as `null` — *unknown* — and put a warning in
 * the panel about flags nobody requested of anything. The distinction between
 * "off" and "unreported" is the whole point of that function for a microphone
 * (ADR 0021 decision 8), and the honest answer for a file is neither: it is
 * "by construction".
 */
export function fileProcessingVerdict(): ProcessingVerdict {
  return { echoCancellation: false, noiseSuppression: false, autoGainControl: false, allOff: true };
}

export interface FileDecodeSentences {
  readonly decode: string;
  /** `null` when the file's own rate is the context's, or is unknown. */
  readonly resampler: string | null;
  /** `null` when the decoded buffer is mono. */
  readonly downmix: string | null;
}

/**
 * The three sentences a file session's numbers travel with.
 *
 * Same register and the same duty as `describeResampler` above: name the
 * stage, say who added it, say that nothing here can remove it, and say what
 * it means for the numbers. The decode sentence carries the clause ADR 0021
 * 7(c) uses to refuse `decodeAudioData` on the golden path — its scaling and
 * clipping convention are unstated — because the refusal's reason does not
 * stop being true when the call becomes permitted; it stops being disqualifying
 * and starts being a thing to declare.
 */
export function describeFileDecode(
  fileName: string,
  probe: AudioProbe,
  decoded: FileChain['decoded'],
  contextRateHz: number,
): FileDecodeSentences {
  const native =
    probe.sampleRateHz === null
      ? 'its header does not state a rate'
      : `its header states ${String(probe.sampleRateHz)} Hz`;
  const decode =
    `${fileName} (${probe.summary}) was decoded by this browser's own decoder through ` +
    `AudioContext.decodeAudioData into ${String(decoded.frames)} frames of ` +
    `${String(decoded.channels)}-channel float at ${String(decoded.sampleRateHz)} Hz — ${native}. ` +
    'The codec, the int16 → float scaling it applies and its clipping convention are the browser\'s and are ' +
    'unstated: that is the reason ADR 0021 decision 7(c) refuses this call on the injection and golden path, ' +
    'and the reason it is DECLARED here rather than measured (7(c), second note — a playback source is not ' +
    'injection mode). No number from this session is held to an oracle row.';

  const resampler =
    probe.sampleRateHz === null || probe.sampleRateHz === contextRateHz
      ? null
      : `The file runs at ${String(probe.sampleRateHz)} Hz and this AudioContext at ${String(contextRateHz)} Hz, ` +
        'so the browser resampled it inside its own decoder, before any sample reached this application. ' +
        'It is the same stage the microphone\'s track-rate declaration names, by ADR 0003 d.7\'s rule ' +
        '(a conversion in the chain is linear and declared), and every number from this session carries it.';

  const downmix =
    decoded.channels <= 1
      ? null
      : `The decoded buffer has ${String(decoded.channels)} channels and the analysis node is mono ` +
        "(channelCount 1, channelInterpretation 'speakers'), so the browser mixes them down by Web Audio's " +
        'published rule — 0.5·(L+R) for a stereo pair — at that node\'s input. That interpretation is set for a ' +
        "file and only for a file: the microphone's node is 'discrete', under which a 2 → 1 mix DROPS the second " +
        'channel, and this sentence would then be false. Playback to the output is the untouched buffer.';

  return { decode, resampler, downmix };
}

/**
 * The fourth declared stage, when there is one: this buffer is not the file.
 *
 * ADR 0021 7(c)'s note declares three stages a browser adds between a stem's
 * bytes and our first sample — the codec, the resample, the down-mix. A
 * stretch is a fourth, and it is ours rather than the browser's, which makes
 * it MORE our duty to declare and not less. The sentence names every number
 * the render is a function of, so that a reader can reproduce it: same file,
 * same region, same factor, same seed, same bytes out.
 */
export function describeStretch(derived: DerivedProvenance): string {
  const [startS, endS] = derived.regionS;
  const guard =
    derived.peakGuardDb === 0
      ? 'the peak guard did not fire'
      : `scaled ${derived.peakGuardDb.toFixed(1)} dB by the peak guard`;
  return (
    `${derived.stretch.toFixed(1)}× Paulstretch-family resynthesis of ` +
    `${startS.toFixed(2)}–${endS.toFixed(2)} s of ${derived.sourceName} (ADR 0023) · ` +
    `N = ${String(derived.windowSamples)} · window (1−x²)^1.25 · phases uniform random, ` +
    `seed 0x${derived.seed.toString(16)} · unity-RMS gain ×${derived.gain.toFixed(4)} · ${guard} · ` +
    'DC and Nyquist zeroed · a DERIVED signal: the f0 and the formant envelope are the file\'s, ' +
    'the timbre and the timing are not · no number from it meets an oracle row'
  );
}

/** Pure assembly for a file session; the panel renders these fields and computes nothing. */
export function buildFileChain(parts: FileChainParts): FileChain {
  const sentences = describeFileDecode(parts.fileName, parts.probe, parts.decoded, parts.contextSampleRate);
  const derived = parts.derived ?? null;
  return {
    source: 'file',
    requestedSampleRate: parts.presetSampleRate,
    contextSampleRate: parts.contextSampleRate,
    trackSampleRate: parts.probe.sampleRateHz,
    browserResampler: sentences.resampler,
    deviceLabel: `File: ${parts.fileName}`,
    processing: fileProcessingVerdict(),
    baseLatencyS: parts.baseLatencyS ?? null,
    outputLatencyS: parts.outputLatencyS ?? null,
    dcBlocker: parts.dcBlocker ?? null,
    userAgent: parts.userAgent ?? '',
    fileName: parts.fileName,
    fileBytes: parts.fileBytes,
    probe: parts.probe,
    decoded: parts.decoded,
    decode: sentences.decode,
    downmix: sentences.downmix,
    derived,
    stretch: derived === null ? null : describeStretch(derived),
  };
}
