//
// Several peaks, not one — and why every number here is provisional.
//
// The single marker of W1 is `peakOfLevels`: the first maximum of the column,
// interpolated. A singer's spectrum has a harmonic series, and the owner's
// first screenshot (2026-08-22, a D3 with eight visible harmonics and one
// marker, on the SECOND harmonic) is the brief for this file. Marking more
// peaks means deciding what a peak IS, and that decision has three knobs:
//
//   PROMINENCE — a local maximum must rise above its surroundings by at least
//     P dB. scipy's definition: walk left and right from the maximum until a
//     higher bin or the end of the column, take the lowest point reached on
//     each side, and the prominence is the drop to the higher of those two. This is
//     what rejects the shoulder of a window skirt (tiny prominence) and the
//     ripple of a noise floor (Rayleigh-distributed bins spread ≈ 5.6 dB).
//     Harmonics of a sung note are 40–100 dB prominent in a room.
//
//   SEPARATION — two accepted peaks are at least S·ENBW apart. The window's
//     main lobe is the resolution of the instrument: two tones closer than
//     ≈ 1.3 ENBW are ONE local maximum anyway (`twotone_1000_d2bin` in the
//     golden set), and the smallest resolved pair in that set is 2.67 ENBW
//     apart (`d4bin`). S = 2 keeps that pair and merges nothing a reader would
//     see as two.
//
//   DYNAMIC RANGE — an accepted peak is within R dB of the strongest one.
//     Prominence alone does not bound LEVEL: the first browser run on a −20 dBFS
//     sine (2026-08-22) marked the tone at 440 Hz and then seven noise-floor
//     ripples near −100 dBFS, each 10 dB prominent, because a Rayleigh floor
//     has exactly that structure. A harmonic 60 dB under the strongest partial
//     is not something a singer is shaping; R = 60 dB `(prov.)`.
//
//   COUNT — top K by level. Eight labels is what the panel can carry without
//     them overprinting; beyond that the picker is right and the drawing is
//     unreadable. This one is taste, and W3 says taste is the owner's.
//
// Peaks are picked on the SMOOTHED column, the one the trace is drawn from. A
// marker that disagrees with the line under it is two answers on one readout.
//
// HARMONIC LABELS are a separate, pure step: given an f0 from the time-domain
// estimator (`mpm.ts`), a peak within a tolerance of n·f0 is labelled `n`. The
// tolerance of 50 cents is the project's RPA threshold; at that width labels
// stay unique up to n = 34 (harmonic spacing 1200·log2((n+1)/n) > 100 cents),
// i.e. to 7.7 kHz at 220 Hz.
//
// THE INVARIANT THE REST OF THE APPLICATION LEANS ON: `peaks[0]`, when present,
// IS `peakOfLevels` — same bin, same Hz, same dB, same sub-bin offset. The
// strongest local maximum of the band is the band's argmax (a plateau at the
// argmax resolves to its lower bin on both sides), and it is accepted WITHOUT
// a prominence test — see `pickPeaks` for why, and `prominenceDb` for the two
// wrong versions that preceded the rule.
// `tests/golden/peaks-first-equals-peak-of-levels.test.ts` asserts it on every
// Tier-0 spectrum. When nothing clears the prominence floor (silence at −200)
// the list is EMPTY rather than a label on nothing.
// ---------------------------------------------------------------------------

import { cents } from './cents';
import { interpolatePeak, searchBounds, type PeakReading } from '../worker/protocol';

export interface PeakPickerParams {
  /** P: minimum prominence, dB. `(prov.)` */
  readonly prominenceDb: number;
  /** S: minimum distance between accepted peaks, in multiples of the window's ENBW. `(prov.)` */
  readonly minSeparationEnbw: number;
  /** R: a peak more than this far below the strongest is not reported. `(prov.)` */
  readonly maxBelowStrongestDb: number;
  /** K: at most this many peaks, strongest first. `(prov.)` */
  readonly maxPeaks: number;
  /** A peak within this many cents of n·f0 is labelled harmonic n. `(prov.)` */
  readonly harmonicToleranceCents: number;
}

export const DEFAULT_PEAK_PICKER: PeakPickerParams = Object.freeze({
  prominenceDb: 10,
  minSeparationEnbw: 2,
  maxBelowStrongestDb: 60,
  maxPeaks: 8,
  harmonicToleranceCents: 50,
});

export interface LabelledPeak extends PeakReading {
  /** The drop from this maximum to the higher of its two flanking minima, dB. */
  readonly prominenceDb: number;
  /** `n` when this peak sits within the tolerance of `n·f0`, else `null`. */
  readonly harmonic: number | null;
}

/**
 * Bins `k` in `[lo, hi]` with `levels[k] > levels[k−1]` and `levels[k] ≥ levels[k+1]`.
 * Neighbours outside the band count as −∞, so a band edge can be a maximum.
 * The asymmetric comparison resolves a two-bin plateau to its LOWER bin, which
 * is what `np.argmax` and `peakOfLevels` do with an exact tie.
 */
export function localMaxima(levelsDb: ArrayLike<number>, lo: number, hi: number): number[] {
  const out: number[] = [];
  let k = lo;
  while (k <= hi) {
    const here = levelsDb[k] as number;
    const left = k - 1 >= lo ? (levelsDb[k - 1] as number) : -Infinity;
    if (!(here > left)) {
      k += 1;
      continue;
    }
    // Walk a plateau of equal bins. It is ONE candidate, at its lower bin, and
    // only if it ends in a drop inside the band. A plateau that runs into the
    // band edge is not a peak — otherwise every flat floor would put a
    // "maximum" at `lo`, and silence would have one marker.
    let end = k;
    while (end + 1 <= hi && (levelsDb[end + 1] as number) === here) {
      end += 1;
    }
    const after = end + 1 <= hi ? (levelsDb[end + 1] as number) : Infinity;
    if (here > after) {
      out.push(k);
    }
    k = end + 1;
  }
  return out;
}

/**
 * scipy `peak_prominences`: walk left and right from `k` until a HIGHER bin or
 * the end of `[lo, hi]`, take the lowest point reached on each side, and the
 * prominence is the drop from the peak to the higher of those two minima. A
 * peak whose immediate neighbour is higher has prominence 0 — it is a skirt,
 * not a peak.
 *
 * `lo`/`hi` default to the WHOLE column, and `pickPeaks` calls it that way on
 * purpose. The first version bounded the walks to the search band, which made
 * the band's first bin a peak whenever a louder lobe sat just outside it: the
 * walk could not see the higher neighbour, so the skirt scored a full drop on
 * its in-band side. With the walks unbounded a skirt sees what it is a skirt
 * of. (A second version went the other way and gave an edge maximum a
 * one-sided prominence — which put a marker on the rumble below 60 Hz leaking
 * into `live_singing`'s band. Both are on record in the unit tests.)
 */
export function prominenceDb(
  levelsDb: ArrayLike<number>,
  k: number,
  lo: number = 0,
  hi: number = levelsDb.length - 1,
): number {
  const peak = levelsDb[k] as number;
  let leftMin = peak;
  for (let i = k - 1; i >= lo; i -= 1) {
    const v = levelsDb[i] as number;
    if (v > peak) {
      break;
    }
    if (v < leftMin) {
      leftMin = v;
    }
  }
  let rightMin = peak;
  for (let i = k + 1; i <= hi; i += 1) {
    const v = levelsDb[i] as number;
    if (v > peak) {
      break;
    }
    if (v < rightMin) {
      rightMin = v;
    }
  }
  return peak - Math.max(leftMin, rightMin);
}

/**
 * The peaks of one level column, strongest first, unlabelled (`harmonic: null`).
 *
 * `enbwHz` is the window's equivalent noise bandwidth in Hz — every
 * `FrameMessage` already carries it, so the separation rule needs nothing new.
 */
export function pickPeaks(
  levelsDb: ArrayLike<number>,
  fs: number,
  fftSize: number,
  enbwHz: number,
  params: PeakPickerParams = DEFAULT_PEAK_PICKER,
  minHz?: number | null,
  maxHz?: number | null,
): LabelledPeak[] {
  if (!(enbwHz > 0) || !Number.isFinite(enbwHz)) {
    throw new RangeError(`ENBW must be positive, got ${String(enbwHz)}`);
  }
  if (!Number.isInteger(params.maxPeaks) || params.maxPeaks < 1) {
    throw new RangeError(`maxPeaks must be a positive integer, got ${String(params.maxPeaks)}`);
  }
  const { lo, hi } = searchBounds(fs, fftSize, minHz, maxHz);
  const binWidth = fs / fftSize;
  const minSeparationBins = (params.minSeparationEnbw * enbwHz) / binWidth;

  // Stable sort by level, descending. Candidates are enumerated in bin order,
  // so an exact tie keeps the lower bin first — `peakOfLevels`'s choice.
  const candidates = localMaxima(levelsDb, lo, hi).sort(
    (a, b) => (levelsDb[b] as number) - (levelsDb[a] as number) || a - b,
  );

  const accepted: { bin: number; prominence: number }[] = [];
  let strongest: number | null = null;
  for (const k of candidates) {
    if (accepted.length >= params.maxPeaks) {
      break;
    }
    const prominence = prominenceDb(levelsDb, k);
    if (strongest === null) {
      // The strongest local maximum of the band IS `peakOfLevels` — the W1
      // marker — and it is accepted unconditionally, prominence reported as
      // measured. Every later candidate is held to the floor; this one is not,
      // because `peaks[0] ≡ peak` is the invariant the display leans on, and a
      // picker that could disagree with the argmax would be two answers on
      // one readout. (On a 1/f floor the argmax is the band's first bin with
      // an out-of-band higher neighbour and a prominence of 0 — and it is
      // still the marker, on both sides of this application.)
      accepted.push({ bin: k, prominence });
      strongest = levelsDb[k] as number;
      continue;
    }
    // Candidates arrive strongest first, so the ceiling is the first one.
    if ((levelsDb[k] as number) < strongest - params.maxBelowStrongestDb) {
      break;
    }
    if (accepted.some((p) => Math.abs(p.bin - k) < minSeparationBins)) {
      continue;
    }
    if (prominence < params.prominenceDb) {
      continue;
    }
    accepted.push({ bin: k, prominence });
  }

  return accepted.map(({ bin, prominence }) => {
    const fit = interpolatePeak(levelsDb, bin);
    return {
      hz: (bin + fit.deltaBins) * binWidth,
      db: fit.levelDb,
      bin,
      deltaBins: fit.deltaBins,
      prominenceDb: prominence,
      harmonic: null,
    };
  });
}

/** The same peaks with `harmonic` filled in against `f0Hz`; all `null` when there is no f0. */
export function labelHarmonics(
  peaks: readonly LabelledPeak[],
  f0Hz: number | null,
  toleranceCents: number = DEFAULT_PEAK_PICKER.harmonicToleranceCents,
): LabelledPeak[] {
  if (f0Hz === null || !(f0Hz > 0)) {
    return peaks.map((p) => ({ ...p, harmonic: null }));
  }
  return peaks.map((p) => {
    const n = Math.round(p.hz / f0Hz);
    if (n < 1) {
      return { ...p, harmonic: null };
    }
    const off = Math.abs(cents(p.hz, n * f0Hz));
    return { ...p, harmonic: off <= toleranceCents ? n : null };
  });
}
