//
// What a file SAYS it is, read from its own header — before the browser
// decodes it and stops being able to tell us.
//
// WHY THIS EXISTS. The playback source of ADR 0021 7(c)'s second note hands a
// file to `decodeAudioData`, which returns an `AudioBuffer` at the decoding
// context's rate with the channel count it chose. By then the file's OWN rate
// and channel count are gone, and those are exactly the two numbers the
// declaration needs: "the file runs at 44100 Hz and this AudioContext at
// 32000 Hz, so the browser resampled it" is a sentence about a stage, and a
// stage nobody can name is a stage nobody declared. So the bytes are read
// first, here, by a parser that describes and never refuses.
//
// IT DESCRIBES; `wav.ts` REFUSES. A 24-bit stereo WAV is a perfectly good
// thing to sing along to and a perfectly bad golden input: the reader that
// feeds the oracle refuses it, and this one reports it. Both walk the same
// RIFF chunks (`readRiffLayout`), because two implementations of "where is the
// fmt chunk" is how a probe comes to report a rate the reader read otherwise.
//
// IT NEVER THROWS. An unreadable header is a fact to display, not a failure:
// the file may still decode perfectly (FLAC, OGG, an MP3 whose sync this
// scanner missed), and refusing to play it because we could not describe it
// would be the tail wagging the dog. `container: 'unknown'` with nulls, and
// the panel says "the header could not be read" — which is the honest thing to
// put beside a decode that then worked.
//
// THE MP3 SIDE IS A FRAME HEADER AND NOTHING MORE. Four bytes: sync, version,
// layer, rate index, channel mode. No Xing walk, no duration — a VBR file's
// duration is not in its first frame, the decoded buffer's duration is exact
// and free, and a number this module guessed would be a second answer to a
// question already answered. ID3v2 is skipped by its syncsafe length because
// tag bytes contain `FF Ex` patterns often enough to matter: an album-art JPEG
// is full of them, and a scanner that started at byte 0 would report the rate
// of a picture.
// ----------------------------------------------------------------------------

import { readRiffLayout } from './wav';

export type AudioContainer = 'wav' | 'mp3' | 'unknown';

export interface AudioProbe {
  readonly container: AudioContainer;
  /** The file's OWN rate, before any decode. `null` when the header did not say. */
  readonly sampleRateHz: number | null;
  readonly channels: number | null;
  /** WAV only, from the data chunk. MP3 duration is the decoded buffer's, not a guess. */
  readonly durationS: number | null;
  /** One line for the panel: "MPEG-1 Layer III, joint stereo, 44100 Hz". */
  readonly summary: string;
}

const UNKNOWN: AudioProbe = Object.freeze({
  container: 'unknown',
  sampleRateHz: null,
  channels: null,
  durationS: null,
  summary: 'container not recognised — the browser decoded it anyway',
});

/** `WAVE_FORMAT_PCM` / `IEEE_FLOAT` / `EXTENSIBLE`, named so the summary is readable. */
const WAVE_FORMATS: Readonly<Record<number, string>> = Object.freeze({
  0x0001: 'PCM',
  0x0003: 'IEEE float',
  0x0006: 'A-law',
  0x0007: 'µ-law',
  0xfffe: 'extensible',
});

/** MPEG audio version bits → the rate table it indexes. Index 1 is reserved. */
const MPEG_RATES: Readonly<Record<number, readonly number[]>> = Object.freeze({
  3: [44100, 48000, 32000], // MPEG-1
  2: [22050, 24000, 16000], // MPEG-2
  0: [11025, 12000, 8000], // MPEG-2.5
});

const MPEG_VERSION_NAMES: Readonly<Record<number, string>> = Object.freeze({
  3: 'MPEG-1',
  2: 'MPEG-2',
  0: 'MPEG-2.5',
});

const LAYER_NAMES: Readonly<Record<number, string>> = Object.freeze({
  3: 'Layer I',
  2: 'Layer II',
  1: 'Layer III',
});

const CHANNEL_MODE_NAMES: readonly string[] = ['stereo', 'joint stereo', 'dual mono', 'mono'];

/**
 * The length of an ID3v2 tag at the start of `bytes`, or 0 when there is none.
 *
 * The size is SYNCSAFE — seven bits per byte — precisely so that a tag can
 * never contain a byte sequence that looks like a frame sync. Reading it as a
 * plain big-endian integer overshoots by up to 12 % and lands the scanner in
 * the middle of the audio.
 */
export function id3v2Length(bytes: Uint8Array): number {
  if (bytes.length < 10) {
    return 0;
  }
  if (bytes[0] !== 0x49 || bytes[1] !== 0x44 || bytes[2] !== 0x33) {
    return 0; // not "ID3"
  }
  const flags = bytes[5] as number;
  const size =
    (((bytes[6] as number) & 0x7f) << 21) |
    (((bytes[7] as number) & 0x7f) << 14) |
    (((bytes[8] as number) & 0x7f) << 7) |
    ((bytes[9] as number) & 0x7f);
  // Bit 4 of the flags is a footer, ten more bytes at the end of the tag.
  return 10 + size + ((flags & 0x10) !== 0 ? 10 : 0);
}

/**
 * The offset of the first plausible MPEG audio frame header at or after
 * `from`, or −1. "Plausible" excludes the reserved encodings, because a random
 * `FF Ex` in a tag or a picture will usually hit one of them.
 */
export function findMp3FrameSync(bytes: Uint8Array, from: number): number {
  const limit = Math.min(bytes.length - 4, from + 65_536);
  for (let i = Math.max(0, from); i <= limit; i += 1) {
    if ((bytes[i] as number) !== 0xff || (((bytes[i + 1] as number) & 0xe0) !== 0xe0)) {
      continue;
    }
    const b1 = bytes[i + 1] as number;
    const b2 = bytes[i + 2] as number;
    const version = (b1 >> 3) & 0x03;
    const layer = (b1 >> 1) & 0x03;
    const bitrateIndex = (b2 >> 4) & 0x0f;
    const rateIndex = (b2 >> 2) & 0x03;
    if (version === 1 || layer === 0 || rateIndex === 3 || bitrateIndex === 0x0f || bitrateIndex === 0) {
      continue;
    }
    return i;
  }
  return -1;
}

/** A WAV's header as a probe, or `null` when it is not a RIFF/WAVE file at all. */
export function probeWav(bytes: Uint8Array): AudioProbe | null {
  let layout;
  try {
    layout = readRiffLayout(bytes);
  } catch {
    return null;
  }
  const { fmt, dataSize } = layout;
  const bytesPerFrame = (fmt.bitsPerSample / 8) * fmt.channels;
  const durationS =
    bytesPerFrame > 0 && fmt.sampleRate > 0 && dataSize >= 0 ? dataSize / bytesPerFrame / fmt.sampleRate : null;
  const format = WAVE_FORMATS[fmt.audioFormat] ?? `format 0x${fmt.audioFormat.toString(16)}`;
  return {
    container: 'wav',
    sampleRateHz: fmt.sampleRate > 0 ? fmt.sampleRate : null,
    channels: fmt.channels > 0 ? fmt.channels : null,
    durationS: durationS !== null && Number.isFinite(durationS) ? durationS : null,
    summary:
      `RIFF/WAVE, ${format}, ${String(fmt.bitsPerSample)}-bit, ` +
      `${String(fmt.channels)} ch, ${String(fmt.sampleRate)} Hz`,
  };
}

/** An MP3's first frame header as a probe, or `null` when no frame was found. */
export function probeMp3(bytes: Uint8Array): AudioProbe | null {
  const start = findMp3FrameSync(bytes, id3v2Length(bytes));
  if (start < 0) {
    return null;
  }
  const b1 = bytes[start + 1] as number;
  const b2 = bytes[start + 2] as number;
  const b3 = bytes[start + 3] as number;
  const version = (b1 >> 3) & 0x03;
  const layer = (b1 >> 1) & 0x03;
  const rateIndex = (b2 >> 2) & 0x03;
  const mode = (b3 >> 6) & 0x03;
  const rates = MPEG_RATES[version];
  const sampleRateHz = rates?.[rateIndex] ?? null;
  const channels = mode === 3 ? 1 : 2;
  return {
    container: 'mp3',
    sampleRateHz,
    channels,
    // See the header: a VBR file's duration is not in its first frame, and the
    // decoded buffer's is exact.
    durationS: null,
    summary:
      `${MPEG_VERSION_NAMES[version] ?? 'MPEG'} ${LAYER_NAMES[layer] ?? 'unknown layer'}, ` +
      `${CHANNEL_MODE_NAMES[mode] ?? 'unknown mode'}, ` +
      `${sampleRateHz === null ? 'rate not stated' : `${String(sampleRateHz)} Hz`}`,
  };
}

/** Whatever the bytes say they are. Never throws; `'unknown'` is an answer. */
export function probeAudio(bytes: Uint8Array): AudioProbe {
  try {
    return probeWav(bytes) ?? probeMp3(bytes) ?? UNKNOWN;
  } catch {
    // A probe that threw would refuse a file the decoder can read. It cannot.
    return UNKNOWN;
  }
}
