//
// The reference note: capture it, keep it, and say how far the live note is
// from it. Pure — no DOM, no Worker, no canvas; the shell wires it up and the
// renderer draws what this file hands over.
//
// PITCH DECIDES; TIMBRE IS ONLY SHOWN. The owner's brief (2026-08-22) is
// "capture a note and see when I reach it while imitating it", and the
// decision taken with him the same day is that "reached" means ONE thing: the
// live f0 is within a band of the captured f0, in cents. The captured spectrum
// is drawn underneath the live one as a ghost, with its harmonic peaks as
// hollow markers, so that the singer can SEE whether the timbre is close — but
// nothing here scores it. Two reasons. A spectral distance would need the two
// spectra to be comparable in level, and with one uncalibrated microphone
// every level readout is relative and within-session until a calibration
// chain says otherwise (CLAUDE.md tenet 2; ADR 0003): a singer who leans in
// 10 cm would "reach" the timbre without changing a thing about the voice.
// And "have I reached the note" is, in plain words, a question about pitch;
// answering a different question with the same green tick would make the
// instrument lie in the direction that flatters. So the match state below is
// a function of two frequencies and nothing else, and the rule is written in
// one place (`matchState`) that the page never re-derives.
//
// THE HOLD IS A MEDIAN, NOT A MEAN, AND NOT THE LAST FRAME. A note held for
// half a second arrives as `holdFrames` f0 readings, of which the first few
// are the onset (scoop, breath, the estimator locking) and any one of them can
// be an octave slip — MPM's first-key-maximum rule guards the octave but does
// not make it impossible. The median of the voiced readings ignores a single
// slip entirely, and the median absolute deviation about it, in cents, is
// reported as `f0SpreadCents` so that the display can say how steady the
// captured note actually was rather than pretending it was a line. The
// voiced-fraction and clarity gates refuse a capture that is mostly breath or
// noise — the reference has to BE a note before anything can be compared to
// it, and a refusal carries its numbers so the hint under the button can say
// why.
//
// THE SPECTRUM IS AVERAGED IN LINEAR POWER, FROM THE RAW COLUMNS. ADR 0006 D8:
// averaging happens in PS/PSD, never in dB — the log-domain mean of a
// noise-like bin is biased low by ≈ 2.5 dB (derived in that record, Heinzel
// §10 for the rule). And it is the RAW column, not the display column: a block
// mean of `holdFrames` raw periodograms is a defined estimator (Bartlett's,
// with the preset's overlap), whereas a mean of the Worker's EMA outputs is an
// average of averages with a time constant nobody wrote down. The Worker
// already sends both columns for exactly this reason — "a residual measured
// against the oracle is a statement about one frame". The averaging is done
// here, on the main thread, on capture: it is a one-off over 25 columns, not a
// per-hop job, and it keeps the Worker's contract to "one frame in, one frame
// out". The −200 dB floor (ADR 0006 D3) survives the round trip: 10^(−20) is
// representable, its mean is itself, and `10·log10` of it is −200 again — the
// unit test pins that exactly, because a floor that came back as −199.9 would
// put a visible shelf under the ghost trace.
//
// A MISMATCHED PRESET IS A WARNING, NOT A REFUSAL. The reference is captured
// under one preset and may be compared under another. Pitch is a property of
// the voice: the f0 estimator reads the time domain with the same parameters
// whatever the FFT size, so a live f0 under `vowel_formant_study` is directly
// comparable to a reference captured under `live_singing`. The spectrum is
// NOT: N, window, scaling (dBFS vs dBFS/Hz) and the display band are all the
// preset's, and a 4096-point power-spectrum ghost under an 8192-point
// spectral-density trace is two conventions on one axis (ADR 0006 D2/D4).
// `compatibility` therefore says "pitch compared, spectrum not shown" and the
// view withholds the ghost; refusing the comparison outright would throw away
// the half that is valid to keep the half that is not. The preset's sha256
// is kept next to its id because decision 7(a) of ADR 0021 makes the served
// file the single source of truth — same id, different bytes, is a different
// preset.
//
// THE STORAGE KEY IS `superspectral.reference.v1`. The same reason as
// `theme.ts`: this page is also served inside an iframe on alexander-gomez.com,
// where al-folio owns the origin's bare keys, so everything this application
// persists is namespaced under `superspectral.`. The `.v1` suffix is the
// FORMAT version, and it appears twice on purpose — in the key, so that a
// future format can live beside the old one and migrate it rather than
// clobber it, and in the payload (`version: 1`), so that a v2 blob written
// under a v1 key by a newer build is refused as `version` rather than parsed
// as corrupt. Every storage call is wrapped: third-party storage inside that
// iframe throws, Safari's private mode throws, and the reference still has to
// work for the page view that captured it — `save()` returning `false` is
// what lets the shell say "kept for this page only".
//
// ALL THE NUMBERS ARE `(prov.)`. They are in one frozen object, each with the
// reason it is what it is, and the page displays them with their tag. The
// in-tune and near bands are anchored to the RPA @ 10 / 25 cents tiers the
// validation README already carries (the CREPE-tier 10 cents and the MIREX
// 25), not to musical practice — W3 says anything that is taste or perception
// is the owner's to change, and it is one constant when he does.
// ---------------------------------------------------------------------------

import { cents, noteName, type NoteName } from '../dsp/cents';
import { CLARITY_THRESHOLD, type F0Estimate } from '../dsp/mpm';
import { DEFAULT_PEAK_PICKER, labelHarmonics, pickPeaks, type LabelledPeak, type PeakPickerParams } from '../dsp/peaks';
import type { FrameMessage } from '../worker/protocol';

/* --- constants ------------------------------------------------------------- */

export interface ReferenceConstants {
  /** Frames in the hold — the LAST this many the session has seen. */
  readonly holdFrames: number;
  /** Fraction of the hold that must be voiced for a capture to be a note. */
  readonly minVoicedFraction: number;
  /** The median clarity over the voiced frames must reach this. */
  readonly minClarity: number;
  /** |cents| ≤ this is "in tune". */
  readonly inTuneCents: number;
  /** |cents| ≤ this is "near"; beyond it is "far". */
  readonly nearCents: number;
  /** The cents bar runs −barSpanCents … +barSpanCents. */
  readonly barSpanCents: number;
}

export const REFERENCE_CONSTANTS: ReferenceConstants = Object.freeze({
  // 25 frames is 0.5 s at the live_singing preset's 50 Hz hop (32 000 / 640).
  // Long enough that a median can outvote an onset and one octave slip, short
  // enough that "hold the note" is a thing a singer does without thinking. It
  // is a frame count rather than a duration so that the rule is the same
  // under every preset; under sustained_pitch_lab (25 Hz) it is a second.
  // `(prov.)`
  holdFrames: 25,
  // Four unvoiced frames in 25 is one breath or one onset; more than that and
  // the hold was not a held note. `(prov.)`
  minVoicedFraction: 0.8,
  // The Worker's own voicing threshold: a frame it called voiced already
  // clears this, so the gate is reachable only from a frame producer with a
  // lower bar (a test, a future estimator, a stored reference from another
  // build). It is the same constant so the two can never drift apart. `(prov.)`
  minClarity: CLARITY_THRESHOLD,
  // The RPA @ 10 cents tier of docs/validation/README.md — the CREPE-tier
  // figure that the project's own ±20-cent acoustic bound is measured
  // against. `(prov.)` — the owner may tighten it; it is one number.
  inTuneCents: 10,
  // The RPA @ 25 cents tier of the same table (the MIREX convention's middle
  // step). Between in-tune and near the direction is shown; beyond near the
  // singer is on a different note. `(prov.)`
  nearCents: 25,
  // The bar's half-width: the 50-cent RPA threshold, beyond which the nearest
  // note is a different one and a needle would point off the scale. `(prov.)`
  barSpanCents: 50,
});

export const REFERENCE_STORAGE_KEY = 'superspectral.reference.v1';

/* --- the tolerance, and why it is the singer's to set ----------------------- */

/**
 * How far off is still "in tune", in cents.
 *
 * Every tuner a musician actually uses exposes this. Tunable calls it a level
 * — "at the beginner level, a note within 10 cents will display as in tune,
 * while at the advanced level, notes must be within two cents" — and Pano
 * Tuner ships it as an adjustable tolerance. A fixed band is a judgement about
 * the player, made by the instrument.
 *
 * Three choices, each a tier the validation plan already names (RPA @ 10 / 25
 * cents; 5 is the "vs Praat" row's ≤ 5). All `(prov.)`, all displayed with
 * their tag until an ADR fixes them (routing Q54).
 */
export const TOLERANCE_CHOICES = Object.freeze([5, 10, 25] as const);
export type ToleranceCents = (typeof TOLERANCE_CHOICES)[number];
export const DEFAULT_TOLERANCE: ToleranceCents = 10;
export const TOLERANCE_STORAGE_KEY = 'superspectral.tolerance';

export function parseTolerance(raw: unknown): ToleranceCents {
  const value = typeof raw === 'string' ? Number(raw) : raw;
  return (TOLERANCE_CHOICES as readonly number[]).includes(value as number)
    ? (value as ToleranceCents)
    : DEFAULT_TOLERANCE;
}

/**
 * The "near" band that goes with an in-tune band.
 *
 * NOT a multiplier. The bands are the validation plan's tiers — 10 and 25 are
 * the RPA rows, 50 is the threshold beyond which the nearest note is a
 * different one — so 5 and 10 both sit inside a 25-cent near band, and a
 * 25-cent in-tune band takes 50. A rule like `max(2.5·c, 25)` would put near
 * at 62.5 cents, which is off the bar and on no tier anyone has written down.
 */
export function nearCentsFor(inTuneCents: ToleranceCents): 25 | 50 {
  return inTuneCents === 25 ? 50 : 25;
}

/**
 * The constants with a different in-tune band. `barSpanCents` never moves: the
 * needle's scale must not change under the singer when they change the band.
 */
export function withTolerance(
  base: ReferenceConstants,
  inTuneCents: ToleranceCents,
): ReferenceConstants {
  return Object.freeze({ ...base, inTuneCents, nearCents: nearCentsFor(inTuneCents) });
}

/** The lane the singer aims into, in Hz. `ref · 2^(±cents/1200)`. */
export interface Lane {
  readonly centreHz: number;
  readonly inTuneHz: readonly [number, number];
  readonly nearHz: readonly [number, number];
  readonly inTuneCents: number;
  readonly nearCents: number;
  /** "A3 · 220.0 Hz" — drawn in the pane's gutter. */
  readonly label: string;
}

export function laneHz(referenceHz: number, constants: ReferenceConstants): Lane {
  if (!(referenceHz > 0) || !Number.isFinite(referenceHz)) {
    throw new RangeError(`a lane needs a positive reference frequency, got ${String(referenceHz)}`);
  }
  const edges = (cents: number): readonly [number, number] => [
    referenceHz * 2 ** (-cents / 1200),
    referenceHz * 2 ** (cents / 1200),
  ];
  const note = noteName(referenceHz);
  return {
    centreHz: referenceHz,
    inTuneHz: edges(constants.inTuneCents),
    nearHz: edges(constants.nearCents),
    inTuneCents: constants.inTuneCents,
    nearCents: constants.nearCents,
    label: `${note === null ? '—' : `${note.name}${String(note.octave)}`} · ${referenceHz.toFixed(1)} Hz`,
  };
}

/* --- needle damping --------------------------------------------------------- */

/**
 * The needle's time constant, seconds. `(prov.)`
 *
 * An undamped needle at 50 hops a second is unreadable: it is the frame-to-frame
 * jitter of the estimator, not the pitch. Both Cleartune and Pano Tuner ship
 * damping as a named feature ("the needle now holds firmly on the note as it
 * rings and fades, instead of drifting or jumping"). 100 ms reaches 63 % of a
 * correction in five hops and 95 % in fifteen — a third of a second — which is
 * faster than a singer can act on it and slower than the jitter.
 */
export const NEEDLE_TAU_S = 0.1;

/** The one-pole coefficient for a hop of `hopS` seconds: `1 − e^(−hop/τ)`. */
export function dampingAlpha(hopS: number, tauS: number = NEEDLE_TAU_S): number {
  if (!(hopS > 0) || !(tauS > 0) || !Number.isFinite(hopS) || !Number.isFinite(tauS)) {
    throw new RangeError(`damping needs positive finite times, got hop ${String(hopS)}, tau ${String(tauS)}`);
  }
  return 1 - Math.exp(-hopS / tauS);
}

/**
 * One damping step. `previous === null` (a fresh needle, or the frame after an
 * unvoiced one) passes the value through: the needle appears where the pitch
 * is, never sliding in from a stale position.
 *
 * THE NEEDLE ONLY. The match state, the cents text and the pitch trace are all
 * undamped — a singer who is 12 cents flat must be told so at once, and a
 * vibrato must read as a wiggle rather than as a smear.
 */
export function dampCents(previous: number | null, next: number, alpha: number): number {
  if (!(alpha > 0) || alpha > 1 || !Number.isFinite(alpha)) {
    throw new RangeError(`damping alpha must be in (0, 1], got ${String(alpha)}`);
  }
  return previous === null || !Number.isFinite(previous) ? next : previous + alpha * (next - previous);
}

export interface ToleranceStore {
  load(): ToleranceCents;
  save(tolerance: ToleranceCents): boolean;
}

/** The same try/catch discipline as the reference store: a third-party iframe throws. */
export function createToleranceStore(getStorage: () => Storage = () => window.localStorage): ToleranceStore {
  return {
    load: () => {
      try {
        return parseTolerance(getStorage().getItem(TOLERANCE_STORAGE_KEY));
      } catch {
        return DEFAULT_TOLERANCE;
      }
    },
    save: (tolerance) => {
      try {
        getStorage().setItem(TOLERANCE_STORAGE_KEY, String(tolerance));
        return true;
      } catch {
        return false;
      }
    },
  };
}

/* --- types ----------------------------------------------------------------- */

/**
 * What this file reads of a frame — a structural subset of `FrameMessage`,
 * so the unit tests can build one without the Worker and so that a frame
 * mirrored through the debug surface (plain arrays) still fits.
 */
export type ReferenceFrame = Pick<FrameMessage, 'frequencyHz' | 'rawLevelDb' | 'levelUnit' | 'f0' | 'peaks' | 'enbwHz'>;

/** The preset facts a capture needs. `LivePreset` + its digest satisfies it structurally. */
export interface ReferencePreset {
  readonly id: string;
  readonly sha256: string;
  readonly sampleRateHz: number;
  readonly fftSize: number;
  readonly freqMinHz: number;
  readonly freqMaxHz: number;
}

/** The two fields `compatibility` reads. */
export type PresetIdentity = Pick<ReferencePreset, 'id' | 'sha256'>;

/**
 * A captured (or injected) reference note. Plain JSON data throughout —
 * number arrays, not typed arrays — so that it round-trips through
 * `JSON.stringify`, `structuredClone` and `page.evaluate()` unchanged.
 */
export interface Reference {
  readonly version: 1;
  /**
   * Where the pitch came from.
   *
   * `capture` — measured from held frames of a live source.
   * `synthetic` — typed by the singer or injected by a test; shown "(set, not sung)".
   * `derived` — measured from held frames of a STRETCHED source; shown
   *   "(from stretch, not sung)". The owner's decision, 2026-08-23 (ADR 0023
   *   decision 4): a drone is a held note, which is the one thing the capture
   *   gate was written for, so refusing it would make the singer type what the
   *   instrument has just measured. The label is what says that the spread and
   *   the hold beside it describe a phase-randomised band ≈ 16 Hz wide rather
   *   than a voice.
   *
   * Widening this enum does NOT bump the format: `version` stays 1 and the key
   * stays `superspectral.reference.v1`. An older build meeting a `derived`
   * blob refuses it as `malformed` and shows *no reference*, which fails safe
   * — the failure mode a version bump would have bought is the one we already
   * have.
   */
  readonly source: 'capture' | 'synthetic' | 'derived';
  /** Present only on a `derived` reference: what it was measured through. */
  readonly provenance?: DerivedReferenceProvenance;
  /** ISO 8601, from the capturing page's clock. */
  readonly capturedAt: string;
  readonly presetId: string;
  readonly presetSha256: string;
  /** Median of the voiced f0 readings over the hold, Hz. */
  readonly f0Hz: number;
  /** Median clarity over the voiced frames. 1 for a synthetic reference. */
  readonly clarity: number;
  /** Voiced frames / hold frames. 1 for a synthetic reference. */
  readonly voicedFraction: number;
  /** Median absolute deviation of the voiced f0 about its median, cents. 0 for a synthetic reference. */
  readonly f0SpreadCents: number;
  /** How many frames were averaged. 0 for a synthetic reference. */
  readonly holdFrames: number;
  readonly note: NoteName | null;
  /** The averaged spectrum's peaks, harmonic-labelled against `f0Hz`. `[]` for a synthetic reference. */
  readonly peaks: readonly LabelledPeak[];
  /** The bin grid of `levelDb`. `[]` for a synthetic reference. */
  readonly frequencyHz: readonly number[];
  /** The hold's RAW columns averaged in linear power, in `levelUnit`. `[]` for a synthetic reference. */
  readonly levelDb: readonly number[];
  readonly levelUnit: 'dBFS' | 'dBFS/Hz';
}

/** The facts a `derived` reference carries about the render it was measured on. */
export interface DerivedReferenceProvenance {
  readonly kind: 'stretch';
  readonly stretch: number;
  readonly sourceName: string;
}

export interface Refusal<Reason extends string> {
  readonly refused: true;
  readonly reason: Reason;
  /** A sentence with the numbers in it, for the hint under the control. */
  readonly message: string;
}

export type CaptureRefusal = Refusal<'too-short' | 'unvoiced' | 'low-clarity'>;
export type CaptureResult = Reference | CaptureRefusal;

export type DeserializeRefusal = Refusal<'malformed' | 'version'>;
export type DeserializeResult = Reference | DeserializeRefusal;

export function isRefusal<R extends string>(value: Reference | Refusal<R>): value is Refusal<R> {
  return (value as Refusal<R>).refused === true;
}

/** What the capture button shows: the gate's verdict and the numbers behind it. */
export interface CaptureReadiness {
  readonly ready: boolean;
  /** `null` when ready. */
  readonly refusal: CaptureRefusal | null;
  /** `min(frames.length, holdFrames)`. */
  readonly framesHeld: number;
  readonly voicedFrames: number;
  readonly voicedFraction: number;
  /** Over the voiced frames; 0 when there are none. */
  readonly medianClarity: number;
}

export type MatchBand = 'in' | 'near' | 'far';

export interface MatchState {
  readonly state: MatchBand | 'unvoiced';
  /** Live relative to reference; `null` when unvoiced. */
  readonly cents: number | null;
  /** `null` when unvoiced or exactly on the reference. */
  readonly direction: 'flat' | 'sharp' | null;
  readonly liveHz: number | null;
  readonly referenceHz: number;
}

export interface Compatibility {
  readonly comparable: boolean;
  /** The warning, or `null` when comparable. */
  readonly message: string | null;
}

export interface CaptureOptions {
  /** The timestamp to record; defaults to now. Injected by tests for a deterministic record. */
  readonly capturedAt?: string;
  /** The picker for the averaged column; defaults to the Worker's own parameters. */
  readonly picker?: PeakPickerParams;
  /**
   * Set when the session's source is a stretched render: the capture is then
   * `source: 'derived'` and carries this block. Absent for a microphone or a
   * raw file, where a capture is exactly what it has always been.
   */
  readonly derivedFrom?: DerivedReferenceProvenance;
}

/* --- small statistics -------------------------------------------------------- */

/** The median of a non-empty list: the middle value, or the mean of the two middle values. */
export function median(values: readonly number[]): number {
  if (values.length === 0) {
    throw new RangeError('median of an empty list');
  }
  const sorted = [...values].sort((a, b) => a - b);
  const mid = sorted.length >>> 1;
  return sorted.length % 2 === 1
    ? (sorted[mid] as number)
    : ((sorted[mid - 1] as number) + (sorted[mid] as number)) / 2;
}

/**
 * The mean of several dB columns taken in LINEAR power, returned in dB.
 * ADR 0006 D8; see the header. Every column must have the same length.
 */
export function averageLevelDb(columns: readonly ArrayLike<number>[]): number[] {
  if (columns.length === 0) {
    throw new RangeError('averageLevelDb needs at least one column');
  }
  const bins = (columns[0] as ArrayLike<number>).length;
  const acc = new Float64Array(bins);
  for (const column of columns) {
    if (column.length !== bins) {
      throw new RangeError(`columns of ${String(bins)} and ${String(column.length)} bins cannot be averaged`);
    }
    for (let k = 0; k < bins; k += 1) {
      acc[k] = (acc[k] as number) + Math.pow(10, (column[k] as number) / 10);
    }
  }
  const out = new Array<number>(bins);
  for (let k = 0; k < bins; k += 1) {
    out[k] = 10 * Math.log10((acc[k] as number) / columns.length);
  }
  return out;
}

/**
 * A reference is plain JSON data, and JSON has no −0: `interpolatePeak` on a
 * symmetric lobe returns `d = 0.5·0/denominator = −0`, which `JSON.stringify`
 * writes as `0`, so a reference would deep-compare unequal to itself after a
 * round trip. `+ 0` turns −0 into +0 and leaves every other number alone.
 */
function withoutNegativeZero(peak: LabelledPeak): LabelledPeak {
  return { ...peak, hz: peak.hz + 0, db: peak.db + 0, deltaBins: peak.deltaBins + 0, prominenceDb: peak.prominenceDb + 0 };
}

function isVoiced(frame: ReferenceFrame): frame is ReferenceFrame & { f0: F0Estimate & { f0Hz: number } } {
  return frame.f0 !== null && frame.f0.f0Hz !== null;
}

function percent(fraction: number): string {
  return `${String(Math.round(fraction * 100))} %`;
}

/* --- capture --------------------------------------------------------------- */

/**
 * The gate, with its numbers. The button is enabled iff `ready`; the hint
 * shows `refusal.message` otherwise. `captureReference` applies exactly this
 * rule — it calls this function — so the button can never enable a capture
 * that would then be refused.
 */
export function captureReadiness(
  frames: readonly ReferenceFrame[],
  constants: ReferenceConstants = REFERENCE_CONSTANTS,
): CaptureReadiness {
  const { holdFrames } = constants;
  const hold = frames.slice(-holdFrames);
  const voiced = hold.filter(isVoiced);
  const voicedFraction = hold.length === 0 ? 0 : voiced.length / hold.length;
  const medianClarity = voiced.length === 0 ? 0 : median(voiced.map((f) => f.f0.clarity));
  const base = {
    framesHeld: hold.length,
    voicedFrames: voiced.length,
    voicedFraction,
    medianClarity,
  };

  if (hold.length < holdFrames) {
    return {
      ...base,
      ready: false,
      refusal: {
        refused: true,
        reason: 'too-short',
        message: `${String(hold.length)} of ${String(holdFrames)} frames held; capture needs the last ${String(holdFrames)}`,
      },
    };
  }
  if (voicedFraction < constants.minVoicedFraction) {
    const estimatorOff = hold.every((f) => f.f0 === null);
    const message =
      `${String(voiced.length)} of ${String(hold.length)} frames voiced (${percent(voicedFraction)}); ` +
      `capture needs ≥ ${percent(constants.minVoicedFraction)}` +
      (estimatorOff ? ' — the f0 estimator is off for this preset (no f0 overlay)' : '');
    return { ...base, ready: false, refusal: { refused: true, reason: 'unvoiced', message } };
  }
  if (medianClarity < constants.minClarity) {
    return {
      ...base,
      ready: false,
      refusal: {
        refused: true,
        reason: 'low-clarity',
        message:
          `median clarity ${medianClarity.toFixed(2)} over ${String(voiced.length)} voiced frames; ` +
          `capture needs ≥ ${constants.minClarity.toFixed(2)}`,
      },
    };
  }
  return { ...base, ready: true, refusal: null };
}

/**
 * Capture a reference from the LAST `holdFrames` of `frames`, or refuse with
 * the numbers. See the header for each rule.
 */
export function captureReference(
  frames: readonly ReferenceFrame[],
  preset: ReferencePreset,
  options: CaptureOptions = {},
  constants: ReferenceConstants = REFERENCE_CONSTANTS,
): CaptureResult {
  const readiness = captureReadiness(frames, constants);
  if (readiness.refusal !== null) {
    return readiness.refusal;
  }
  const hold = frames.slice(-constants.holdFrames);
  const voiced = hold.filter(isVoiced);
  const last = hold[hold.length - 1] as ReferenceFrame;

  const f0Hz = median(voiced.map((f) => f.f0.f0Hz));
  const f0SpreadCents = median(voiced.map((f) => Math.abs(cents(f.f0.f0Hz, f0Hz))));

  const levelDb = averageLevelDb(hold.map((f) => f.rawLevelDb));
  const picker = options.picker ?? DEFAULT_PEAK_PICKER;
  const peaks = labelHarmonics(
    pickPeaks(levelDb, preset.sampleRateHz, preset.fftSize, last.enbwHz, picker, preset.freqMinHz, preset.freqMaxHz),
    f0Hz,
    picker.harmonicToleranceCents,
  ).map(withoutNegativeZero);

  return {
    version: 1,
    source: options.derivedFrom === undefined ? 'capture' : 'derived',
    ...(options.derivedFrom === undefined ? {} : { provenance: options.derivedFrom }),
    capturedAt: options.capturedAt ?? new Date().toISOString(),
    presetId: preset.id,
    presetSha256: preset.sha256,
    f0Hz,
    clarity: readiness.medianClarity,
    voicedFraction: readiness.voicedFraction,
    f0SpreadCents,
    holdFrames: hold.length,
    note: noteName(f0Hz),
    peaks,
    frequencyHz: Array.from(last.frequencyHz),
    levelDb,
    levelUnit: last.levelUnit,
  };
}

/**
 * A reference with a pitch and no spectrum.
 *
 * Two callers, one state. A test injects one through the debug surface's
 * `setReferenceF0(hz)` to pin the band edges against a known tone without
 * singing; a SINGER types one ("G4", "392 Hz") because a song never holds a
 * note for the 25 frames a capture needs — the note is then a target rather
 * than a measurement. Both are shown "(set, not sung)" and both leave the
 * ghost empty, which is the honest display of a pitch with no spectrum
 * behind it.
 */
export function syntheticReference(
  f0Hz: number,
  preset: PresetIdentity,
  options: CaptureOptions & { readonly levelUnit?: 'dBFS' | 'dBFS/Hz' } = {},
): Reference {
  if (!(f0Hz > 0) || !Number.isFinite(f0Hz)) {
    throw new RangeError(`a reference needs a positive finite f0, got ${String(f0Hz)}`);
  }
  return {
    version: 1,
    source: 'synthetic',
    capturedAt: options.capturedAt ?? new Date().toISOString(),
    presetId: preset.id,
    presetSha256: preset.sha256,
    f0Hz,
    clarity: 1,
    voicedFraction: 1,
    f0SpreadCents: 0,
    holdFrames: 0,
    note: noteName(f0Hz),
    peaks: [],
    frequencyHz: [],
    levelDb: [],
    levelUnit: options.levelUnit ?? 'dBFS',
  };
}

/* --- match ----------------------------------------------------------------- */

/**
 * The band a cents offset falls in. Inclusive at the edge: |cents| ≤
 * inTuneCents is `in`, ≤ nearCents is `near`, beyond is `far`. This is the
 * whole rule, on its own so that the edge can be tested EXACTLY — an Hz
 * value whose `cents()` is 10.000 does not exist in double precision (one
 * ULP of 440 Hz is ≈ 4·10⁻¹³ cents and none of the neighbours lands on it),
 * so a test through frequencies can only bracket the edge, never touch it.
 */
export function matchBand(centsOffset: number, constants: ReferenceConstants = REFERENCE_CONSTANTS): MatchBand {
  const magnitude = Math.abs(centsOffset);
  return magnitude <= constants.inTuneCents ? 'in' : magnitude <= constants.nearCents ? 'near' : 'far';
}

/**
 * The match of a live f0 against the reference: `matchBand` of
 * `cents(live, reference)`, with the direction. `null` when there is no
 * reference; `unvoiced` when the live frame has no pitch.
 */
export function matchState(live: F0Estimate | null, reference: Reference, constants?: ReferenceConstants): MatchState;
export function matchState(
  live: F0Estimate | null,
  reference: Reference | null,
  constants?: ReferenceConstants,
): MatchState | null;
export function matchState(
  live: F0Estimate | null,
  reference: Reference | null,
  constants: ReferenceConstants = REFERENCE_CONSTANTS,
): MatchState | null {
  if (reference === null) {
    return null;
  }
  const referenceHz = reference.f0Hz;
  if (live === null || live.f0Hz === null) {
    return { state: 'unvoiced', cents: null, direction: null, liveHz: null, referenceHz };
  }
  const c = cents(live.f0Hz, referenceHz);
  const direction = c > 0 ? 'sharp' : c < 0 ? 'flat' : null;
  return { state: matchBand(c, constants), cents: c, direction, liveHz: live.f0Hz, referenceHz };
}

/**
 * Where the needle goes: `cents / barSpanCents`, clamped to [−1, 1], so the
 * page places it at `centre + fraction·halfWidth` and does no other arithmetic.
 * `null` when there is no needle to draw (no reference, or unvoiced).
 */
export function barFraction(match: MatchState | null, constants: ReferenceConstants = REFERENCE_CONSTANTS): number | null {
  if (match === null || match.cents === null) {
    return null;
  }
  return Math.max(-1, Math.min(1, match.cents / constants.barSpanCents));
}

/** The match cell's text. The word carries the sign; the cents are integers. */
export function describeMatch(match: MatchState | null): string {
  if (match === null) {
    return 'no reference';
  }
  if (match.cents === null) {
    return 'no pitch';
  }
  if (match.state === 'in') {
    return 'in tune';
  }
  // `near`/`far` with a non-zero offset always has a direction: a zero offset
  // is inside every band, so `direction === null` cannot reach this line.
  return `${match.direction ?? 'sharp'} ${String(Math.round(Math.abs(match.cents)))}¢`;
}

/* --- compatibility ----------------------------------------------------------- */

/** A digest's first eight hex characters — enough to tell two presets apart by eye. */
function shortDigest(sha256: string): string {
  return sha256.slice(0, 8);
}

/**
 * Can the reference's SPECTRUM be drawn under this preset's trace? Pitch is
 * always compared; only the ghost is withheld. See the header.
 */
export function compatibility(reference: Reference, preset: PresetIdentity): Compatibility {
  if (reference.presetId !== preset.id) {
    return {
      comparable: false,
      message:
        `reference captured under preset "${reference.presetId}", this session runs "${preset.id}": ` +
        'pitch compared, spectrum not shown',
    };
  }
  if (reference.presetSha256 !== preset.sha256) {
    return {
      comparable: false,
      message:
        `preset "${preset.id}" has changed since the reference was captured ` +
        `(sha256 ${shortDigest(reference.presetSha256)} → ${shortDigest(preset.sha256)}): ` +
        'pitch compared, spectrum not shown',
    };
  }
  return { comparable: true, message: null };
}

/* --- persistence --------------------------------------------------------------- */

export function serialize(reference: Reference): string {
  return JSON.stringify(reference);
}

function malformed(message: string): DeserializeRefusal {
  return { refused: true, reason: 'malformed', message };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function isNumberArray(value: unknown): value is number[] {
  return Array.isArray(value) && value.every(isFiniteNumber);
}

function isLabelledPeak(value: unknown): value is LabelledPeak {
  return (
    isRecord(value) &&
    isFiniteNumber(value['hz']) &&
    isFiniteNumber(value['db']) &&
    Number.isInteger(value['bin']) &&
    isFiniteNumber(value['deltaBins']) &&
    isFiniteNumber(value['prominenceDb']) &&
    (value['harmonic'] === null || Number.isInteger(value['harmonic']))
  );
}

/** A `derived` reference's block, checked field by field like everything else here. */
function isDerivedProvenance(value: unknown): value is DerivedReferenceProvenance {
  return (
    isRecord(value) &&
    value['kind'] === 'stretch' &&
    isFiniteNumber(value['stretch']) &&
    (value['stretch'] as number) > 0 &&
    typeof value['sourceName'] === 'string'
  );
}

function isNoteName(value: unknown): value is NoteName {
  return (
    isRecord(value) &&
    typeof value['name'] === 'string' &&
    Number.isInteger(value['octave']) &&
    Number.isInteger(value['midi']) &&
    isFiniteNumber(value['cents'])
  );
}

/**
 * Read a reference back, refusing anything that is not one. The version is
 * checked FIRST, so that a newer format is reported as `version` and not as
 * a pile of missing fields; everything else is `malformed` with the field
 * named. Nothing is coerced (ADR 0010 decision 7's rule, applied to our own
 * output): a reference that parses with `f0Hz: undefined` would reach
 * `cents()` and throw in the middle of a frame callback.
 */
export function deserialize(text: string): DeserializeResult {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (error) {
    return malformed(`not JSON: ${error instanceof Error ? error.message : String(error)}`);
  }
  if (!isRecord(parsed)) {
    return malformed('expected an object');
  }
  if (parsed['version'] !== 1) {
    return {
      refused: true,
      reason: 'version',
      message: `reference format version ${JSON.stringify(parsed['version'])} is not the 1 this build reads`,
    };
  }
  const checks: readonly [key: string, ok: boolean][] = [
    ['source', parsed['source'] === 'capture' || parsed['source'] === 'synthetic' || parsed['source'] === 'derived'],
    ['provenance', parsed['provenance'] === undefined || isDerivedProvenance(parsed['provenance'])],
    ['capturedAt', typeof parsed['capturedAt'] === 'string'],
    ['presetId', typeof parsed['presetId'] === 'string'],
    ['presetSha256', typeof parsed['presetSha256'] === 'string'],
    ['f0Hz', isFiniteNumber(parsed['f0Hz']) && parsed['f0Hz'] > 0],
    ['clarity', isFiniteNumber(parsed['clarity'])],
    ['voicedFraction', isFiniteNumber(parsed['voicedFraction'])],
    ['f0SpreadCents', isFiniteNumber(parsed['f0SpreadCents'])],
    ['holdFrames', Number.isInteger(parsed['holdFrames'])],
    ['note', parsed['note'] === null || isNoteName(parsed['note'])],
    ['peaks', Array.isArray(parsed['peaks']) && parsed['peaks'].every(isLabelledPeak)],
    ['frequencyHz', isNumberArray(parsed['frequencyHz'])],
    ['levelDb', isNumberArray(parsed['levelDb'])],
    ['levelUnit', parsed['levelUnit'] === 'dBFS' || parsed['levelUnit'] === 'dBFS/Hz'],
  ];
  const failed = checks.find(([, ok]) => !ok);
  if (failed !== undefined) {
    return malformed(`field ${JSON.stringify(failed[0])} is missing or of the wrong shape`);
  }
  const frequencyHz = parsed['frequencyHz'] as number[];
  const levelDb = parsed['levelDb'] as number[];
  if (frequencyHz.length !== levelDb.length) {
    return malformed(
      `frequencyHz has ${String(frequencyHz.length)} bins and levelDb ${String(levelDb.length)}; they must agree`,
    );
  }
  // Rebuilt field by field rather than cast, so that a stray extra key in
  // storage does not come along for the ride.
  return {
    version: 1,
    source: parsed['source'] as Reference['source'],
    // Spread rather than assigned: `exactOptionalPropertyTypes` makes an
    // explicit `undefined` a PRESENT key, and a reference that carried
    // `provenance: undefined` would not deep-equal the one it round-tripped
    // from.
    ...(parsed['provenance'] === undefined
      ? {}
      : { provenance: parsed['provenance'] as DerivedReferenceProvenance }),
    capturedAt: parsed['capturedAt'] as string,
    presetId: parsed['presetId'] as string,
    presetSha256: parsed['presetSha256'] as string,
    f0Hz: parsed['f0Hz'] as number,
    clarity: parsed['clarity'] as number,
    voicedFraction: parsed['voicedFraction'] as number,
    f0SpreadCents: parsed['f0SpreadCents'] as number,
    holdFrames: parsed['holdFrames'] as number,
    note: parsed['note'] as NoteName | null,
    peaks: parsed['peaks'] as LabelledPeak[],
    frequencyHz,
    levelDb,
    levelUnit: parsed['levelUnit'] as Reference['levelUnit'],
  };
}

export interface ReferenceStore {
  /** The stored reference, or `null` when there is none, it is unreadable, or storage threw. */
  load(): Reference | null;
  /** `false` when storage threw — the shell then says "kept for this page only". */
  save(reference: Reference): boolean;
  /** `false` when storage threw. */
  clear(): boolean;
}

/**
 * The store, over a Storage GETTER rather than a Storage: `window.localStorage`
 * itself is the expression that throws when third-party storage is blocked,
 * so it has to be evaluated inside the try.
 */
export function createReferenceStore(getStorage: () => Storage = () => window.localStorage): ReferenceStore {
  return {
    load: () => {
      try {
        const text = getStorage().getItem(REFERENCE_STORAGE_KEY);
        if (text === null) {
          return null;
        }
        const result = deserialize(text);
        return isRefusal(result) ? null : result;
      } catch {
        return null;
      }
    },
    save: (reference) => {
      try {
        getStorage().setItem(REFERENCE_STORAGE_KEY, serialize(reference));
        return true;
      } catch {
        return false;
      }
    },
    clear: () => {
      try {
        getStorage().removeItem(REFERENCE_STORAGE_KEY);
        return true;
      } catch {
        return false;
      }
    },
  };
}
