//
// The f0 history, in step with the spectrogram's rows.
//
// The overlay and the pitch strip both draw the pitch of the last few seconds,
// and both must line it up with the spectrogram row it came from. The trap is
// two counters: a ring with a head of its own drifts from the texture's head
// the first time a frame is dropped, and the trace then sits a row or two off
// the harmonics it belongs to — visible only as a slight lag, never as an error.
//
// So there is ONE head, it lives in `waterfall-view.ts` because that is the GPU
// write position, and `push` there returns the row it wrote. The session hands
// that row to this ring in the same message handler. This ring has no counter;
// it is told where it is.
//
// Unvoiced is `NaN` in the store and `null` at the boundary: a gap in a pitch
// trace is not a zero, and a zero read as a frequency is the mistake
// `golden-files.md` warns about on the Praat side.
// ---------------------------------------------------------------------------

export interface TraceRing {
  readonly rows: number;
  /** Record `hz` (or `null` for unvoiced) at the spectrogram row `row`. */
  push(row: number, hz: number | null): void;
  /** The value `age` rows back from the newest, or `null`. */
  at(age: number): number | null;
  /** The row of the most recent push, or `null` before the first. */
  readonly newestRow: number | null;
  /** How many rows have been written, capped at `rows`. */
  readonly held: number;
  /** How many of those carry a frequency. */
  readonly voiced: number;
}

export function createTraceRing(rows: number): TraceRing {
  if (!Number.isInteger(rows) || rows < 2) {
    throw new RangeError(`a trace ring needs at least 2 rows, got ${String(rows)}`);
  }
  const store = new Float64Array(rows).fill(Number.NaN);
  let newest: number | null = null;
  let pushes = 0;
  let voiced = 0;

  return {
    rows,
    push: (row, hz) => {
      if (!Number.isInteger(row) || row < 0 || row >= rows) {
        throw new RangeError(`row ${String(row)} is outside a ${String(rows)}-row ring`);
      }
      // The slot being overwritten stops counting toward `voiced`. Rows arrive
      // in sequence from the spectrogram, so this only fires after a full lap.
      if (!Number.isNaN(store[row] as number)) {
        voiced -= 1;
      }
      const value = hz === null || !Number.isFinite(hz) || hz <= 0 ? Number.NaN : hz;
      store[row] = value;
      if (!Number.isNaN(value)) {
        voiced += 1;
      }
      newest = row;
      pushes += 1;
    },
    at: (age) => {
      if (newest === null || !Number.isInteger(age) || age < 0 || age >= Math.min(pushes, rows)) {
        return null;
      }
      const value = store[(((newest - age) % rows) + rows) % rows] as number;
      return Number.isNaN(value) ? null : value;
    },
    get newestRow() {
      return newest;
    },
    get held() {
      return Math.min(pushes, rows);
    },
    get voiced() {
      return voiced;
    },
  };
}
