//
// Extreme time-stretch: a short sung phrase held as a long drone, at the same
// pitch, to sing along to (ADR 0023).
//
// PROVENANCE, AND WHAT IS OWED. The algorithm is the Paulstretch family, by
// **Nasca Octavian Paul**, Targu Mures, Romania —
// https://github.com/paulnasca/paulstretch_python — whose `README:17` reads
// "The Paulstretch algorithm is released under Public Domain" and whose every
// source file repeats it. Public domain owes no licence notice; it is still
// owed attribution, and this paragraph is it (bibliography 06 #67). What is
// taken is the mathematics of five expressions — the window, the input hop,
// the phase draw, the double windowing and the 50 % overlap-add — re-derived
// here rather than transcribed, which is the house habit for an algorithm
// (ADR 0004 item 5). The author's later C++ (06 #68) is **GPL-2.0-only** and
// therefore uncopyable even into this GPL-3.0-or-later tree: two of its
// BEHAVIOURS are reproduced below (zeroing DC and Nyquist, a deterministic
// phase stream) and no expression from it appears anywhere in this repository.
//
// WHY THE PITCH SURVIVES. Only the phases are replaced. Each frame keeps its
// |X| bin for bin, so the harmonic comb f₀, 2f₀, 3f₀ … and the formant
// envelope that makes the vowel are untouched; what is destroyed is the
// relative phase between partials, which is the waveform's shape inside the
// window and carries the timing rather than the pitch. Consecutive output
// frames are therefore mutually INCOHERENT, and that one fact drives
// everything else here: they add in power, so the window must be
// power-complementary (`stretch-window.ts`), the makeup gain is 1/√mean(w²),
// and the output is noise-like with a crest factor near 5σ rather than a
// waveform with a predictable peak.
//
// FOUR DEPARTURES FROM THE REFERENCE, each deliberate and each in ADR 0023 D7:
//
//   1. THE LOOP IS READ CIRCULARLY. The reference stretches a FILE, and its
//      output ends in a fade-out `N·S` samples long — two seconds at 8×, five
//      at 20×. We stretch a LOOP, and that fade would wrap round to meet the
//      reference's `N/2` fade-in at every repeat. Reading `x[(i+j) mod L]` and
//      priming the overlap from the step before zero makes the output
//      circularly continuous instead, which is the whole point of a drone.
//   2. DC AND NYQUIST ARE ZEROED, and the region is DC-blocked first. The
//      reference randomises bin 0 like any other; `irfft` keeps only its real
//      part, so the frame gets `|X₀|·cos φ` — a random DC step, changing at the
//      frame rate (≈ 8 Hz at 0.25 s). Zeroing the bin is the C++'s behaviour.
//      The blocker is needed AS WELL because the window's main lobe leaks input
//      DC into bins 1–2, which are then randomised like anything else.
//   3. NO HARD CLAMP. The reference clips to ±1 and says nothing. Here the peak
//      is measured, and if it would exceed the guard the whole buffer is scaled
//      and the scale is REPORTED — distortion nobody is told about is the one
//      reference behaviour this file refuses outright.
//   4. THE PHASES ARE SEEDED. `Math.random()` would make two renders of the
//      same region different sounds and a bug report unreproducible. A seeded
//      xorshift32 makes the output a function of its inputs, which is also what
//      lets a test assert bytes.
//
// PURE. No DOM, no Worker, no AudioBuffer: this module is a function from
// samples to samples, so every property it has can be measured in node.
// ----------------------------------------------------------------------------

import { DcBlocker, dcBlockerPole } from './dcblock';
import { MAX_FFT_SIZE, MIN_FFT_SIZE, RealFft, allocSpectrum } from './fft';
import { stretchWindow, unityRmsGain } from './stretch-window';

/**
 * The phase stream's seed. A constant, not a parameter of the interface: two
 * renders of the same region must sound identical, or "it sounded different
 * the second time" becomes a bug nobody can chase. The value is the golden
 * ratio's fractional part in hex — the usual arbitrary-but-well-mixed choice.
 */
export const STRETCH_SEED = 0x9e37_79b9;

/** Peak the delivered buffer may reach before it is scaled down, linear. −1 dBFS. `(prov.)` */
export const STRETCH_PEAK_GUARD = 0.891_25;

/** Longest render this engine will produce, in seconds of OUTPUT. `(prov.)` — ADR 0023 D1. */
export const STRETCH_CAP_S = 300;

/**
 * The smear settings, in seconds — the window length, exposed (ADR 0023
 * decision 5 as amended 2026-08-23; roadmap Q58).
 *
 * WHAT THE SINGER HEARS. Everything inside one window collapses into a single
 * stationary spectrum, so the window IS the amount of the voice that is frozen.
 * At 0.05 s a vibrato cycle and most of a consonant survive and the result
 * still reads as a slowed voice; at 0.5 s a quarter of a second of singing
 * becomes one chord and the result is a pure, motionless tone — easier to tune
 * against, further from a voice. The reference's 0.25 s sits near the drony
 * end, which is what the owner heard when he called the first build "too
 * drony": it was tuned for stretching ambient music, not for holding a sung
 * note in front of a singer.
 *
 * The frequency side moves the other way, which is why this is a knob and not
 * a constant: a short window means coarse bins (20 Hz at 0.05 s), so each
 * partial becomes a wider noise band and low notes get rough. Long is pure and
 * frozen; short is rough and alive.
 */
export const STRETCH_SMEAR_CHOICES = Object.freeze([0.05, 0.1, 0.25, 0.5] as const);
export type StretchSmearS = (typeof STRETCH_SMEAR_CHOICES)[number];

/**
 * The default. 0.1 s, NOT the reference's 0.25 s. `(prov.)`
 *
 * The owner's decision on 2026-08-23 after hearing 0.25 s: a tenth of a second
 * keeps enough of the voice's movement to still sound like the singer, which
 * is what a drone to sing along to has to do. The reference's value remains
 * one click away.
 */
export const STRETCH_SMEAR_DEFAULT_S: StretchSmearS = 0.1;

/** The reference implementation's own window length, kept as a named landmark. */
export const STRETCH_REFERENCE_SMEAR_S = 0.25;

export function isStretchSmear(value: number): value is StretchSmearS {
  return (STRETCH_SMEAR_CHOICES as readonly number[]).includes(value);
}

/**
 * The analysis window for a rate and a smear: the power of two at or above it.
 *
 * The reference picks a 2/3/5-smooth size instead — 8000 for 0.25 s at 32 kHz
 * — because FFTW is happy with those radices; `RealFft` is radix-2, and
 * rounding UP rather than down keeps the smear at least as long as it was
 * asked for, which is the property the sound depends on. 0.5 s at 48 kHz is
 * 24 000 → 32768, which is why `MAX_FFT_SIZE` moved on the same day.
 */
export function stretchWindowSamplesFor(
  sampleRateHz: number,
  smearS: number = STRETCH_SMEAR_DEFAULT_S,
): number {
  if (!(sampleRateHz > 0) || !Number.isFinite(sampleRateHz)) {
    throw new RangeError(`sample rate must be positive and finite, got ${String(sampleRateHz)}`);
  }
  if (!(smearS > 0) || !Number.isFinite(smearS)) {
    throw new RangeError(`the smear must be a positive number of seconds, got ${String(smearS)}`);
  }
  const n = 2 ** Math.ceil(Math.log2(smearS * sampleRateHz));
  return Math.min(Math.max(n, MIN_FFT_SIZE), MAX_FFT_SIZE);
}

/**
 * xorshift32 — the phase stream.
 *
 * Chosen over `Math.random()` for reproducibility and over a cryptographic
 * generator because nothing here is a secret: what is needed is a stream that
 * is uniform enough that no partial's phase correlates with its neighbour's,
 * and identical on every machine. Seed 0 is refused because it is the
 * generator's fixed point — it would emit zero forever, and every frame would
 * have the same phase, which is a coherent overlap-add wearing a disguise.
 */
export class Xorshift32 {
  private state: number;

  constructor(seed: number) {
    if (!Number.isInteger(seed) || seed === 0) {
      throw new RangeError(`xorshift32 needs a non-zero integer seed, got ${String(seed)}`);
    }
    this.state = seed >>> 0;
  }

  next(): number {
    let x = this.state;
    x ^= x << 13;
    x >>>= 0;
    x ^= x >>> 17;
    x ^= x << 5;
    x >>>= 0;
    this.state = x;
    return x;
  }

  /** The next draw on [0, 1). */
  unit(): number {
    return this.next() / 0x1_0000_0000;
  }
}

export interface StretchParams {
  /** The factor. > 0 and finite; the interface offers 1 … 32. */
  readonly stretch: number;
  /** The analysis window, a power of two in `RealFft`'s range. */
  readonly windowSamples: number;
  /** Carried for the DC blocker's corner and the cap; the stretch arithmetic never reads it. */
  readonly sampleRateHz: number;
  readonly seed: number;
  /** Read the region as a loop (the default for a drone) or as a file with fades at both ends. */
  readonly circular: boolean;
  /** Zero bins 0 and N/2 before the inverse. Frozen true; `false` exists so a test can show the artefact. */
  readonly zeroDcNyquist: boolean;
  /** Run the region through the 20 Hz house blocker first. Frozen true; see the header. */
  readonly dcBlock: boolean;
  /** Output gain. Frozen to `unityRmsGain(w)`; a parameter so a test can set 1. */
  readonly gain: number;
  /** Peak the output may reach before the whole buffer is scaled; 0 disables the guard. */
  readonly peakGuard: number;
}

export interface StretchResult {
  readonly samples: Float32Array;
  readonly inputSamples: number;
  readonly outputSamples: number;
  /** Overlap-add steps run. */
  readonly steps: number;
  /** The largest |sample| BEFORE the guard — reported, never hidden. */
  readonly peakAbs: number;
  /** What the guard did, in dB. 0 when it did not fire. */
  readonly peakGuardDb: number;
}

/** Every frozen default in one object, so a caller states only the factor and the rate. */
export function defaultStretchParams(
  sampleRateHz: number,
  stretch: number,
  smearS: number = STRETCH_SMEAR_DEFAULT_S,
): StretchParams {
  const windowSamples = stretchWindowSamplesFor(sampleRateHz, smearS);
  return {
    stretch,
    windowSamples,
    sampleRateHz,
    seed: STRETCH_SEED,
    circular: true,
    zeroDcNyquist: true,
    dcBlock: true,
    gain: unityRmsGain(stretchWindow(windowSamples)),
    peakGuard: STRETCH_PEAK_GUARD,
  };
}

/**
 * How long the render will be, in samples.
 *
 * Whole overlap-add steps: `M·N/2` with `M = round(L·S/(N/2))`. The reference
 * emits `⌈L/h⌉` steps and discards its last half-window, which leaves a length
 * nobody can predict to the sample; rounding the step count means the duration
 * is `L·S` to within half a hop (≤ 128 ms at 32 kHz, N = 8192) AND the buffer
 * ends exactly where a step does — which is what makes a circular render join
 * itself without a click.
 */
export function stretchOutputLength(inputSamples: number, stretch: number, windowSamples: number): number {
  const hop = windowSamples / 2;
  const steps = Math.max(1, Math.round((inputSamples * stretch) / hop));
  return steps * hop;
}

function checkParams(x: ArrayLike<number>, p: StretchParams): void {
  if (x.length === 0) {
    throw new RangeError('there is nothing to stretch: the region is empty');
  }
  if (!(p.stretch > 0) || !Number.isFinite(p.stretch)) {
    throw new RangeError(`the stretch factor must be positive and finite, got ${String(p.stretch)}`);
  }
  if (!Number.isInteger(p.windowSamples) || (p.windowSamples & (p.windowSamples - 1)) !== 0) {
    throw new RangeError(`the window must be a power of two, got ${String(p.windowSamples)}`);
  }
  if (p.windowSamples < MIN_FFT_SIZE || p.windowSamples > MAX_FFT_SIZE) {
    throw new RangeError(
      `the window must be in [${String(MIN_FFT_SIZE)}, ${String(MAX_FFT_SIZE)}], got ${String(p.windowSamples)}`,
    );
  }
}

/**
 * Render `x` stretched by `p.stretch`.
 *
 * One step, in full: read `N` samples at `⌊m·h⌋` where `h = (N/2)/S` (so the
 * input advances at 1/S of real time), window them, transform, replace every
 * phase with a fresh draw while keeping every magnitude, transform back,
 * window again, and overlap-add at 50 %. `onProgress` is called at most once
 * per second of output; the loop is synchronous, and in the Worker that is
 * exactly what is wanted — there is no main thread to yield to.
 */
export function stretchRender(
  x: Float32Array | Float64Array,
  p: StretchParams,
  onProgress?: (doneSamples: number, totalSamples: number) => void,
): StretchResult {
  checkParams(x, p);

  const n = p.windowSamples;
  const hop = n / 2;
  const inputSamples = x.length;
  const outputSamples = stretchOutputLength(inputSamples, p.stretch, n);
  const steps = outputSamples / hop;
  const h = inputSamples / steps; // the input advance per step: L/M, exactly

  // The region, in float64, DC-blocked once in stream order. Blocking here and
  // not per frame is the point: the blocker has state, and running it over
  // overlapping frames would filter the same samples several times with
  // different histories.
  const source = new Float64Array(inputSamples);
  if (p.dcBlock) {
    const blocker = new DcBlocker(20, p.sampleRateHz);
    // Two passes over a circular region, keeping the second: the first pass
    // gives the filter the history it would have had, so the loop point is not
    // a transient. `dcBlockerPole` is imported for the same reason the chain
    // panel prints it — the corner is ADR 0006 D7's, not a local invention.
    void dcBlockerPole(20, p.sampleRateHz);
    if (p.circular) {
      const warm = new Float64Array(inputSamples);
      blocker.process(x, warm);
    }
    blocker.process(x, source);
  } else {
    for (let i = 0; i < inputSamples; i += 1) {
      source[i] = x[i] as number;
    }
  }

  const w = stretchWindow(n);
  const fft = new RealFft(n);
  const spectrum = allocSpectrum(n);
  const frame = new Float64Array(n);
  const synth = new Float64Array(n);
  const out = new Float64Array(outputSamples);
  const rng = new Xorshift32(p.seed);
  const bins = fft.bins;

  // WHERE THE LOOP POINT'S SECOND CONTRIBUTION COMES FROM. Every output
  // position needs exactly two overlapping frames. In the middle that is steps
  // m and m−1; at the very start it is step 0's first half and the LAST step's
  // second half, which on a circular render wraps round into `[0, hop)` in the
  // overlap-add below. Nothing else is needed — and an extra "priming" step
  // before zero, which the first draft of this file ran, is a THIRD
  // contribution there: measured +2.01 dB on the opening hop against a steady
  // state that was otherwise flat to 0.09 dB. Three incoherent frames instead
  // of two is exactly √(3/2), and it made the loop point the loudest moment in
  // the drone.
  for (let m = 0; m < steps; m += 1) {
    const start = m * h;
    const i = Math.floor(start);

    // --- read and window ---------------------------------------------------
    if (p.circular) {
      for (let j = 0; j < n; j += 1) {
        const index = (((i + j) % inputSamples) + inputSamples) % inputSamples;
        frame[j] = (source[index] as number) * (w[j] as number);
      }
    } else {
      for (let j = 0; j < n; j += 1) {
        const index = i + j;
        frame[j] = index >= 0 && index < inputSamples ? (source[index] as number) * (w[j] as number) : 0;
      }
    }

    // --- magnitudes kept, phases replaced ----------------------------------
    fft.forward(frame, spectrum);
    for (let k = 1; k < bins - 1; k += 1) {
      const re = spectrum[2 * k] as number;
      const im = spectrum[2 * k + 1] as number;
      const magnitude = Math.hypot(re, im);
      const phase = 2 * Math.PI * rng.unit();
      spectrum[2 * k] = magnitude * Math.cos(phase);
      spectrum[2 * k + 1] = magnitude * Math.sin(phase);
    }
    if (p.zeroDcNyquist) {
      spectrum[0] = 0;
      spectrum[1] = 0;
      spectrum[2 * (bins - 1)] = 0;
      spectrum[2 * (bins - 1) + 1] = 0;
    } else {
      // What the reference does, kept only so a test can show the artefact:
      // the inverse ignores the imaginary part, so this is a random-signed DC.
      const dc = Math.abs(spectrum[0] as number);
      const nyq = Math.abs(spectrum[2 * (bins - 1)] as number);
      spectrum[0] = dc * Math.cos(2 * Math.PI * rng.unit());
      spectrum[1] = 0;
      spectrum[2 * (bins - 1)] = nyq * Math.cos(2 * Math.PI * rng.unit());
      spectrum[2 * (bins - 1) + 1] = 0;
    }

    // --- back to time, windowed again, overlap-added -----------------------
    fft.inverse(spectrum, synth);
    const base = m * hop;
    for (let j = 0; j < n; j += 1) {
      const at = base + j;
      if (at < outputSamples) {
        out[at] = (out[at] as number) + p.gain * (w[j] as number) * (synth[j] as number);
      } else if (p.circular) {
        // The last step's tail wraps into the beginning: this is what makes the
        // render join itself.
        const wrapped = at - outputSamples;
        out[wrapped] = (out[wrapped] as number) + p.gain * (w[j] as number) * (synth[j] as number);
      }
    }

    if (onProgress !== undefined && m % Math.max(1, Math.round(p.sampleRateHz / hop)) === 0) {
      onProgress(Math.min(outputSamples, (m + 1) * hop), outputSamples);
    }
  }

  // --- the peak guard, measured then applied, never silent -------------------
  let peakAbs = 0;
  for (const value of out) {
    const magnitude = Math.abs(value);
    if (magnitude > peakAbs) {
      peakAbs = magnitude;
    }
  }
  let peakGuardDb = 0;
  let scale = 1;
  if (p.peakGuard > 0 && peakAbs > p.peakGuard) {
    scale = p.peakGuard / peakAbs;
    peakGuardDb = 20 * Math.log10(scale);
  }

  const samples = new Float32Array(outputSamples);
  for (let i = 0; i < outputSamples; i += 1) {
    samples[i] = (out[i] as number) * scale;
  }
  onProgress?.(outputSamples, outputSamples);

  return { samples, inputSamples, outputSamples, steps, peakAbs, peakGuardDb };
}
