//
// The Canvas2D spectrum line: grid, reference ghost, trace, hold, peak
// markers, clip state.
//
// WHAT THIS FILE MAY AND MAY NOT DO. It may map numbers to pixels. It may not
// change a number: no smoothing (ADR 0006 D8 puts that in linear power, in the
// Worker), no averaging, no re-scaling of dB, no peak of its own — the markers
// it draws are the Worker's `frame.peaks` (and `frame.peak` when that list is
// empty), the harmonic numbers on them are the Worker's `harmonic` labels, and
// the ghost it draws under the trace is the `Reference` the session handed it,
// averaged on the main thread by `app/reference.ts`. A renderer that computed
// anything would be a fourth implementation of a convention, and ADR 0021
// decision 2's star has exactly three arms. Even the label collision rule
// below compares pixel extents, never frequencies.
//
// DRAW ORDER IS MEANING. Reference ghost first, then the hold, then the live
// trace and its markers: the thing the singer is trying to reach sits under
// the thing they are doing now, so the live reading is never hidden by a
// target that was captured earlier. The three lines are also told apart by
// dash pattern, not only hue — reference dotted `[1, 3]`, hold dashed
// `[4, 3]`, live solid — and the markers by fill: hollow for the reference,
// filled for the live peaks. Shape carries "is this a harmonic": a circle for
// a peak the Worker labelled `Hn`, a square for one it did not.
//
// ONE EXCEPTION, FOUND IN THE FIRST SCREENSHOT (2026-08-22): the reference's
// hollow markers and `Hn` labels are painted AFTER the live trace's fill, not
// with the ghost trace. The fill is opaque, and a reference harmonic that is
// quieter than the live one at that frequency sits inside it — the marker and
// its label vanished for exactly the frames where the comparison mattered.
// The ghost TRACE stays underneath (a line under a fill is the right picture);
// its markers are symbols, and a symbol nobody can see is not one.
//
// DROP, NEVER QUEUE, is `render/scheduler.ts`'s — see its header for the
// failure it prevents and for why the rule lives in a module node can test.
// `columnsDrawn` and `columnsDropped` are that scheduler's counters, surfaced
// here because they are two of the numbers ADR 0021 decision 3 requires to be
// reported for the web application's refresh (*measured, never claimed*).
//
// devicePixelRatio. `app.css` stretches the canvas to the panel width; the
// `width`/`height` attributes are the BACKING STORE. If the two disagree the
// browser resamples the drawing, and a resampled 1-pixel-wide spectral peak
// moves — which would make the peak marker disagree with the line it is
// pointing at. `resize()` therefore sets the backing store from the measured
// CSS box times `devicePixelRatio` and scales the context once, so every
// coordinate below is in CSS pixels.
//
// NOTHING IS ENCODED BY COLOUR ALONE (WCAG 2.2 SC 1.4.1, bibliography 03 #23).
// The strongest peak carries its frequency and level as TEXT beside the
// marker, every harmonic carries its `Hn`, the hold trace is dashed as well as
// differently coloured, and the clip state is the word CLIP, not a red pixel.
// Every `--ss-canvas-*` pair is held to WCAG 1.4.3 / 1.4.11 by
// `tests/unit/theme-contrast.test.ts`.
//
// WHY LABELS MAY BE DROPPED BUT MARKERS NEVER ARE. Eight harmonics of a D3 on a
// log axis crowd together above 1 kHz; drawn naively their labels overprint
// into an unreadable smear. The collision rule below keeps ONE running
// `lastLabelRight` per label row (live `Hn` labels above the markers,
// reference labels below) and skips a label whose measured text extent would
// start inside the previous label's extent plus a 4 px gap. The marker is
// still drawn, so the picture stays complete; and every peak's Hz and dB are
// listed in full in the DOM legend (`#peak-legend`), so nothing is LOST by the
// skip — only moved off the canvas.
//
// THE STRONGEST PEAK'S LABEL HAS A ROW OF ITS OWN. It is the long one — `H3 ·
// 660.0 Hz  −27.1 dBFS` — and the first version of this file reserved its
// extent on the `Hn` row, which on a log axis swallowed H4, H5 and H6 on
// every /a/ (the steady-vowel screenshot, 2026-08-22): the three labels a
// singer most wants were the three always missing. So it is drawn one text
// row HIGHER than the `Hn` labels instead. That cannot collide with any of
// them, by construction: the strongest peak is the maximum of the column, so
// every other marker sits at or below it — to within the parabolic
// interpolator's fraction of a decibel, a pixel or two on a 90 dB axis, which
// the row's spare leading absorbs — every `Hn` (six pixels above its own
// marker) sits at or below the strongest's `Hn` height, and the long label is
// a full row above that. No reservation, no arithmetic on data — one more
// pixel offset. (Only a peak within a text row of the ceiling would push the
// long label off the canvas, and the clamp below keeps it on; a note that
// loud is the CLIP word's business, not this label's.)
// ----------------------------------------------------------------------------

import type { Reference } from '../app/reference';
import type { LabelledPeak } from '../dsp/peaks';
import type { FrameMessage } from '../worker/protocol';
import { browserRafHost, createFrameScheduler, type FrameScheduler, type RafHost } from './scheduler';
import { PLOT_GUTTER, axisMapper, frequencyTicks } from './axis';
import { FALLBACK_PALETTE, type SpectrumPalette } from './palette';

/** The axes, from the preset's `display` block. */
export interface SpectrumViewOptions {
  readonly freqMinHz: number;
  readonly freqMaxHz: number;
  readonly freqScale: 'log' | 'linear';
  readonly dbFloor: number;
  readonly dbCeiling: number;
}

export interface SpectrumView {
  /** Submit a frame for the next animation callback. Newest wins; see the scheduler. */
  draw(frame: FrameMessage): void;
  setOptions(options: SpectrumViewOptions): void;
  setPalette(palette: SpectrumPalette): void;
  /**
   * The captured reference to draw under the live trace, or `null` for none.
   * Repaints from the last frame at once; the session passes `null` when the
   * reference is not comparable with the running preset (different N, window
   * or scaling — `app/reference.ts`'s `compatibility`), so the ghost is never a
   * spectrum drawn against axes it was not measured on.
   */
  setReference(reference: Reference | null): void;
  /** Re-measure the CSS box and rebuild the backing store. Call from a ResizeObserver. */
  resize(): void;
  readonly columnsDrawn: number;
  readonly columnsDropped: number;
  /** Animation callbacks per second, rolling. The *measured* refresh of ADR 0021 decision 3. */
  rafHz(): number;
  resetCounters(): void;
  destroy(): void;
}

/**
 * The gutters, in CSS pixels.
 *
 * `left`/`right` are `axis.ts`'s, shared with the spectrogram, the overlay and
 * the axis strip: four panes stacked in one column, one plot rectangle, so a
 * harmonic in this pane sits directly above its stripe in the one below.
 *
 * `bottom` is 6 rather than 22 because the FREQUENCY LABELS MOVED OUT. They are
 * now the axis strip's, drawn once for the whole column with a row of note
 * names beside them, instead of once per pane in Hz only — which is both a
 * duplicate reading and 16 px of a 620 px budget spent twice.
 */
const PADDING = { left: PLOT_GUTTER.left, right: PLOT_GUTTER.right, top: 10, bottom: 6 } as const;

/** dB grid spacing. 10 dB is the interval every level readout in this project is quoted in. */
const DB_GRID_STEP = 10;

/** Marker geometry, CSS pixels. The strongest live peak is the largest; the rest match the reference. */
const MARKER = { strongest: 3.5, other: 2.5, reference: 3 } as const;

/** Minimum horizontal gap between two labels on the same row before the second is skipped. */
const LABEL_GAP_PX = 4;

/** Dash patterns, so the three traces survive a monochrome screenshot (SC 1.4.1). */
const DASH = { reference: [1, 3], hold: [4, 3] } as const;

/** Horizontal/vertical offset of a label from its marker, CSS pixels. */
const LABEL_OFFSET = { x: 8, y: 6 } as const;

/** One text row: the 12 px label font plus leading. The strongest peak's label sits this far above the `Hn` row. */
const LABEL_ROW_PX = 16;

const LABEL_FONT = '12px ui-monospace, "DejaVu Sans Mono", monospace';
const SMALL_LABEL_FONT = '11px ui-monospace, "DejaVu Sans Mono", monospace';

function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

export function createSpectrumView(
  canvas: HTMLCanvasElement,
  palette: SpectrumPalette = FALLBACK_PALETTE,
  options: SpectrumViewOptions,
  host: RafHost = browserRafHost(canvas.ownerDocument.defaultView ?? window),
): SpectrumView {
  // An IIFE rather than `const c = ...; if (c === null) throw;`: the drawing
  // helpers below are hoisted function declarations, and TypeScript does not
  // carry a narrowing from the enclosing flow into them. Typing the binding
  // itself is what makes `context.save()` legal inside `drawGrid`.
  const context = ((): CanvasRenderingContext2D => {
    const found = canvas.getContext('2d');
    if (found === null) {
      throw new Error('this browser did not give a 2d context for the spectrum canvas');
    }
    return found;
  })();

  let currentPalette = palette;
  let currentOptions = options;
  let currentReference: Reference | null = null;
  /** CSS-pixel size of the drawing area, refreshed by `resize()`. */
  let cssWidth = canvas.clientWidth > 0 ? canvas.clientWidth : canvas.width;
  let cssHeight = canvas.clientHeight > 0 ? canvas.clientHeight : canvas.height;
  /**
   * The device-pixel ratio the backing store was actually built with.
   *
   * Owned by `resize()` and read by `paint()`. Deriving it instead — as
   * `canvas.width / cssWidth` — is a trap: those two are only in step AFTER a
   * resize, and before the first one `cssWidth` is the HTML `width` attribute
   * while the backing store is whatever a previous view left. The derived ratio
   * is then wrong, the transform is wrong, and the frame paints at the wrong
   * scale on top of the old one. That is the ghost the light-theme screenshot
   * caught on 2026-08-22: a second `dBFS 0` at the old right edge.
   */
  let backingDpr = 1;

  const plot = (): { x: number; y: number; w: number; h: number } => ({
    x: PADDING.left,
    y: PADDING.top,
    w: Math.max(1, cssWidth - PADDING.left - PADDING.right),
    h: Math.max(1, cssHeight - PADDING.top - PADDING.bottom),
  });

  /**
   * The axis mapped across the current plot rectangle. REBUILT AT THE TOP OF
   * EVERY PAINT, never cached across one: `paint` is the only entry point to
   * every drawing helper below, so a mapper made there cannot go stale, and a
   * mapper made per call would be one closure per BIN — several thousand per
   * frame at N = 4096, on the path whose dropped-column counter is a published
   * measurement.
   */
  let currentMapper = axisMapper(currentOptions, PADDING.left, 1);

  /**
   * Frequency → x, through the ONE mapper.
   *
   * This function used to carry its own copy of the log arithmetic, and the
   * spectrogram carried another that differed at the endpoints. `axis.ts` is
   * now the only place either is written; `axis-and-trace-ring.test.ts` asserts
   * that a spectrum-style call and a spectrogram-style call put 440 Hz on the
   * same pixel.
   */
  function xOf(hz: number): number {
    return currentMapper.xOf(hz);
  }

  /** Level → y. `dbCeiling` at the top, `dbFloor` at the bottom, clamped into the plot. */
  function yOf(db: number): number {
    const { y, h } = plot();
    const { dbFloor, dbCeiling } = currentOptions;
    const t = (dbCeiling - db) / (dbCeiling - dbFloor);
    return y + h * clamp(t, 0, 1);
  }

  function drawGrid(): void {
    const { x, y, w, h } = plot();
    context.save();
    context.font = '11px ui-monospace, "DejaVu Sans Mono", monospace';
    context.textBaseline = 'middle';

    // --- dB, every 10 dB ---------------------------------------------------
    const { dbFloor, dbCeiling } = currentOptions;
    context.strokeStyle = currentPalette.grid;
    context.fillStyle = currentPalette.axisText;
    context.lineWidth = 1;
    const first = Math.ceil(dbFloor / DB_GRID_STEP) * DB_GRID_STEP;
    for (let db = first; db <= dbCeiling; db += DB_GRID_STEP) {
      // +0.5 so a 1-pixel line lands on a pixel rather than across two.
      const yy = Math.round(yOf(db)) + 0.5;
      context.beginPath();
      context.moveTo(x, yy);
      context.lineTo(x + w, yy);
      context.stroke();
      context.textAlign = 'right';
      context.fillText(String(db), x - 6, yy);
    }

    // --- frequency: decades major, 2…9 minor (log) or ten ticks (linear) ----
    //
    // The LINES only. The tick list is `axis.ts`'s (lifted from here, so the
    // spectrogram and the axis strip draw the same decades), and the LABELS are
    // the axis strip's: one row of Hz with a row of note names under it, once
    // for the whole column. A pane that also printed them would be printing a
    // second reading of the same axis a few pixels away from the first.
    for (const tick of frequencyTicks(currentOptions)) {
      const xx = Math.round(xOf(tick.hz)) + 0.5;
      context.strokeStyle = tick.major ? currentPalette.grid : currentPalette.gridMinor;
      context.beginPath();
      context.moveTo(xx, y);
      context.lineTo(xx, y + h);
      context.stroke();
    }

    // Unit labels: a dB axis with no unit is the "silently mixed" readout
    // ADR 0006 D3 forbids, and the unit is per FRAME (dBFS or dBFS/Hz), so it
    // is written by `paint` rather than here.
    context.restore();
  }

  /**
   * One polyline over the bins, reduced to at most one segment per pixel column.
   *
   * The MAXIMUM within a column, not the mean or the first bin: at N = 4096 and
   * an 8 kHz span there are several bins per pixel, and a mean would flatten
   * every narrow peak — the peak marker would then point at a level the trace
   * does not show. Taking the max is the same choice a spectrogram makes and it
   * is a DISPLAY reduction only; nothing downstream reads it.
   */
  function tracePath(frequencyHz: ArrayLike<number>, levelDb: ArrayLike<number>): void {
    const { x, w } = plot();
    const { freqMinHz, freqMaxHz } = currentOptions;
    context.beginPath();
    let started = false;
    let columnX = Number.NaN;
    let columnMax = Number.NEGATIVE_INFINITY;
    const flush = (): void => {
      if (!Number.isNaN(columnX)) {
        const yy = yOf(columnMax);
        if (started) {
          context.lineTo(columnX, yy);
        } else {
          context.moveTo(columnX, yy);
          started = true;
        }
      }
    };
    for (let k = 0; k < levelDb.length; k += 1) {
      const hz = frequencyHz[k] as number;
      if (hz < freqMinHz || hz > freqMaxHz) {
        continue;
      }
      const px = clamp(Math.round(xOf(hz)), x, x + w);
      if (px !== columnX) {
        flush();
        columnX = px;
        columnMax = Number.NEGATIVE_INFINITY;
      }
      const db = levelDb[k] as number;
      if (db > columnMax) {
        columnMax = db;
      }
    }
    flush();
  }

  /**
   * A marker: a circle for a harmonic, a square for anything else, hollow or
   * filled. The shape is the second channel for "is this a harmonic" — the
   * `Hn` text is the first — so the distinction survives a label that the
   * collision rule skipped.
   */
  function marker(px: number, py: number, radius: number, harmonic: boolean, filled: boolean): void {
    context.beginPath();
    if (harmonic) {
      context.arc(px, py, radius, 0, 2 * Math.PI);
    } else {
      context.rect(px - radius, py - radius, 2 * radius, 2 * radius);
    }
    if (filled) {
      context.fill();
    } else {
      context.stroke();
    }
  }

  /** One label row's collision state: `lastRight` walks left to right. */
  interface LabelRow {
    lastRight: number;
  }

  /** May a label spanning `[left, right]` be drawn on this row? Records it if so. */
  function claim(row: LabelRow, left: number, right: number): boolean {
    if (left < row.lastRight + LABEL_GAP_PX) {
      return false;
    }
    row.lastRight = right;
    return true;
  }

  /** The ghost trace alone: dotted, underneath everything. */
  function drawReferenceTrace(reference: Reference): void {
    context.save();
    context.strokeStyle = currentPalette.reference;
    context.lineWidth = 1;
    context.setLineDash([...DASH.reference]);
    tracePath(reference.frequencyHz, reference.levelDb);
    context.stroke();
    context.restore();
  }

  /** The reference's hollow markers and their `Hn` labels (below the markers). Painted over the live fill — see the header. */
  function drawReferenceMarkers(reference: Reference, plotX: number, plotW: number): void {
    context.save();
    context.strokeStyle = currentPalette.reference;
    context.fillStyle = currentPalette.reference;
    context.lineWidth = 1;
    context.font = SMALL_LABEL_FONT;
    context.textBaseline = 'top';
    context.textAlign = 'center';
    const row: LabelRow = { lastRight: Number.NEGATIVE_INFINITY };
    // Left to right, so the running `lastRight` means what it says.
    const ordered = [...reference.peaks].sort((a, b) => a.hz - b.hz);
    for (const p of ordered) {
      const px = xOf(p.hz);
      if (px < plotX || px > plotX + plotW) {
        continue;
      }
      const py = yOf(p.db);
      marker(px, py, MARKER.reference, p.harmonic !== null, false);
      if (p.harmonic === null) {
        continue;
      }
      const text = `H${String(p.harmonic)}`;
      const half = context.measureText(text).width / 2;
      if (claim(row, px - half, px + half)) {
        context.fillText(text, px, py + LABEL_OFFSET.y);
      }
    }
    context.restore();
  }

  /**
   * The live markers and their labels (above the markers). `frame.peaks` when
   * the picker produced any; otherwise the single `frame.peak`, which is the
   * W1 behaviour and what every preset without `peak_markers` still gets.
   */
  function drawLivePeaks(frame: FrameMessage, plotX: number, plotW: number): void {
    context.save();
    context.strokeStyle = currentPalette.peakMarker;
    context.fillStyle = currentPalette.peakMarker;
    context.lineWidth = 1;
    context.font = LABEL_FONT;
    context.textBaseline = 'bottom';

    const peaks: readonly LabelledPeak[] =
      frame.peaks.length > 0 ? frame.peaks : [{ ...frame.peak, prominenceDb: Number.NaN, harmonic: null }];
    const strongest = peaks[0] as LabelledPeak;
    const row: LabelRow = { lastRight: Number.NEGATIVE_INFINITY };

    // The strongest peak first: its label carries BOTH numbers and BOTH units.
    // A marker that only changed colour would encode the reading in the colour
    // (SC 1.4.1), and a level with no unit could be read on the wrong axis
    // (ADR 0006 D3). It is the label the readout strip quotes, and it is drawn
    // one text row above the `Hn` row — its own row, never in their way (the
    // header says why that is safe).
    const sx = xOf(strongest.hz);
    if (sx >= plotX && sx <= plotX + plotW) {
      const sy = yOf(strongest.db);
      marker(sx, sy, MARKER.strongest, strongest.harmonic !== null, true);
      const prefix = strongest.harmonic === null ? '' : `H${String(strongest.harmonic)} · `;
      const label = `${prefix}${strongest.hz.toFixed(1)} Hz  ${strongest.db.toFixed(1)} ${frame.levelUnit}`;
      const width = context.measureText(label).width;
      const flip = sx + width + LABEL_OFFSET.x + LABEL_GAP_PX > plotX + plotW;
      context.textAlign = flip ? 'right' : 'left';
      const anchor = flip ? sx - LABEL_OFFSET.x : sx + LABEL_OFFSET.x;
      // Clamped so a peak at the ceiling keeps its label on the canvas.
      const labelY = Math.max(sy - LABEL_OFFSET.y - LABEL_ROW_PX, LABEL_ROW_PX);
      context.fillText(label, anchor, labelY);
    }

    // The rest, left to right. Harmonics get `Hn`; a non-harmonic peak gets a
    // square and no text — its numbers are in the legend, and a bare frequency
    // above every ripple is the overprint the collision rule exists to stop.
    context.textAlign = 'center';
    const others = peaks.slice(1).sort((a, b) => a.hz - b.hz);
    for (const p of others) {
      const px = xOf(p.hz);
      if (px < plotX || px > plotX + plotW) {
        continue;
      }
      const py = yOf(p.db);
      marker(px, py, MARKER.other, p.harmonic !== null, true);
      if (p.harmonic === null) {
        continue;
      }
      const text = `H${String(p.harmonic)}`;
      const half = context.measureText(text).width / 2;
      if (claim(row, px - half, px + half)) {
        context.fillText(text, px, py - LABEL_OFFSET.y);
      }
    }
    context.restore();
  }

  function paint(frame: FrameMessage): void {
    const { x, y, w, h } = plot();
    currentMapper = axisMapper(currentOptions, x, w);
    context.save();

    // CLEAR THE WHOLE BACKING STORE, not the measured CSS box.
    //
    // `cssWidth`/`cssHeight` are what `resize()` last measured; the backing
    // store is what the browser actually allocated. When those disagree — a
    // paint that ran before the first ResizeObserver callback, a device-pixel
    // ratio change, an element laid out wider than the box we recorded —
    // filling only `cssWidth × cssHeight` leaves everything outside it holding
    // the PREVIOUS frame. It shows up as a ghost: the dBFS axis label drawn
    // twice, once where it belongs and once at the old right edge, which is
    // exactly what the light-theme screenshot caught on 2026-08-22.
    //
    // Resetting the transform is what makes the rectangle mean device pixels;
    // the scale is restored immediately after so every later call stays in CSS
    // pixels.
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.fillStyle = currentPalette.background;
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.scale(backingDpr, backingDpr);

    drawGrid();

    // --- the reference ghost, underneath everything ---------------------------
    if (currentReference !== null && currentReference.levelDb.length > 0) {
      drawReferenceTrace(currentReference);
    }

    // --- hold next, so the live trace is never hidden by it ------------------
    if (frame.holdDb !== null) {
      context.save();
      context.strokeStyle = currentPalette.hold;
      context.lineWidth = 1;
      // Dashed as WELL as coloured: SC 1.4.1 again — the difference between
      // "now" and "loudest so far" must survive a monochrome screenshot.
      context.setLineDash([...DASH.hold]);
      tracePath(frame.frequencyHz, frame.holdDb);
      context.stroke();
      context.restore();
    }

    // --- the trace, and its fill --------------------------------------------
    tracePath(frame.frequencyHz, frame.levelDb);
    context.save();
    context.lineJoin = 'round';
    context.strokeStyle = currentPalette.trace;
    context.lineWidth = 1.5;
    context.stroke();
    context.lineTo(x + w, y + h);
    context.lineTo(x, y + h);
    context.closePath();
    context.fillStyle = currentPalette.traceFill;
    context.fill();
    context.restore();

    // --- the reference's markers, over the fill (header: the exception) ------
    if (currentReference !== null && currentReference.levelDb.length > 0) {
      drawReferenceMarkers(currentReference, x, w);
    }

    // --- the live peaks, labelled --------------------------------------------
    drawLivePeaks(frame, x, w);

    // --- clip -----------------------------------------------------------------
    if (frame.clipped) {
      context.save();
      context.fillStyle = currentPalette.clip;
      context.font = '600 13px ui-monospace, "DejaVu Sans Mono", monospace';
      context.textAlign = 'right';
      context.textBaseline = 'top';
      // The WORD, not a red border: ADR 0021 decision 1 lists the clipping flag
      // as a live overlay, and `live_singing`'s guidance is "clipping is
      // flagged, never tamed" — so it has to be readable, not inferable.
      context.fillText('CLIP', x + w, y);
      context.restore();
    }

    // --- the level unit, once, where the dB labels are -----------------------
    context.save();
    context.fillStyle = currentPalette.axisText;
    context.font = '11px ui-monospace, "DejaVu Sans Mono", monospace';
    context.textAlign = 'left';
    context.textBaseline = 'top';
    context.fillText(frame.levelUnit, 4, 2);
    context.restore();

    context.restore();
  }

  const scheduler: FrameScheduler<FrameMessage> = createFrameScheduler<FrameMessage>((frame) => {
    paint(frame);
  }, host);

  function resize(): void {
    const view = canvas.ownerDocument.defaultView;
    const dpr = view?.devicePixelRatio ?? 1;
    backingDpr = dpr;
    const measuredWidth = canvas.clientWidth;
    const measuredHeight = canvas.clientHeight;
    cssWidth = measuredWidth > 0 ? measuredWidth : cssWidth;
    cssHeight = measuredHeight > 0 ? measuredHeight : cssHeight;
    const backingWidth = Math.max(1, Math.round(cssWidth * dpr));
    const backingHeight = Math.max(1, Math.round(cssHeight * dpr));
    if (canvas.width !== backingWidth || canvas.height !== backingHeight) {
      canvas.width = backingWidth;
      canvas.height = backingHeight;
    }
    // Reset before scaling: setting width/height already clears the transform,
    // but `resize()` is also called on a dpr change alone, where it has not.
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.scale(dpr, dpr);
    const last = scheduler.last;
    if (last !== null) {
      // Repaint immediately rather than waiting for the next frame: a resize
      // clears the backing store, and a paused or slow stream would leave the
      // panel blank for as long as it took the next hop to arrive.
      paint(last);
      return;
    }
    // No frame yet — but the canvas may not be empty. Stopping capture and
    // starting it again builds a NEW view over the SAME element, and whatever
    // the previous one painted is still there until the first hop arrives. Fill
    // it now, in this palette, so the gap reads as "not started" rather than as
    // a stale reading someone might believe.
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.fillStyle = currentPalette.background;
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.scale(dpr, dpr);
  }

  resize();

  return {
    draw(frame: FrameMessage): void {
      scheduler.submit(frame);
    },
    setOptions(next: SpectrumViewOptions): void {
      currentOptions = next;
      const last = scheduler.last;
      if (last !== null) {
        paint(last);
      }
    },
    setPalette(next: SpectrumPalette): void {
      currentPalette = next;
      const last = scheduler.last;
      if (last !== null) {
        paint(last);
      }
    },
    setReference(reference: Reference | null): void {
      currentReference = reference;
      const last = scheduler.last;
      if (last !== null) {
        paint(last);
      }
    },
    resize,
    get columnsDrawn(): number {
      return scheduler.drawn;
    },
    get columnsDropped(): number {
      return scheduler.dropped;
    },
    rafHz: () => scheduler.rafHz(),
    resetCounters: () => {
      scheduler.resetCounters();
    },
    destroy(): void {
      scheduler.cancel();
    },
  };
}
