//
// One frequency axis, shared by every pane that has one.
//
// The spectrum, the spectrogram, the overlay drawn on top of it and the axis
// strip between them all have to agree about where 440 Hz is — to the pixel,
// or a harmonic sits beside its own marker and a reference lane sits beside the
// note it is drawn for. Before this file each pane computed its own `xOf`, and
// two of them disagreed: `spectrum-view` mapped `hz → x` from the plot box
// while `waterfall-view` mapped `column index → hz` as `i/(N−1)`, which is the
// edge of the first texel and the edge of the last, not their centres.
//
// So there is one mapper, everyone calls it, and the tests assert that a
// spectrum-style call and a waterfall-style call with the same plot rectangle
// return the same x for the same frequency. The gutters are here too, for the
// same reason: a pane that reserved a different left margin would be aligned
// with nothing.
// ---------------------------------------------------------------------------

import { A4_HZ, noteHz } from '../dsp/cents';

/** The frequency span and scale a preset asks for. */
export interface FrequencyAxis {
  readonly freqMinHz: number;
  readonly freqMaxHz: number;
  readonly freqScale: 'log' | 'linear';
}

/**
 * The margins every pane reserves, in CSS pixels. `left` is where the
 * spectrum's dB labels live; every other pane leaves it empty (or draws a
 * label of its own in it) so the plot rectangles line up.
 */
export const PLOT_GUTTER = Object.freeze({ left: 46, right: 10 });

/** Width of the plot rectangle inside a canvas of `cssWidth`. */
export function plotWidthFor(cssWidth: number): number {
  return Math.max(1, cssWidth - PLOT_GUTTER.left - PLOT_GUTTER.right);
}

export interface AxisMapper {
  readonly plotLeft: number;
  readonly plotWidth: number;
  /** Frequency → CSS x. */
  xOf(hz: number): number;
  /** Frequency → position in [0, 1] across the plot. */
  fractionOf(hz: number): number;
  /** The inverse: a position in [0, 1] → frequency. */
  hzAt(fraction: number): number;
}

export function axisMapper(axis: FrequencyAxis, plotLeft: number, plotWidth: number): AxisMapper {
  const lo = Math.log10(Math.max(axis.freqMinHz, 1e-6));
  const hi = Math.log10(Math.max(axis.freqMaxHz, axis.freqMinHz + 1e-6));
  const log = axis.freqScale === 'log';

  const fractionOf = (hz: number): number =>
    log
      ? (Math.log10(Math.max(hz, 1e-6)) - lo) / (hi - lo)
      : (hz - axis.freqMinHz) / (axis.freqMaxHz - axis.freqMinHz);

  return {
    plotLeft,
    plotWidth,
    fractionOf,
    xOf: (hz) => plotLeft + plotWidth * fractionOf(hz),
    hzAt: (t) => (log ? 10 ** (lo + t * (hi - lo)) : axis.freqMinHz + t * (axis.freqMaxHz - axis.freqMinHz)),
  };
}

/** Minor ticks inside a decade: the 2…9 of a log axis. */
const DECADE_MINORS = [2, 3, 4, 5, 6, 7, 8, 9] as const;

export interface Tick {
  readonly hz: number;
  readonly major: boolean;
  /** What to print, or `null` for a tick that is drawn but not labelled. */
  readonly label: string | null;
}

/** Hz ticks — decades major on a log axis, ten steps on a linear one. Lifted from `spectrum-view`. */
export function frequencyTicks(axis: FrequencyAxis): Tick[] {
  const out: Tick[] = [];
  const label = (hz: number): string => (hz >= 1000 ? `${String(hz / 1000)}k` : String(Math.round(hz)));
  if (axis.freqScale === 'log') {
    const firstDecade = Math.floor(Math.log10(Math.max(axis.freqMinHz, 1e-6)));
    const lastDecade = Math.ceil(Math.log10(axis.freqMaxHz));
    for (let d = firstDecade; d <= lastDecade; d += 1) {
      const decade = 10 ** d;
      out.push({ hz: decade, major: true, label: label(decade) });
      for (const m of DECADE_MINORS) {
        out.push({ hz: decade * m, major: false, label: null });
      }
    }
  } else {
    const step = (axis.freqMaxHz - axis.freqMinHz) / 10;
    for (let i = 0; i <= 10; i += 1) {
      const hz = axis.freqMinHz + i * step;
      out.push({ hz, major: i % 2 === 0, label: i % 2 === 0 ? label(hz) : null });
    }
  }
  return out.filter((t) => t.hz >= axis.freqMinHz && t.hz <= axis.freqMaxHz);
}

/**
 * Note ticks: every semitone a minor, every C a labelled major.
 *
 * A singer reading `261.6 Hz` is doing arithmetic mid-phrase. Every analyzer
 * that singers actually use offers a musical axis — Sing&See draws its pitch
 * trace on a keyboard, `woheller69/audio-analyzer` ships a note axis beside
 * its linear and log ones — and the note names cost one row of the strip.
 */
export function noteTicks(axis: FrequencyAxis, a4Hz: number = A4_HZ): Tick[] {
  const out: Tick[] = [];
  // MIDI 12 is C0 at 16.35 Hz; 127 is G9. Walk the whole range and filter.
  for (let midi = 12; midi <= 127; midi += 1) {
    const hz = noteHz(midi, a4Hz);
    if (hz < axis.freqMinHz || hz > axis.freqMaxHz) {
      continue;
    }
    const isC = ((midi % 12) + 12) % 12 === 0;
    out.push({ hz, major: isC, label: isC ? `C${String(Math.floor(midi / 12) - 1)}` : null });
  }
  return out;
}
